UPDATE dict_terms SET full_desc='<p>임플란트는 빠진 치아 자리에 ‘인공 치아 뿌리’를 뼈에 심고 그 위에 보철(인공치아)을 연결해 자연치아처럼 씹고 보이도록 회복하는 치료입니다. 티타늄 재질의 인공뿌리는 뼈와 단단히 붙어 저작력을 회복해주고, 주변 건강한 치아를 깎지 않아도 된다는 장점이 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>임플란트의 핵심은 뼈와의 결합(골유착)입니다. 티타늄 기둥이 턱뼈에 안정적으로 고정되면 그 위에 지대주와 보철을 올려 자연치아와 유사한 기능과 심미성을 제공합니다. 최근에는 CBCT와 구강스캐너 기반의 디지털 가이드를 사용해 위치와 각도를 정밀하게 계획합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>단일치아 또는 다수 치아 상실 시</li>
  <li>부분틀니·완전틀니가 불편하거나 유지가 어려울 때</li>
  <li>인접 치아를 손상시키지 않고 지대를 보존하고 싶을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>충분한 뼈가 필요해 경우에 따라 뼈이식을 할 수 있고, 시술 후 골유착 기간(수주~수개월)이 필요합니다. 흡연·조절되지 않는 당뇨 등은 성공률에 영향을 주므로 사전 평가가 중요합니다. 유지관리를 위해 정기검진과 구강위생 관리가 필요하며, 보다 안전한 계획을 위해 이음치과에서는 CBCT와 구강스캐너 기반의 디지털 가이드를 활용합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='implant';
UPDATE dict_terms SET full_desc='<h3>픽스처란 무엇인가요?</h3>
<p>픽스처는 턱뼈 속에 식립하는 나사 모양의 인공 치근으로, 인공 치아를 단단히 지지하는 임플란트의 핵심 부품입니다. 주로 티타늄이나 지르코니아로 제작되며 수술로 뼈에 넣어 골유착(뼈와의 결합)이 이루어지면 보철물을 안정적으로 받을 수 있는 기반이 됩니다. 이음치과에서 임플란트 계획 시 가장 먼저 고려되는 요소입니다.</p>

<h3>원리 또는 특징</h3>
<p>픽스처 표면은 골유착을 촉진하도록 미세처리되어 있고, 길이와 직경이 다양해 환자의 골 상태와 해부학적 위치에 맞춰 선택합니다. 티타늄은 생체적합성과 내구성이 높아 널리 쓰이며, 금속에 민감한 경우 지르코니아계 픽스처를 고려할 수 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>단일치아 또는 여러 치아가 빠져 자연치의 기능을 대체할 때</li>
  <li>부분 또는 전체 틀니의 유지력을 개선하고자 할 때</li>
  <li>교합 안정성과 저작 기능 회복이 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>식립 후 골유착까지 보통 3~6개월이 필요하며, 흡연·당뇨·골밀도 등 전신 상태가 성공률에 영향을 줍니다. 시술 전 정밀검사(방사선·CT)가 필요하고, 드물게 실패나 재수술이 필요할 수 있으므로 담당의와 충분히 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='fixture';
UPDATE dict_terms SET full_desc='<p>어버트먼트는 뼈 속에 심어진 임플란트(픽스처)와 위에 올리는 크라운이나 브릿지 같은 보철물을 연결해 주는 중간 부품입니다. 잇몸 높이와 보철물의 방향에 맞춰 표준형 또는 맞춤형으로 제작되며, 보철의 위치와 심미성, 잇몸과의 맞물림을 결정하는 핵심 요소입니다.</p>

<h3>원리 또는 특징</h3>
<p>주로 티타늄이나 지르코니아로 만들며, 스크류로 체결하는 방식과 시멘트로 고정하는 방식이 있습니다. 어버트먼트의 형태와 각도는 보철물의 위치를 조정하고 잇몸의 ''출구 모양(emergence profile)''을 만들어 치아처럼 보이게 합니다. 각도 보정용 어버트먼트는 삽입 각도가 불리할 때 사용합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>단일 치아 임플란트에 크라운을 연결할 때</li>
  <li>여러 임플란트를 연결해 브릿지 보철을 만들 때</li>
  <li>잇몸 높이·치열 각도 조정이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>어버트먼트 선택은 심미성과 청결 관리에 영향을 줍니다. 체결부의 느슨해짐이나 나사 파손을 예방하려면 정기 점검이 필요하며, 색과 재질은 앞니 심미성에 중요한 요소입니다. 궁금한 점은 이음치과에서 상담을 받아 맞춤형 옵션을 확인하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='abutment';
UPDATE dict_terms SET full_desc='<p>골유착은 티타늄 임플란트 표면에 새로운 뼈가 자라 임플란트와 뼈가 하나로 단단히 결합되는 생물학적 과정입니다. 수술로 얻은 초기 고정성 위에 뼈세포가 자라면서 안정성이 증가하고, 이 안정성이 확보된 뒤에 최종 보철물을 올려 기능을 회복하게 됩니다.</p>

<h3>원리 또는 특징</h3>
<p>임플란트 표면에 골아세포가 부착되어 골형성과 재형성이 일어납니다. 티타늄은 생체친화성이 좋아 염증 없이 뼈와 잘 붙고, 초기에는 기계적 안정성, 이후에는 생물학적 골유착이 핵심입니다. 회복 기간은 부위에 따라 다르며 <strong>하악 약 2~3개월, 상악 약 4~6개월</strong>이 일반적입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>단일 치아 상실 후 기능·심미 회복</li>
  <li>여러 치아 결손으로 고정성 보철이 필요할 때</li>
  <li>무치악 환자의 틀니 안정성 개선(오버덴처)</li>
  <li>발치 후 즉시 또는 지연 식립을 계획할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>흡연·당뇨·구강위생 불량은 골유착을 방해하므로 관리가 중요합니다. 골량이 부족하면 골이식이 필요할 수 있고, 성공률은 높지만 100%는 아닙니다. 개인 상태에 따라 이음치과에서 적절한 시기와 계획을 세워 진행합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='osseointegration';
UPDATE dict_terms SET full_desc='<p>골이식은 임플란트를 심을 때 잇몸뼈의 높이와 폭이 부족한 부위를 보강해 임플란트가 안정적으로 자리잡을 수 있는 뼈 환경을 만드는 치료입니다. 자가골, 이종골(동물유래), 동종골(사람유래), 합성골 등 여러 이식재를 쓰며 필요에 따라 상악동 거상술(사이너스 리프트)을 병행하기도 합니다. 이음치과에서는 환자 상태에 맞는 재료와 시기를 판단합니다.</p>

<h3>원리 또는 특징</h3>
<p>이식재는 주변 골조직과 서서히 결합되며 일부는 새로운 뼈로 치환됩니다. 자가골은 골유합력이 우수하지만 별도 채취가 필요하고, 이종골·합성골은 수술이 비교적 간단하고 공급이 용이합니다. 이식부를 보호하기 위해 흡수성 막을 사용하기도 합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
<li>임플란트 식립을 위해 잇몸뼈의 높이나 폭이 부족할 때</li>
<li>치조골 흡수로 인해 잇몸뼈가 얇아진 경우</li>
<li>상악동과 근접해 충분한 길이가 확보되지 않을 때(사이너스 리프트)</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>골이식 후 완전한 골화까지 수개월이 걸려 임플란트 시기를 단계적으로 결정합니다. 흡연이나 조절되지 않는 당뇨 등은 실패 위험을 높이므로 사전 상담과 전신 상태 관리가 중요합니다. 드물게 감염이나 이식재 노출이 생길 수 있어 정기적 경과 관찰이 필요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='bone-graft';
UPDATE dict_terms SET full_desc='<h3>상악동 거상술이란</h3>
<p>위턱 어금니 위쪽에 있는 상악동(부비동)의 바닥 점막을 위로 들어올려 그 공간에 골이식재를 채워 넣어 임플란트를 지지할 충분한 뼈 높이를 만드는 수술입니다. 뼈가 부족해 임플란트 식립이 어려운 경우 미리 뼈를 보충하는 목적으로 시행하며, 환자 상태에 따라 임플란트를 동시에 심거나 나중에 하는 방법이 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>상악동 내 점막(슈나이더막)을 신중히 들춰 올려 생긴 빈 공간에 자가골·동종골·이종골·합성골 등 골이식재를 채우면 골유착을 통해 뼈 높이가 증가합니다. 접근 방식은 측방창을 내는 측방접근법과 치조정으로 접근하는 치조정접근법(오스테오톰)이 있어 환자 골량과 해부학에 따라 선택합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>위턱 어금니 부위의 골높이가 임플란트에 부족할 때</li>
  <li>오랜 시간 후 발치로 인해 치조골이 심하게 흡수된 경우</li>
  <li>임플란트 동시 식립 보조나 연속적인 골보충이 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치료 전 CT로 상악동 해부를 정확히 확인해야 하고, 시술은 보통 국소마취나 진정하에 진행됩니다. 수술 후 일시적 코막힘·부기·출혈이 생길 수 있고, 점막 천공이 가장 흔한 합병증입니다. 흡연이나 만성 부비동 질환은 회복에 영향을 주므로 사전상담이 중요하며, 이음치과와 같은 전문의 상담으로 개별 계획을 세우는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='sinus-lift';
UPDATE dict_terms SET full_desc='<p>즉시 임플란트는 발치와 동시에 같은 자리에 인공치근을 심아 치유 기간과 수술 횟수를 줄이는 치료법입니다. 발치 후 빈 공간에 바로 식립해 잇몸 형태를 보존하고 빠르게 임시보철을 올릴 수 있으나, 초기 고정력과 주변 뼈·잇몸 상태가 양호해야 성공률이 높습니다.</p>

<h3>원리 또는 특징</h3>
<p>발치 후 즉시 식립하면 치조골과 연조직의 소실을 줄이고 심미성을 확보하기 유리합니다. 임플란트가 초기 안정성을 얻지 못하면 골이식이나 수차례의 치유기간이 필요할 수 있고, 간혹 즉시 임시보철을 연결해 기능과 심미를 유지합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>앞니 등 심미성이 중요한 부위에서 빠른 복원이 필요할 때</li>
  <li>치조골 두께와 높이가 충분해 초기 안정성이 확보되는 경우</li>
  <li>국소 감염이 없고 전신 상태(당뇨·흡연 등)가 안정적일 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>모든 경우에 적용되는 것은 아닙니다. 급성 감염, 부족한 골량, 과도한 흡연이나 조절되지 않은 전신질환이 있으면 지연 식립이 더 안전합니다. 시술 전 CBCT로 정확한 평가가 필요하며, 일부 환자에서는 골이식이나 연조직 재건이 병행됩니다. 이음치과와 상의해 개별적 적합성을 판단하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='immediate-implant';
UPDATE dict_terms SET full_desc='<p>디지털 가이드는 환자의 구강과 뼈 정보를 바탕으로 임플란트의 위치·각도·깊이를 컴퓨터에서 미리 설계한 뒤, 그 설계대로 구강에 맞게 제작한 맞춤형 수술 안내 장치입니다. CBCT 영상과 구강스캐너 데이터를 합성해 가상으로 최적 위치를 결정하고 3D 프린터로 가이드를 만듭니다. 이음치과에서는 원내에서 직접 설계·제작합니다.</p>

<h3>원리 또는 특징</h3>
<p>CBCT로 얻은 골 구조와 구강스캔의 치아·연조직을 정합해 가상의 임플란트를 배치합니다. 설계된 경로에 맞춰 구멍이 있는 가이드를 수술 부위에 장착하면 드릴이 계획된 각도와 깊이로만 움직이게 되어 정확도가 향상되고 수술 시간이 줄어듭니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>심미성이 중요한 앞니 부위나 좁은 공간에 식립할 때</li>
  <li>즉시 보철(임플란트 즉시 장착)을 계획할 때</li>
  <li>복잡한 해부 구조를 피해 안전하게 시술해야 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>정확도를 높여 주지만 영상 품질·스캔 오차·가이드 적합성에 따라 차이가 날 수 있어 의사의 임상 판단이 필요합니다. 추가 비용과 제작 시간이 들며, 수술 중 상황 변화가 있으면 계획을 수정해야 할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='digital-guide';
UPDATE dict_terms SET full_desc='<p>오스템(Osstem Implant)은 국내에서 개발된 대표적인 치과임플란트 제품군으로, 다양한 식립형태와 크기, 임상자료를 바탕으로 널리 사용되는 브랜드입니다. 전 세계 시장에서도 점유율이 높은 편이며, 여러 임상 환경에서 검증된 설계와 재료를 통해 인공치근 역할을 합니다. 이음치과에서도 해당 브랜드를 사용합니다.</p>

<h3>원리 또는 특징</h3>
<p>임플란트는 티타늄 등 생체친화적 재료로 만들어져 잇몸뼈와 결합(골유착)을 목표로 합니다. 오스템은 표면처리와 나사형·테이퍼형 등 다양한 형상을 제공해 초기 안정성과 장기적 골유착을 높이는 설계를 적용합니다. 규격과 수술키트, 디지털 가이드와의 호환성도 장점입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>단일치 결손으로 자연치 외형과 기능을 회복할 때</li>
  <li>여러 치아를 잃어 브리지 대신 임플란트가 필요할 때</li>
  <li>무치악(치아가 모두 없는 경우)의 고정성 보철 치료</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>브랜드 선택은 중요하지만 시술자의 경험, 골질·골량, 전신건강(흡연·당뇨 등)이 성공에 큰 영향을 줍니다. 시술 전 구강촬영과 정확한 치료계획이 필요하며, 임플란트 후 유지관리와 정기검진을 통해 장기적 기능을 확보해야 합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='osstem';
UPDATE dict_terms SET full_desc='<h3>네비게이션 임플란트란?</h3>
<p>네비게이션 임플란트는 수술 중에 드릴과 임플란트 위치를 컴퓨터 화면의 3차원(3D)으로 실시간 추적해 계획한 위치에 정확히 식립하도록 돕는 장비·기법입니다. 미리 촬영한 CBCT 영상과 연동해 계획을 구현하고, 실제 수술에서 오차를 줄여 안전하고 예측 가능한 결과를 목표로 합니다.</p>

<h3>원리 또는 특징</h3>
<p>CBCT로 얻은 3D 영상 위에 임플란트 위치를 가상으로 계획하고, 광학·전자 추적 장치가 수술 중 드릴의 위치를 센싱해 화면에 표시합니다. 덕분에 깊이·각도·근심 원심 위치를 즉시 확인할 수 있고, 최소 절개로 식립하거나 인접 구조(신경·상악동)를 보호하기 쉽습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>턱뼈의 해부학적 구조가 복잡하거나 중요한 신경·혈관 근처에 식립할 때</li>
  <li>골이식 등 동반 수술로 정확도가 특히 요구되는 경우</li>
  <li>즉시 기능을 위해 정확한 위치가 필요한 전치부 보철 계획 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>정확도를 높이는 유용한 기술이지만, 장비와 술자의 숙련도에 따라 차이가 있으며 계획·보정 과정이 필요합니다. 작은 위치 오차는 여전히 발생할 수 있고 비용이 추가될 수 있습니다. 이음치과와 같은 전문 의료기관에서 충분한 상담과 계획을 받은 뒤 결정하는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='navigation-implant';
UPDATE dict_terms SET full_desc='<p>전악 임플란트는 한쪽 위턱이나 아래턱의 모든 치아를 인공치근(임플란트)과 그 위에 연결한 고정형 보철로 다시 만드는 치료입니다. 보통 4~8개의 임플란트를 골격으로 삼아 하나의 견고한 보철을 결합해 씹는 기능과 심미를 회복합니다.</p>

<h3>원리 또는 특징</h3>
<p>잇몸뼈에 티타늄 임플란트를 심어 뼈와 결합시키고, 그 위에 금속·레진 혼합 보철을 고정합니다. All‑on‑4, All‑on‑6처럼 임플란트 수와 배열로 즉시 장착 가능 여부가 달라지며, 컴퓨터 단층촬영(CT)로 미리 계획합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>한 악궁의 대부분 또는 전치열을 상실했을 때</li>
  <li>탈착식 의치로 불편을 느끼거나 안정성이 낮을 때</li>
  <li>많은 치아가 치주질환·우식으로 보존 불가능할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>골량 부족 시 골이식이나 상악동 거상술이 필요할 수 있고, 수술 후 몇 개월의 유착 기간과 정기적 관리가 중요합니다. 치료 계획과 비용, 기대 결과는 이음치과에서 자세히 상담받으시길 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='full-arch-implant';
UPDATE dict_terms SET full_desc='<h3>미니 임플란트란</h3>
<p><strong>미니 임플란트</strong>는 지름이 2~3mm로 작은 형태의 치과용 임플란트입니다. 뼈가 얇아 일반 임플란트를 바로 식립하기 어려운 부위나 틀니의 고정력을 높이기 위해 쓰이며, 교정치료에서 일시적 고정원으로도 활용됩니다. 시술이 비교적 간단하고 회복이 빠른 편입니다.</p>

<h3>원리 또는 특징</h3>
<p>티타늄 소재의 작은 나사 모양을 잇몸과 잇몸뼈에 삽입해 기계적 고정을 얻습니다. 직경이 작아 최소한의 골량으로도 식립이 가능하고, 즉시 부하를 걸어 틀니를 고정하는 경우가 많습니다. 다만 하중을 분산시키는 능력이 일반 임플란트보다 낮습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>턱뼈 폭이 좁아 일반 임플란트가 어려운 경우</li>
  <li>부분·총틀니의 유지력 향상이 필요할 때</li>
  <li>교정치료 중 일시적 고정원이 필요할 때</li>
  <li>짧은 시술 시간과 빠른 회복을 원할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>미니 임플란트는 간단하지만 하중 한계가 있어 큰 어금니 교체용으로는 적합하지 않습니다. 청결 관리와 정기검진이 중요하며, 문제 발생 시 제거나 교체가 비교적 쉽습니다. 상세한 적응증 판단은 이음치과와 상담해 결정하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='mini-implant';
UPDATE dict_terms SET full_desc='<h3>임플란트 주위염이란</h3>
<p>임플란트 주위염은 인공치근(임플란트)을 둘러싼 잇몸과 그것을 지지하는 뼈에 세균이 침투해 염증과 골 소실이 진행되는 상태를 말합니다. 자연치의 치주염과 비슷하게 시작되지만 임플란트는 한 번 손상되면 회복이 제한될 수 있어 조기 발견과 관리가 매우 중요합니다. 방치하면 임플란트 고정력이 약해져 실패로 이어질 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>임플란트 표면이나 보철물 가장자리에 쌓인 치태·치석 속 세균이 잇몸에 염증을 일으키고, 염증이 뼈로 확산되면 골 소실이 발생합니다. 흡연·당뇨 같은 전신적 요인, 과도한 교합력, 보철 설계나 시멘트 잔류 등이 위험을 높입니다. 자연치와 해부학적 차이로 예방과 정기 관리의 중요성이 큽니다.</p>

<h3>관련 상황</h3>
<ul>
<li>임플란트 주변 잇몸이 붓거나 출혈이 있을 때</li>
<li>임플란트 주변에 지속적 통증이나 냄새가 날 때</li>
<li>과거 중증 치주염 병력·흡연·조절되지 않는 당뇨가 있는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단은 임상 소견과 방사선 검사로 하며, 경미하면 전문적 스케일링·약물 치료로 통제할 수 있으나 진행되면 수술적 제거·재생술이 필요할 수 있습니다. 올바른 구강위생과 정기적인 전문관리로 예방이 가능하며, 자세한 상담은 이음치과에서 받으실 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='peri-implantitis';
UPDATE dict_terms SET full_desc='<p>힐링 어버트먼트는 임플란트 수술 직후 임플란트 지대주에 임시로 연결해 잇몸(치은)의 모양을 자연스럽게 잡아주는 장치입니다. 최종 보철물을 올리기 전까지 잇몸이 안정된 형태로 치유되도록 유도하고, 인상(틀을 뜨는) 과정과 보철 디자인을 수월하게 합니다.</p>

<h3>원리 또는 특징</h3>
<p>임플란트 상부에 나사로 고정되어 연조직이 주변에 눌려 적절한 치은 형태를 만들게 합니다. 형태가 유지되면 보철물의 경계(출구부·emergence profile)가 자연스럽고 심미적으로 만들어집니다. 영구 부품이 아니며, 필요 시 교체하거나 제거합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>임플란트 식립 후 잇몸 형태를 유지하거나 재형성해야 할 때</li>
  <li>2차 수술(덮개 제거) 후 연조직 치유를 유도할 때</li>
  <li>최종 보철 전 임시 형태로 인상 채득이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>힐링 어버트먼트는 짧은 기간 사용되는 임시 부속품으로, 청결을 잘 유지하고 과도한 힘은 피하는 것이 중요합니다. 때때로 불편감이나 염증이 생길 수 있어 정기 검진이 필요합니다. 자세한 계획은 이음치과의 상담을 통해 결정됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='healing-abutment';
UPDATE dict_terms SET full_desc='<p><strong>GBR(골유도재생술)</strong>은 임플란트 식립이나 치조골 결손을 치료할 때 부족한 뼈를 인공·자가 골이식재로 채운 뒤 차폐막으로 덮어 연조직 침입을 막고 뼈세포가 자라게 하는 수술입니다. 목표는 잇몸뼈의 높이와 폭을 회복해 안정적인 임플란트 지지 기반을 만드는 것입니다.</p>

<h3>원리 또는 특징</h3>
<p>차폐막은 빠르게 자라는 연조직을 차단해 상대적으로 느리게 자라는 뼈가 공간을 채우도록 돕습니다. 이식재는 자가골, 동종·이종·합성골 등 다양한 소재가 쓰이며, 흡수성 또는 비흡수성 막을 선택합니다. 공간유지와 봉합의 밀폐가 성공에 중요하며 치유에는 수개월이 걸립니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>임플란트 식립을 위해 잇몸뼈의 높이·폭이 부족할 때</li>
  <li>발치 후 치조골 보존이 필요할 때</li>
  <li>임플란트 주변 골결손(주위결손)이나 골융합 부족한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치유 기간이 길고 감염이나 막 노출 시 실패 위험이 있으므로 충분한 구강관리와 정기 관찰이 필요합니다. 비흡수성 막은 제거가 필요한 반면 흡수성은 추가 수술이 적지만 선택 기준이 다릅니다. 자세한 검토와 치료계획은 이음치과에서 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gbr';
UPDATE dict_terms SET full_desc='<p>크라운은 손상되거나 약해진 치아의 형태와 기능을 회복하기 위해 치아 전체를 감싸는 맞춤 보철물입니다. 치아 일부를 다듬어 기둥처럼 만든 뒤 인상이나 디지털 스캔으로 제작해 시멘트로 고정합니다. 이음치과에서는 환자 상태에 따라 심미성과 강도를 고려한 재료로 맞춤 제작합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 전체를 덮어 외부 충격과 세균 침투를 차단하고 씹는 힘을 분산시켜 파절을 예방합니다. 재료는 금, PFM(도재), 지르코니아, 올세라믹 등으로 강도·심미성·치아 삭제량에서 차이가 납니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>광범위 충전이나 고도 손상으로 충전만으로 회복이 어려울 때</li>
  <li>신경치료(근관치료) 후 약해진 치아 보호가 필요할 때</li>
  <li>치아 균열·심한 마모로 기능 회복이 필요할 때</li>
  <li>심미적 개선이나 교합(물림) 재조정이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>재료에 따라 비용·심미성·내구성이 달라지며, 시술 전 치아 삭제량과 장기 관리(양치, 치석 제거, 정기검진)가 수명에 영향을 줍니다. 시술 후 민감증이나 교합 조정이 필요할 수 있으며, 완전 무균 상태를 유지해야 충치 재발을 줄일 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='crown';
UPDATE dict_terms SET full_desc='<h3>라미네이트란?</h3>
<p>라미네이트는 치아 앞면을 0.3~0.5mm 정도 얇게 다듬은 뒤, 얇은 세라믹 껍질(쉘)을 접착제로 붙여 색과 모양을 바꾸는 심미 보철입니다. 미세한 색 변색이나 틈새, 작은 깨짐을 자연스럽게 개선하면서 치아 전체 인상을 밝게 만드는 방법으로, 보철적 심미 개선을 원할 때 흔히 선택됩니다.</p>

<h3>원리 또는 특징</h3>
<p>세라믹은 빛 투과성이 좋아 자연 치아와 유사한 미백 효과를 냅니다. 치아 표면의 에나멜에 강력한 접착제를 사용해 붙이므로 보존적 처치이고, 준비량이 적어 구조를 많이 손상시키지 않는 편입니다. 색과 형태를 맞추기 위해 시적 조정과 색상 선택이 중요합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>심한 변색으로 미백만으로 개선되지 않는 경우</li>
  <li>치아 사이 간격(다이아스티마)이나 불규칙한 형태 개선</li>
  <li>작은 파절이나 마모로 인한 미관 개선</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술은 일부 법랑질을 삭제하므로 되돌리기 어렵고, 심한 충치나 치아 파절이 있으면 먼저 치료가 필요합니다. 강한 이갈이나 부하가 큰 부위에는 적합하지 않을 수 있으며, 적절한 구강위생과 관리로 수년 간 유지됩니다. 자세한 상담은 이음치과 등 전문기관에서 평가를 받아보세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='laminate';
UPDATE dict_terms SET full_desc='<p>올세라믹은 크라운이나 브릿지를 만들 때 금속 뼈대 없이 전부 세라믹(도자기) 재료로 제작한 보철물입니다. 자연치아의 투명도와 색감을 정밀하게 재현할 수 있어 앞니와 같은 심미 부위에 적합하며, 금속 색이 비치는 일이 없어 보다 자연스러운 미소를 기대할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치과용 세라믹은 빛을 투과하고 반사하는 특성이 있어 자연치아와 유사한 광학 효과를 냅니다. 대표적 재료로는 지르코니아, 리튬실리케이트 계열이 있으며 재료에 따라 강도와 투명도가 달라집니다. 금속이 없어 잇몸 경계에서 어두운 띠가 생기지 않고 금속 알레르기 우려가 없습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>앞니처럼 심미성이 중요한 부위의 크라운이나 베니어 대체</li>
  <li>금속 알레르기 또는 금속 색 노출을 피하고 싶은 경우</li>
  <li>기존 금속 보철물의 심미적 개선을 원할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>심미성이 뛰어나지만 재료와 설계에 따라 깨짐(파절) 위험이 있으므로 교합 상태와 치아 위치를 고려해 선택해야 합니다. 비용과 보험 적용 범위가 제한될 수 있으니 치료 전 충분한 상담이 필요합니다. 자세한 검토는 이음치과에서 진단을 통해 결정합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='all-ceramic';
UPDATE dict_terms SET full_desc='<h3>지르코니아란 무엇인가요?</h3>
<p><strong>지르코니아</strong>는 산화지르코늄으로 만든 고강도 세라믹 재료로, 견고함과 심미성을 동시에 추구하는 보철물에 쓰입니다. 금속보다 강도가 높아 깨짐에 강하고 치아 색을 자연스럽게 표현해 크라운·브릿지·임플란트 상부 보철에 널리 사용됩니다. 금속 알레르기 우려가 있는 환자에게도 적합한 경우가 많습니다.</p>

<h3>원리 또는 특징</h3>
<p>결정 구조가 촘촘하여 기계적 강도가 높고, CAD/CAM 밀링 또는 소결 공정을 통해 정확한 형태로 제작됩니다. 표면을 글레이즈하거나 색을 맞춰 심미성을 높이며, 금속처럼 빛이 투과되지 않아 금속 색이 비치지 않습니다. 다만 유리질 세라믹보다 약간 불투명할 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>심미성과 내구성을 동시에 요구하는 앞니·어금니 크라운</li>
  <li>교합력이 큰 부위의 브릿지 또는 임플란트 보철</li>
  <li>금속 알레르기나 금속색을 피하고 싶은 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>지르코니아는 제작 방법과 시편 두께, 표면처리에 따라 성능이 달라집니다. 마모나 적합도를 줄이기 위해 맞춤 연마와 정기검진이 필요하며, 수리나 재장착 시 재평가가 필요합니다. 치료 계획과 재료 선택은 이음치과에서 치아 상태를 확인한 뒤 결정하는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='zirconia';
UPDATE dict_terms SET full_desc='<p><strong>브릿지(Bridge)</strong>는 빠진 치아의 공간을 양쪽 인접 치아에 고정된 보철로 연결해 채우는 치료입니다. 상실된 치아 양쪽의 치아를 덧씌울 형태로 깎아 지대치로 만들고, 3개 이상의 연속된 크라운을 하나로 제작해 빈틈을 메우므로 고정식이라 탈부착이 필요 없습니다.</p>

<h3>원리 또는 특징</h3>
<p>양쪽 치아를 지지대로 삼아 연결된 보철물이 빈 공간을 떠받치는 구조입니다. 재료는 금속·도재 결합, 전부도재(지르코니아) 등 다양하며 심미성과 강도가 중요합니다. 고정식이라 유지·관리 시 환자의 청결 관리가 필수입니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>단일 혹은 복수 치아가 빠져 인접치아 상태가 양호할 때</li>
  <li>임플란트가 의학적·경제적 이유로 어려울 때</li>
  <li>빠진 치아로 인해 저작 기능·심미성이 저하된 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>브릿지는 즉시 안정감을 주지만 인접치를 깎아야 하므로 자연치 손실 위험과 충치·치주질환 관리가 필요합니다. 수명은 관리와 재료에 따라 다르며, 장기적인 선택은 치아 상태와 생활습관을 고려해 이음치과와 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='bridge';
UPDATE dict_terms SET full_desc='<p>PFM(도재-금속 크라운)은 내부에 금속 뼈대를 두고 그 위에 도자기(도재)를 얇게 씌워 만든 보철물입니다. 금속의 강도와 도재의 자연스러운 색감·광택을 결합해 심미성과 내구성을 동시에 추구하는 전통적 보철 방식입니다.</p>

<h3>원리 또는 특징</h3>
<p>금속 코핑이 씹는 힘을 지지하고 도재층이 치아 색과 표면 광택을 재현합니다. 고정성 보철물로서 강도가 좋아 교량(브릿지)이나 어금니에 유리하지만, 잇몸이 내려오면 금속 가장자리가 보일 수 있고 도재가 갈라지거나 칩이 생기면 수리·교체가 필요합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
<li>치아가 많이 손상되어 단단한 지지 구조가 필요할 때</li>
<li>여러 치아를 연결하는 브릿지 제작 시</li>
<li>심미성과 내구성을 동시에 원하는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>금속 알레르기나 잇몸 후퇴로 금속선이 보일 수 있음을 미리 상담하세요. 단단한 음식이나 이갈이는 도재 파절 위험을 높이며, 문제가 생기면 이음치과 등 전문의에게 평가받아 부분 보수나 재제작을 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='pfm';
UPDATE dict_terms SET full_desc='<p><strong>인레이</strong>는 충치나 손상으로 잃은 치아 내부의 공간을 외부에서 맞춤 제작해 채워 넣는 보철물입니다. 치아의 교합면과 옆면 일부(치아의 굴곡 안쪽)에만 들어가며, 기성 레진과 달리 치과외 랩에서 정밀 제작한 뒤 접착제로 고정합니다. 형태와 색을 세밀하게 맞출 수 있어 자연스럽습니다.</p>

<h3>원리 또는 특징</h3>
<p>충치 제거 후 남은 치질을 본을 떠 디지털 스캔 또는 석고 모델로 제작합니다. 금속(골드), 세라믹, 레진 계열 소재로 만들며 강도와 심미성, 마모성이 소재별로 다릅니다. 치아와 접착해 이탈을 막고 정확한 마진을 제공합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치아의 교합면과 인접면 일부에 국한된 중간 크기 충치</li>
  <li>기존 충전물의 마모나 변색으로 교체가 필요할 때</li>
  <li>심미성과 내구성을 동시에 원할 때(세라믹 인레이)</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>크라운보다 보존적이지만 치아 경계가 튼튼해야 합니다. 재료에 따라 비용과 색맞춤, 내구성이 달라 여러 선택지가 있으니 이음치과에서 상담으로 적합한 재료와 치료 계획을 결정하세요. 시린감이나 수복물의 변색·마모는 추후 관리가 필요할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='inlay';
UPDATE dict_terms SET full_desc='<p>온레이는 어금니의 씹는 면 가운데 손상된 부분을 본을 떠 맞춤 제작한 보철물로 덮어 치아의 형태와 기능을 회복시키는 치료입니다. 인레이보다 넓게 교두(치아의 뾰족한 부분)를 포함해 수복하지만, 전체를 씌우는 크라운에 비해 치아削除량이 적어 자연 치아를 더 보존할 수 있습니다. 병·의원에서 본을 채취해 도재, 복합레진, 금속 등으로 제작합니다.</p>

<h3>원리 또는 특징</h3>
<p>온레이는 실험실 제작물(간접 수복물)을 치아 표면에 접착제로 고정해 파절 저항과 균열 방지 효과를 줍니다. 교두를 보호해 씹는 힘을 분산하고, 재료에 따라 심미성과 내구성이 달라 치료 목적에 맞춰 선택합니다. 시술은 보통 1~2회 방문으로 완성됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>충전물이 크거나 교두까지 손상되어 일반 충전으로는 약한 경우</li>
  <li>치아 균열이 있어 교두 보호가 필요한 경우</li>
  <li>크라운보다는 치아를 더 보존하면서 심미성도 고려할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>온레이는 보존적 대안이지만 모든 경우에 가능한 것은 아니므로 검사 후 결정합니다. 재료별 장단점과 비용, 시술 횟수, 수복물의 마모·파절 가능성 등을 상담받아야 합니다. 적절한 관리와 정기검진으로 수명을 연장할 수 있으며, 자세한 상담은 이음치과에서 받아보세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='onlay';
UPDATE dict_terms SET full_desc='<h3>의치란 무엇인가요?</h3>
<p>의치(틀니)는 빠진 여러 치아를 대신해 입에서 빼고 끼울 수 있도록 만든 보철물입니다. 잇몸 모양에 맞춘 베이스에 인공치아가 배치되어 씹기와 발음, 얼굴 형태를 회복하는 데 도움을 줍니다. 부분의치와 총의치로 구분되며 개인 상태에 맞게 설계합니다.</p>

<h3>원리 또는 특징</h3>
<p>대부분 아크릴 수지나 금속 기반에 인공치아를 고정해 잇몸 표면에 앉히거나 치아에 걸쇠로 고정합니다. 부분의치는 주변 자연치아에 클라스프로 지지하고, 총의치는 흡착력과 정확한 적합으로 유지됩니다. 착용감과 안정성은 재료·설계·구강 상태에 따라 달라집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>여러 개의 치아가 빠져 일반 보철 치료가 필요한 경우</li>
  <li>모든 치아가 상실되어 총의치가 필요한 경우</li>
  <li>임플란트 등 고정 보철이 어려울 때 비용이나 전신 상태에 맞춘 대안</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기에는 말하고 씹는 데 적응기간이 필요하며, 불편하면 조정이 필요합니다. 매일 세척하고 장기간 사용 시 재라이닝이나 교체가 필요할 수 있습니다. 정확한 선택과 조정은 구강검진 후 결정되므로 이음치과와 상담해 적합한 옵션을 논의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='denture';
UPDATE dict_terms SET full_desc='<p>임시 보철은 최종 크라운이나 브릿지가 완성될 때까지 일시적으로 씌우는 보철물입니다. 치아 삭제로 노출된 조직을 보호하고 저작과 발음, 심미를 유지해 주며 잇몸 형태를 안정시키는 역할을 합니다. 보통 레진(합성수지)로 제작해 임시 시멘트로 고정하며, 이음치과에서도 제작·조정합니다.</p>

<h3>원리 또는 특징</h3>
<p>임시 보철은 단기간 사용을 전제로 하여 빠르게 제작되고 쉽게 제거될 수 있도록 설계됩니다. 임시 시멘트로 붙여 통증과 감각 과민을 줄이고, 주변 치은의 모양을 유지해 최종 보철의 적합성을 돕습니다. 내구성은 낮아 마모나 파절 가능성이 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치아를 깎아 최종 보철물이 나올 때까지 보호가 필요할 때</li>
  <li>보철물 제작 기간 동안 심미성과 저작 기능 유지가 필요할 때</li>
  <li>치은 형태를 안정시켜 최종 보철의 적합성을 확인할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>딱딱하거나 끈적한 음식은 피하고 평소보다 꼼꼼히 양치하세요. 느슨해지거나 빠질 수 있으니 통증·이물감·탈락 시 즉시 치과에 내원해야 합니다. 색상과 강도는 임시적이므로 장기 사용은 권하지 않습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='temporary-crown';
UPDATE dict_terms SET full_desc='<p>치아 미백은 변색된 치아의 색을 밝게 만들어 웃음의 인상을 개선하는 치료입니다. 과산화수소나 카바마이드 과산화물 같은 착색 분해제를 사용해 치아 표면과 내부의 색소를 옅게 만들며, 병원에서 빠르게 시행하는 오피스 미백과 집에서 서서히 진행하는 홈 미백으로 나뉩니다. 이음치과와 같은 전문의 진료에서 안전하게 계획합니다.</p>

<h3>원리 또는 특징</h3>
<p>미백제의 산화 작용으로 색소 분자가 분해되어 치아 색이 밝아집니다. 오피스 미백은 고농도의 약물을 레이저나 광원과 함께 사용해 짧은 시간에 효과를 보고, 홈 미백은 맞춤 트레이에 약물을 넣어 장기간 서서히 변화시키는 방식입니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>커피·담배·와인 등 외인성 착색 개선이 필요할 때</li>
  <li>노화로 인한 전반적 치아색 밝기 개선을 원할 때</li>
  <li>치아 내부(약물·치수치료 후) 착색의 경우 보철·비니어 전 고려 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치아 균열, 민감도 증가, 잇몸 자극이 발생할 수 있고, 충전물·크라운 등 보철물은 밝아지지 않습니다. 안전한 시행을 위해 구강검진 후 적절한 방법과 강도를 선택하고, 유지 관리를 위해 가급적 전문의 상담을 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='teeth-whitening';
UPDATE dict_terms SET full_desc='<h3>치아 성형이란</h3>
<p>치아 성형은 본래 치아의 모양을 다듬거나 보강해 웃을 때 보이는 모습의 균형을 맞추는 치료입니다. 작은 모서리 부러짐을 갈아내거나, 레진(복합레진)으로 결손을 메우고, 라미네이트로 형태를 바꿔 자연스럽고 조화로운 치열을 만드는 비교적 간단한 심미 시술입니다.</p>

<h3>원리 또는 특징</h3>
<p>필요한 부위의 치질을 최소한으로 삭제해 표면을 연마하거나, 접착성 재료로 모양을 더해 치아 외형을 바꿉니다. 즉석에서 보철·레진으로 보완하거나, 얇은 세라믹 라미네이트를 제작해 붙이는 등 비침습적 방법이 주를 이룹니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치아 끝이 들쭉날쭉하거나 작은 부러짐이 있을 때</li>
  <li>작은 틈(사이)을 메워 심미적으로 개선하고 싶을 때</li>
  <li>치아 크기·비대칭이 있어 웃을 때 눈에 띄는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치아 성형은 치아를 많이 깎지 않는 것이 원칙이나, 한계가 있어 심한 배열 문제는 교정이나 보철을 병행해야 합니다. 시술 후 민감도가 일시적일 수 있고 색 유지 관리를 위해 정기검진과 구강위생이 중요합니다. 정확한 계획은 이음치과에서 진단 후 결정합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tooth-contouring';
UPDATE dict_terms SET full_desc='<h3>심미 보철이란</h3>
<p>심미 보철은 부러지거나 닳은 치아를 단순히 기능적으로 복원하는 것을 넘어서 주변 치아와 어울리는 색감·형태·투명도·광택을 맞춰 자연스러운 미소를 만드는 치료입니다. 얼굴 균형과 발음, 교합을 함께 고려해 개인별로 맞춤 제작합니다. 이음치과에서도 환자 요구와 임상 상황을 종합해 결과를 설계합니다.</p>

<h3>원리 또는 특징</h3>
<p>색채 매칭, 표면 텍스처와 광택 재현, 치아 형태 조정, 적절한 재료 선택(도재·지르코니아·복합레진 등)을 통해 자연치와의 시각적 통합을 목표로 합니다. 또한 교합 안정성과 장기 내구성을 고려해 설계합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>심한 변색이나 치아 표면 손상으로 미용 개선이 필요한 경우</li>
  <li>치아가 깨지거나 형태가 불량해 균형 있는 미소가 필요한 경우</li>
  <li>임플란트·크라운 등 보철물을 심미적으로 맞춰야 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>재료와 치료 범위에 따라 비용과 수명이 달라집니다. 가능하면 자연치를 보존하는 보존치료를 우선 고려하고, 완성 뒤에는 규칙적인 관리와 치과 검진으로 색 변화나 마모를 점검해야 합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cosmetic-prosthetics';
UPDATE dict_terms SET full_desc='<p><strong>교합(Occlusion)</strong>은 위아래 치아가 서로 닿고 움직이며 맞물리는 관계를 말합니다. 올바른 교합은 음식을 효율적으로 씹고 말하기를 돕고 턱관절에 가해지는 부담을 줄여줍니다. 보철 치료에서는 크라운·임플란트 등의 높이와 접촉점을 정밀하게 맞추는 과정이 필수이며, 이음치과에서도 세심하게 평가합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아의 접촉 위치와 면적, 그리고 턱의 움직임이 조화롭게 어울려 힘을 분산시키는 것이 핵심입니다. 중심위(centric relation)에서의 안정적 접촉과 씹을 때의 동적 접촉이 균형을 이루면 치아 마모, 통증, 보철 파손 위험이 줄어듭니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>크라운·브릿지·임플란트 등 보철물 장착 전·후</li>
  <li>턱관절 통증이나 소리, 개구 제한이 있을 때</li>
  <li>치아마모·부정교합으로 저작·발음에 문제가 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>교합은 한번 맞춘 뒤에도 미세조정이 필요할 수 있으며, 적응 기간이 있습니다. 보철물은 재조정으로 편안함을 개선할 수 있고, 정기검진으로 교합 변화를 확인하는 것이 중요합니다. 필요 시 교정이나 교합장치로 추가 치료를 고려할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='occlusion';
UPDATE dict_terms SET full_desc='<p>색조 매칭은 보철물(크라운·베니어 등)의 색을 주변 자연치아와 조화롭게 맞추는 과정을 말합니다. 단순히 색깔만 맞추는 것이 아니라 투명도, 명도·채도, 표면광택과 주변 잇몸·입술 색까지 고려해 눈에 띄지 않도록 만드는 것이 목표입니다.</p>

<h3>원리 또는 특징</h3>
<p>치과용 색조 가이드(예: VITA)와 분광광도계·디지털 사진을 함께 사용해 수치와 시각 정보를 확보합니다. 표준 조명하에서 측정하고, 세라믹의 층별 색소 배합과 광택으로 최종 색을 재현합니다. 의사와 치기공소 간 소통이 중요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>앞니 단독 크라운이나 베니어 등 심미적 부위 보철</li>
  <li>치아 표백 후 보철물을 맞출 때</li>
  <li>부분적 수복으로 주변 치아와 조화가 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>조명과 각도, 자연치아의 색상 변화 때문에 완벽한 일치가 어려울 수 있습니다. 때로는 미백을 먼저 권하거나, 제작 후 환자 구강에서 미세 조정을 합니다. 이음치과에서는 디지털 측정과 치기공사와의 협업으로 최상의 결과를 추구합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='shade-matching';
UPDATE dict_terms SET full_desc='<p>충치는 입안에 사는 세균이 음식물 속 당을 분해해 산을 만들면서 치아의 단단한 표면(법랑질)과 그 아래의 상아질을 서서히 녹여 구멍을 만드는 질환입니다. 초기에는 별다른 증상이 없다가 진행되면 찬것·단것에 예민하거나 심한 통증과 염증, 농양으로 이어질 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>충치는 반복적 산 노출로 인한 탈회(미네랄 손실)로 시작하며 흰반점 단계에서 적절한 관리로 회복될 수 있습니다. 진행되면 표면이 무너져 구멍이 생기고 세균이 깊숙이 들어가 신경을 침범해 통증과 감염을 유발합니다. 식습관, 구강위생, 침 분비량 등이 위험도를 좌우합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>음식·음료에서 찬맛·단맛에 예민하거나 지속적 통증이 있을 때</li>
  <li>치아 표면에 흰반점, 갈색·검은 얼룩 또는 구멍이 보일 때</li>
  <li>정기 구강검진 중 치아 손상이나 초기 병변이 발견될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기에 발견하면 불소도포, 불소치약과 올바른 칫솔질로 진행을 멈출 수 있고, 이미 구멍이 생기면 충전·신경치료·발치 등 상황에 맞춘 치료가 필요합니다. 규칙적 검진과 당 섭취 조절, 치실 사용 등이 예방에 가장 효과적이며, 정확한 치료 계획은 이음치과 등 전문의와 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cavity';
UPDATE dict_terms SET full_desc='<h3>레진이란</h3>
<p>레진(Composite Resin)은 치아 색과 유사한 복합 수지로 만든 충전재입니다. 충치를 제거한 뒤 생긴 빈 공간을 자연스러운 색과 형태로 메워 심미적 수복이 가능하며, 치아 표면에 바로 접착해 단단하게 굳히므로 대부분 당일 치료가 가능합니다. 이음치과에서도 심미 레진 치료에 자주 사용됩니다.</p>

<h3>원리 또는 특징</h3>
<p>레진은 유기성 수지 매트릭스와 무기 필러 입자가 섞여 있어 강도와 광택을 얻습니다. 치면에 접착제를 적용해 화학·기계적으로 결합시키고, 특수 광원으로 광중합(광선경화)하면 즉시 경화되어 형태를 유지합니다. 색상 맞춤과 연마로 자연스러운 외관을 만들 수 있지만 시간이 지나면 마모나 착색이 생길 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>작거나 중간 크기의 충치 수복이 필요할 때</li>
  <li>앞니 심미 수복(깨짐·모양 보정 등)할 때</li>
  <li>기존 수복물의 부분 보수나 모서리 파절 수리 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>레진은 치아를 많이 깎지 않는 보존적 방법이며 한 번 내원으로 치료가 가능한 경우가 많습니다. 다만 음식물·흡연 등으로 착색될 수 있고, 사용 부위와 습관에 따라 수명이 제한되어 교체가 필요할 수 있습니다. 민감도를 느끼거나 유지관리에 관해선 담당 치과의사와 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='resin';
UPDATE dict_terms SET full_desc='<p><strong>신경치료(근관치료)</strong>는 충치나 외상으로 치아 내부의 치수(신경과 혈관)가 염증 또는 감염되어 통증이나 농양이 생길 때, 그 손상된 조직을 제거하고 근관을 깨끗이 소독한 뒤 밀봉하여 치아를 살리는 치료입니다. 국소마취로 통증을 조절하며 보통 치아를 발치하지 않고 보존하는 목적입니다.</p>

<h3>원리 또는 특징</h3>
<p>감염된 치수를 기계적·화학적으로 제거하고 근관(치아 속 관)을 세척·소독한 뒤 생체적합성 충전재(예: 구타퍼차)로 밀봉해 재감염을 막습니다. 한 번에 끝나지 않을 수 있어 여러 방문이 필요하고, 이후 치아 강도 유지를 위해 보철(크라운) 권유가 흔합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>심한 충치로 인해 찬것·더운것에 심한 통증 또는 지속적 통증이 있을 때</li>
  <li>치아 외상으로 신경 손상 또는 노출이 발생했을 때</li>
  <li>치아 뿌리 끝에 염증(치근단 농양)이 생긴 경우</li>
  <li>이미 신경치료한 치아가 재감염되어 재치료가 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술은 대개 안전하며 치아를 보존하는 효과가 큽니다. 그러나 치료 후에도 일시적 통증이나 민감감이 있을 수 있고, 근관의 복잡한 구조 때문에 완전한 성공을 위해 재치료나 외과적 치료(치근단 절제술)가 필요할 수 있습니다. 치료 후에는 크라운 등 보철로 치아를 보호하는 것이 재발 방지와 기능 유지에 도움이 됩니다. 자세한 상담은 이음치과 전문의와 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='root-canal';
UPDATE dict_terms SET full_desc='<p>근관은 치아 뿌리 속에 자리한 관 모양의 작은 공간으로, 그 안에 치수(신경과 혈관)가 들어 있습니다. 관의 굵기와 모양은 치아마다 다르고 갈라지는 지점이 있어 세밀한 관리가 필요합니다. 치수에 염증이나 감염이 생기면 이 공간을 깨끗이 소독하고 밀봉하는 근관치료가 필요합니다.</p>

<h3>원리 또는 특징</h3>
<p>근관은 매우 좁고 복잡해 치과용 현미경과 특수 기구로 잔존 감염 물질을 제거해야 합니다. 제거 후 소독약으로 멸균하고 충전재로 밀봉해 외부 세균의 재침투를 막는 것이 핵심입니다. 치아의 구조와 근관 형태에 따라 치료법이 달라집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>깊은 충치로 치수가 노출되거나 염증이 생겼을 때</li>
  <li>치아 외상으로 신경이 손상되었을 때</li>
  <li>치근단 농양이나 지속적인 통증·맹목적인 통증이 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>근관치료는 통상적으로 치아를 살리는 시술이며 성공률이 높습니다. 치료 후에는 크라운 같은 보철로 치아를 보강하는 경우가 많고, 통증은 마취와 진통제로 조절됩니다. 자세한 검사와 상담은 이음치과 등의 전문의와 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='root-canal-anatomy';
UPDATE dict_terms SET full_desc='<h3>치수란 무엇인가요?</h3>
<p>치수는 치아 중심부에 자리한 연한 조직으로 신경, 혈관, 결합조직이 모여 있습니다. 치아에 영양을 공급하고 온도·압력 같은 감각을 전달하며, 성장기에는 치아 형성에 관여합니다. 염증이나 손상이 생기면 심한 통증을 유발하고 치료가 늦으면 치아 전체에 영향을 줄 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치수는 치관의 치수강과 근심(뿌리관)을 통해 구조화되어 있으며 혈류와 신경이 풍부합니다. 단단한 치질로 둘러싸여 있어 부종을 잘 견디지 못하고, 나이가 들수록 2차 상아질 축적으로 치수강이 좁아집니다. 손상 시 치수는 제한적인 회복 반응(수복 상아질 형성)을 보입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>충치가 깊어 치수에 까지 도달한 경우(치수염)</li>
  <li>외상으로 치아가 금이 가거나 치수 노출이 된 경우</li>
  <li>반복적인 수복 치료로 치수 자극이 누적된 경우</li>
  <li>심한 마모나 산식으로 치수 민감 증상이 나타나는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치수 염증의 증상은 찬·더운 자극에 예민하거나 지속적·심한 통증이 있습니다. 치료는 손상 정도에 따라 보존적 신경치료(부분적 또는 전치수 제거·근관치료)나 발치로 나뉩니다. 초기에 치료하면 치아 보존 가능성이 높으므로 통증이나 깊은 충치가 있으면 이음치과와 상담해 조기 관리하는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-pulp';
UPDATE dict_terms SET full_desc='<p>법랑질은 치아의 바깥쪽을 감싸는 매우 단단한 흰 층으로, 아래의 상아질과 치수(신경)를 보호하는 역할을 합니다. 인체에서 가장 무기질이 많은 조직으로 충격과 마모에 강하지만 세포나 혈관이 없어 손상 후 스스로 재생되지는 않습니다. 다만 초기 탈회는 불소 등으로 재광화될 수 있어 조기 관리가 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>주성분은 하이드록시아파타이트 같은 무기질로 두께는 부위에 따라 수밀리미터 수준입니다. 세포가 없어 회복 능력이 없고 단단하지만 약간의 투명성을 띠어 색 변화나 얇아짐이 눈에 띌 수 있습니다. 산성 물질·마찰·충치로 점차 손상됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>충치 초기(법랑질 탈회로 흰반점 또는 작은 구멍 발생)</li>
  <li>산 침식(탄산음료·위산 노출로 표면 부식)</li>
  <li>물리적 마모(강한 칫솔질, 음식물 마모, 이갈이)</li>
  <li>심미적 문제나 외상으로 인한 파절</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>예방이 가장 중요해 불소 도포, 실란트, 올바른 칫솔 습관과 식이조절로 손상을 줄일 수 있습니다. 이미 손상된 법랑질은 자연 재생이 어렵기 때문에 충전이나 크라운 등 치과적 복원이 필요할 수 있으며, 자세한 상담은 이음치과에서 받으실 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='enamel';
UPDATE dict_terms SET full_desc='<p>상아질은 법랑질 아래와 치근 표면을 이루는 노란빛의 단단한 조직으로, 치아의 대부분을 구성해 내부 치수를 보호하면서도 외부 충격을 분산합니다. 미세한 관인 상아세관이 치수까지 이어져 있어 자극이 전달되면 시림이나 예민함을 느낄 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>상아질은 무기질과 콜라겐으로 이루어진 생체 조직으로 법랑질보다 단단도는 낮지만 탄력성이 있어 치아의 구조적 지지를 담당합니다. 상아세관을 통한 액체 이동이 자극 전달의 주요 기전이며, 충치나 마모 시 치수에 영향을 주기 쉽습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>충치가 법랑질을 뚫고 상아질에 도달했을 때</li>
  <li>잇몸 후퇴로 뿌리부위의 상아질이 노출될 때(시림)</li>
  <li>치아마모·산식해로 표면이 닳아 상아질이 드러날 때</li>
  <li>수복·보철 과정에서 상아질의 보존과 접착이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>노출된 상아질은 민감성완화제, 불소도포, 레진 수복 등으로 관리하며, 간단한 시린 증상은 생활습관조정과 적절한 홈케어로 개선될 수 있습니다. 치료 시 가능한 한 상아질을 보존하는 것이 중요하고, 증상이 심하면 신경치료가 필요할 수 있으므로 정확한 진단과 치료는 이음치과에서 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dentin';
UPDATE dict_terms SET full_desc='<p>아말감은 은·주석·구리와 소량의 수은을 혼합해 만든 금속성 충전재로, 특히 어금니처럼 씹는 힘이 큰 부위에서 오래 견디는 특성으로 오랫동안 쓰여 왔습니다. 내구성과 비용 측면이 장점이지만 은빛 색 때문에 심미성이 떨어져 앞니 치료에는 적합하지 않습니다. 이음치과에서도 상황에 따라 선택적으로 권합니다.</p>

<h3>원리 또는 특징</h3>
<p>아말감은 수은과 다른 금속이 화학적으로 합금되어 굳으면서 기계적 강도를 얻습니다. 마모와 압박에 강하고 시술이 비교적 빠르며 비용이 낮은 편입니다. 다만 색이 눈에 띄고, 제거 시 미세 입자·증기 노출을 줄이기 위한 주의가 필요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>어금니의 깊은 충치나 넓은 수복이 필요할 때</li>
  <li>내구성이 최우선이고 심미성 요구가 낮을 때</li>
  <li>비용이나 시술 시간 제약이 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>수은 함유에 대한 우려가 있으나 주요 보건기관은 일상적 수복에서의 안전성을 인정합니다. 임신기·영유아·금속 알레르기 환자는 별도 상담이 필요하며, 미용을 중요시하면 레진·세라믹 대체재를 고려할 수 있습니다. 기존 아말감 제거는 전문적 방호 장비로 안전하게 시행해야 합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='amalgam';
UPDATE dict_terms SET full_desc='<p>글래스아이오노머시멘트(GIC)는 유리분말과 산성용액을 섞어 만드는 충전재로, 치아표면과 화학적으로 결합하고 지속적으로 불소를 내보내 이차 우식을 억제하는 장점이 있습니다. 강도는 복합레진보다 낮아 주로 유치나 임시충전, 치아 내부 보호층으로 많이 쓰입니다. 이음치과에서도 소아치료와 임시복원에 활용됩니다.</p>

<h3>원리 또는 특징</h3>
<p>산-염기 반응으로 경화하며, 치아의 법랑질·상아질과 화학적으로 밀착합니다. 불소방출으로 주변 치질의 재광화에 도움되지만, 마모저항과 색조안정성은 복합레진보다 떨어집니다. 수분에 상대적으로 관대해 초기습윤 환경에서도 사용 가능합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>유치의 충전이나 소아치과 치료</li>
  <li>임시충전 또는 근관치료 후 임시복원</li>
  <li>치관부 목부(경부) 충전이나 마모된 치아 보존</li>
  <li>충전물 아래 라이너나 베이스로 사용</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>작은 교합부위나 저하중 부위에 적합하며, 큰 결손부에는 보강이나 다른 재료와 병용하는 것이 안전합니다. 초기 경화 시 과도한 수분이나 건조는 성능에 영향을 주므로 시술 시 주의가 필요하고, 시간이 지나며 색이 변할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gic';
UPDATE dict_terms SET full_desc='<p>치수 복조술은 충치나 치료 중 치아 속 신경(치수)이 드러나거나 거의 드러날 때, 그 부위를 약제로 덮어 치수의 염증을 가라앉히고 치수의 생명을 보존하려는 보존적 치료입니다. 목표는 신경을 제거하지 않고 자연 치수 조직이 치유되도록 유도하는 것입니다.</p>

<h3>원리 또는 특징</h3>
<p>수산화칼슘이나 MTA 같은 약제가 치수 표면에 닿아 염증을 줄이고 새로운 상아질(치수벽)을 형성하도록 자극합니다. 직접복조술(치수가 노출된 경우)과 간접복조술(치수가 거의 노출될 위험이 있는 경우)로 나뉘며, 약제 적용 후 빈틈 없이 밀봉하는 것이 중요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>충치 제거 중 작은 규모로 치수가 노출된 경우</li>
  <li>깊은 충치로 치수에 가깝게 접근했지만 아직 광범위한 감염이 없는 경우</li>
  <li>경미한 외상으로 치수가 일부 노출된 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>성공률은 노출 크기·감염 여부·밀봉 상태에 따라 달라집니다. 시술 후 통증이나 불편이 지속되면 근관치료(신경치료)가 필요할 수 있으니 정기 관찰과 엑스레이 확인이 중요합니다. 이음치과와 같은 전문 치과에서 적절한 판정을 받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='pulp-capping';
UPDATE dict_terms SET full_desc='<p>MTA는 치아 내부의 손상된 조직을 보호하고 뿌리 끝을 안정시키기 위해 사용하는 생체친화적 시멘트입니다. 소독 후 결손 부위에 채워 넣으면 균이 들어오는 통로를 막고, 주변 조직의 치유를 돕는 특성이 있어 신경 보존 치료나 근관치료 보조에 자주 활용됩니다.</p>

<h3>원리 또는 특징</h3>
<p>주성분은 칼슘 실리케이트계로 수분이 있는 환경에서 굳으며 우수한 밀봉력을 가집니다. 경화 과정에서 칼슘이온을 방출해 하이드록시아파타이트층이 형성되고, 이로 인해 조직과 잘 결합하여 재생을 촉진합니다. 방사선상 확인이 가능하고 비교적 조직 친화적입니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치수복조·부분적 신경보존(급성 염증이 심하지 않을 때)</li>
  <li>근관 천공 수복(뿌리 쪽 구멍 막기)</li>
  <li>근단수복(근관치료 후 뿌리 끝 봉쇄) 및 치근단 수술 보조</li>
  <li>미성숙치의 근단 폐쇄(아펙시피케이션) 보조</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>일반적으로 안전하지만 굳는 시간이 비교적 길고(수분 환경에 따라 다름) 재료비가 상대적으로 높습니다. 일부 유형은 치아 색 변화가 생길 수 있어 치아 위치와 미관을 고려해 선택해야 하며, 정확한 적용 여부는 전문의와 상의하는 것이 좋습니다. 이음치과 등 전문 진료에서 환자 상태에 맞는 재료 선택을 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='mta';
UPDATE dict_terms SET full_desc='<h3>거타퍼차란 무엇인가요?</h3>
<p>거타퍼차는 신경치료(근관치료) 후 깨끗하게 정리된 치아 뿌리관을 밀봉하는 데 쓰이는 열가소성 고무계 재료입니다. 가늘게 만든 콘 형태로 넣어 열이나 압력으로 밀착시키며, 세균의 재감염을 막기 위해 치과용 실러와 함께 사용합니다.</p>

<h3>원리 또는 특징</h3>
<p>열을 가하면 말랑해져 근관의 형태에 맞춰 채워지고 굳으면 안정화됩니다. 방사선에 보이는 성분이 포함되어 위치 확인이 쉽고, 치아 조직과 화학적으로 결합하지 않아 실러가 함께 필요합니다. 대부분 생체적합성이 좋아 조직 반응이 적습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>근관치료(신경치료) 후 근관을 완전하게 밀봉할 때</li>
  <li>치료 실패로 인한 재근관치료 시 기존 충전물 제거 및 재충전</li>
  <li>치근단 치료나 장기적 근관 유지가 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>거타퍼차 자체는 문제가 적지만 완전한 치료 결과는 치아 위쪽의 보존 수복(씌우기나 충전)과 함께할 때 유지됩니다. 과도하게 뿌리끝을 넘기면 주변 조직에 자극을 줄 수 있고, 필요하면 제거·재충전이 가능합니다. 보다 자세한 상담은 이음치과에서 가능합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gutta-percha';
UPDATE dict_terms SET full_desc='<h3>재근관치료란</h3>
<p>재근관치료는 이전에 근관치료를 받은 치아에서 통증이나 감염이 재발할 때 기존의 근관 충전재를 제거하고 근관을 다시 세척·소독한 뒤 재충전하여 치아를 보존하는 치료입니다. 실패 원인을 확인해 문제 부위를 수정함으로써 발치를 피하고 자연치를 유지하는 것을 목표로 하며, 이음치과에서도 환자 상태에 맞춘 계획을 세웁니다.</p>

<h3>원리 또는 특징</h3>
<p>근관 내부의 세균과 염증성 조직을 물리적으로 제거하고 약물로 소독한 뒤 밀봉해 재감염을 차단하는 것이 핵심입니다. 기존 충전재와 병변을 제거하고 근관 형태를 재정비하며, 엑스레이나 현미경을 사용해 정확도를 높입니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>치아의 재발성 통증이나 잇몸 부종이 있을 때</li>
  <li>방사선상 치근단 병변이 남아 있거나 확대될 때</li>
  <li>기존 근관 충전이 불완전하거나 누출되어 재감염된 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>대부분의 경우 재근관치료로 치아를 유지할 수 있지만, 포스트나 광범위한 보철물이 있어 접근이 어려운 경우나 심한 골파괴가 있으면 근단절제술이나 발치가 필요할 수 있습니다. 치료 후 일시적 통증이나 재감염 가능성이 있으므로 추적관찰과 적절한 보철 처치가 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='retreatment';
UPDATE dict_terms SET full_desc='<p>치근단 절제술은 근관치료만으로 낫지 않는 뿌리 끝의 염증이나 낭종을 외과적으로 제거해 치아를 보존하려는 치료입니다. 잇몸을 소량 절개해 뿌리 끝과 감염 조직을 제거하고 필요하면 뿌리 끝을 밀봉하는 처치를 병행합니다. 통상 국소마취로 외래에서 시행하며, 필요한 경우 이음치과에서도 시행합니다.</p>

<h3>원리 또는 특징</h3>
<p>뼈를 일부분 제거해 치근단에 접근한 뒤 감염된 조직과 뿌리 끝 2~3mm를 잘라냅니다. 이후 병소를 소독하고 필요 시 역행충전(뿌리 끝에서부터 밀봉)을 하여 재감염을 막습니다. 치아를 발치하지 않고 보존할 수 있는 수술적 방법입니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>근관치료·재치료 후에도 방사선상 병소가 남거나 통증이 지속될 때</li>
  <li>근관 내 접근이 어려워 재치료가 불가능한 경우(예: 부러진 기구, 좁은 관)</li>
  <li>치근단 낭종이나 반복적인 누공·화농이 있는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>수술 후 1~2주간 붓기나 통증이 올 수 있으며 소독과 약물 복용이 필요합니다. 성공률은 높지만 100%는 아니며, 실패 시 발치가 대안이 될 수 있습니다. 아래턱 어금니 근처는 신경 손상 위험이 있으니 담당의와 위험도를 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='apicoectomy';
UPDATE dict_terms SET full_desc='<p><strong>치주질환</strong>은 입안 세균이 만든 플라크와 염증이 잇몸(치은)뿐 아니라 치주인대·치조골 같은 치아 지지 조직까지 손상시키는 질환입니다. 초기에는 잇몸의 출혈과 붓기 정도지만 진행되면 치아가 흔들리거나 빠질 수 있어 조기 발견과 관리가 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 표면에 붙은 세균성 바이오필름(플라크)이 염증을 유발하고, 면역반응으로 조직파괴가 일어납니다. 치은염은 가역적이지만 치주염은 골 흡수와 섬유 파괴가 동반되어 만성적·재발성으로 진행될 수 있으며 흡연, 당뇨 같은 위험인자가 치료 반응에 영향을 줍니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>양치할 때 잇몸에서 피가 나는 경우</li>
  <li>지속적인 입냄새 또는 불쾌한 맛</li>
  <li>치아가 흔들리거나 이간이 벌어지는 느낌</li>
  <li>흡연자나 당뇨가 있거나 구강 위생이 불량한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단은 치주 탐침 깊이와 엑스레이로 확인하며, 기본 치료는 스케일링·루트플래닝과 구강관리 교육입니다. 진행된 경우에는 수술적 치료와 정기적 유지관리가 필요합니다. 조기에 관리하면 치아 보존이 가능하니 증상 있으면 이음치과에서 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='periodontal-disease';
UPDATE dict_terms SET full_desc='<p>치은염은 치아 주위 잇몸에 생기는 초기 염증으로 잇몸에만 국한되어 가역적으로 회복될 수 있는 상태입니다. 치태(플라그)가 잇몸 경계에 쌓여 염증을 일으키면 잇몸이 붉어지고 부으며 양치할 때 출혈이 생깁니다. 적절한 구강관리와 스케일링으로 호전됩니다.</p>

<h3>원리 또는 특징</h3>
<p>주원인은 치면에 붙은 세균성 치태로, 이로 인해 잇몸에 염증 반응이 생깁니다. 통증이 심하지 않은 경우가 많아 자각이 늦을 수 있고, 염증이 장기간 지속되면 치주염으로 진행할 위험이 있습니다. 대체로 가역적이라 전문적 치석 제거와 올바른 칫솔질로 회복됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>양치 시 잇몸에서 출혈이 자주 나는 경우</li>
  <li>잇몸이 붉고 부어 보이며 민감한 느낌이 들 때</li>
  <li>구강 위생이 불량하거나 치석이 많이 쌓인 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치은염은 초기에 치료하면 완치가 가능합니다. 치료는 스케일링과 개인 구강위생 교육이 핵심이며, 흡연·당뇨 같은 전신 상태가 영향을 줄 수 있어 관리가 필요합니다. 정기검진을 받아 상태를 확인하고 필요 시 이음치과에서 전문적인 청소를 받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gingivitis';
UPDATE dict_terms SET full_desc='<p>치주염은 잇몸의 염증이 잇몸뼈(치조골)까지 확산되어 치아를 지탱하는 조직이 손상되는 질환입니다. 초기의 치은염과 달리 치조골 소실은 자연 회복이 어려워 치료로 진행을 멈추고 기능을 보존하는 것이 목표입니다. 치료하지 않으면 치아 흔들림과 결국 상실로 이어질 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>입안의 세균이 만든 치태(플라크)가 잇몸 주머니를 만들고 염증을 유발합니다. 숙주 면역반응과 염증 매개체가 골흡수를 촉진해 치조골이 줄어들며, 잇몸 주머니(치주낭)가 깊어져 잔여 치태 제거가 어려워지는 악순환이 특징입니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>잇몸 출혈이나 붓기가 반복될 때</li>
  <li>잇몸이 내려가 치아가 길어 보이거나 시린 느낌이 있을 때</li>
  <li>치아가 흔들리거나 맞물림이 달라졌을 때</li>
  <li>깊은 치주낭이 측정되거나 방사선에서 뼈 손실이 보일 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기 치료(스케일링·루트플래닝 등)로 진행을 멈출 수 있으나 손실된 뼈는 완전히 자연 재생되지 않습니다. 필요하면 치주수술이나 재생치료를 고려하고, 금연과 혈당 조절이 치료 성과에 큰 영향을 줍니다. 정기적 치주 관리가 중요하며, 전문가는 이음치과 등에서 진단과 맞춤 치료 계획을 제시합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='periodontitis';
UPDATE dict_terms SET full_desc='<h3>스케일링이란</h3>
<p>스케일링은 초음파 기구와 손기구를 이용해 치아 표면에 붙은 치태(플라그)와 치석을 제거하는 기본적인 잇몸 관리 시술입니다. 잇몸 염증을 줄이고 충치·치주질환으로 진행되는 것을 예방하는 목적이며, 이음치과에서도 정기검진의 일환으로 권장합니다.</p>

<h3>원리 또는 특징</h3>
<p>초음파 스케일러의 미세진동과 수류로 단단한 치석을 깨뜨리고, 수기구로 남은 부분을 정밀하게 다듬습니다. 일반적으로 국소마취가 필요하지 않고 시술 중 약간의 시림이나 출혈이 있을 수 있으나 대개 일시적입니다. 시술 후 표면을 매끄럽게 폴리싱합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>잇몸이 붓고 양치 시 출혈이 있는 경우</li>
  <li>입냄새가 지속되거나 치아 표면에 갈색·회색 얼룩이 보일 때</li>
  <li>정기 구강관리(건강보험으로 연1회 스케일링 적용)</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>건강한 경우 연1회 보험 적용으로 충분하지만, 치주질환이 있으면 3~6개월마다 반복해야 합니다. 시술 후 며칠간 시린감이나 잇몸 민감성이 생길 수 있으므로 부드러운 칫솔질과 치실 사용을 권장합니다. 심한 치주병은 추가 치료가 필요할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='scaling';
UPDATE dict_terms SET full_desc='<h3>치석이란</h3>
<p>치석은 입안의 미세한 세균막(플라크)이 타액 속 무기질과 결합해 점차 단단하게 굳은 침착물입니다. 치아 표면이나 잇몸 가장자리, 치아 사이에 단단히 붙어 칫솔로는 잘 지워지지 않으며 전문적인 처치가 필요합니다.</p>

<h3>원리 또는 특징</h3>
<p>플라크(생물막)가 시간이 지나면서 칼슘·인 같은 무기질로 석회화되어 치석이 됩니다. 표면이 거칠어지면 다시 플라크가 더 붙기 쉬워지고, 색은 위치에 따라 밝은색에서 짙은 갈색까지 다양합니다. 한 번 생기면 스케일링(초음파·수동 기구)으로 제거해야 합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>잇몸이 붓고 쉽게 피가 나는 경우</li>
  <li>입냄새가 지속되는 경우</li>
  <li>치아에 검은 착색이나 홈이 생긴 경우</li>
  <li>정기 검진에서 치석 축적이 관찰될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치석은 칫솔질만으로 제거되지 않으니 정기적인 전문 스케일링과 일상적인 치실·칫솔 관리가 중요합니다. 재발할 수 있으므로 개인 상태에 맞는 관리 주기를 치과(예: 이음치과)에서 상담받아 정하는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='calculus';
UPDATE dict_terms SET full_desc='<p>치태는 치아 표면에 끈적하게 붙는 투명한 세균막으로, 입안의 세균과 음식물 찌꺼기가 결합해 만들어집니다. 처음에는 손질로 제거되지만 시간이 지나면 단단한 치석으로 변해 충치와 잇몸 염증(치주질환)을 일으키는 주된 원인이 됩니다.</p>

<h3>원리 또는 특징</h3>
<p>치태는 여러 균종이 공동체를 이루는 바이오필름으로, 설탕 등 탄수화물을 분해해 산을 만들어 치아 법랑질을 녹이고 잇몸에 염증을 유발합니다. 표면이 끈적여 칫솔질만으로는 잘 제거되지 않고, 24시간 이내에 축적이 시작되어 방치하면 석회화됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>양치질이 불규칙하거나 올바르지 않을 때</li>
  <li>치아 사이 관리(치실·치간칫솔)가 부족할 때</li>
  <li>건조한 입(타액 분비 감소) 또는 고당질 식사 습관</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치태는 일상적인 칫솔질과 치실로 줄일 수 있고, 단단한 치석은 전문적 스케일링이 필요합니다. 초기 관리로 충치와 잇몸병을 예방할 수 있으니 증상이 있거나 제거가 어렵다면 이음치과에서 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='plaque';
UPDATE dict_terms SET full_desc='<p>치조골은 치아가 자리한 턱뼈의 부분으로, 치주인대를 통해 치아와 연결되어 물리적 지지와 충격 흡수 역할을 합니다. 정상적으론 씹는 힘에 맞춰 골 형성과 흡수가 반복되며 치아를 안정적으로 지지하지만, 잇몸 염증이 오래되면 골 소실이 진행되어 치아가 흔들리거나 상실될 수 있습니다.</p>
<h3>원리 또는 특징</h3>
<p>치조골은 치아가 들어가는 소켓을 만들고 있는 피질골과 내부의 해면골로 구성됩니다. 치주인대 섬유가 골 표면에 부착되어 힘을 분산시키며 혈관과 세포 활동으로 계속 재형성됩니다. 발치·염증·무리한 힘 등이 있으면 흡수가 촉진되어 형태가 바뀔 수 있습니다.</p>
<h3>관련 상황</h3>
<ul>
  <li>만성 치주염으로 인한 골 소실과 치아 흔들림</li>
  <li>치아 발치 후 골 흡수로 임플란트 계획이 필요한 경우</li>
  <li>교정 치료 중 치아 이동에 따른 골 재형성</li>
  <li>외상이나 국소 감염으로 인한 골 손상</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>초기 잇몸 치료로 골 손실을 멈추거나 늦출 수 있고, 진단은 구강검진과 X선(파노라마·근접촬영)으로 확인합니다. 필요하면 뼈 재생술(자가골·인공골)이나 추가 처치를 고려하며, 흡연·당뇨 등 전신 상태가 예후에 영향을 줍니다. 자세한 상담은 이음치과에서 가능합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='alveolar-bone';
UPDATE dict_terms SET full_desc='<h3>치주낭이란 무엇인가요?</h3>
<p>치주낭은 잇몸과 치아 사이에 생긴 비정상적으로 깊은 틈을 말합니다. 정상 잇몸 고랑은 대개 1~3mm인데, 잇몸 염증(치주염)으로 인해 4mm 이상으로 깊어지면 치주낭이 형성됩니다. 이 낭 속에는 세균과 플라크가 쌓여 염증을 악화시키고 주변 뼈를 손상할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치주낭은 잇몸과 치아의 연결조직(부착)이 파괴되면서 발생하며, 깊이가 깊을수록 세균 제거가 어려워 치료가 복잡해집니다. 탐침으로 낭 깊이를 측정하고 X선으로 뼈 손실 정도를 확인합니다. 흔히 출혈·구취·치아 흔들림이 동반됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>잇몸에서 자주 피가 나거나 붓는 경우</li>
  <li>입냄새가 오래 지속되는 경우</li>
  <li>치아가 흔들리거나 치열이 벌어지는 느낌이 들 때</li>
  <li>구강검진 시 프로빙 깊이 ≥4mm 또는 방사선상 뼈 소실이 관찰될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>적절한 스케일링과 루트플래닝, 그리고 올바른 칫솔질과 치실 사용으로 많은 치주낭은 줄일 수 있습니다. 깊거나 재발하는 낭은 치주 수술이나 재생치료가 필요할 수 있으므로 정기검진과 조기치료가 중요합니다. 증상이 의심되면 이음치과에서 평가를 받아보세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='periodontal-pocket';
UPDATE dict_terms SET full_desc='<p>잇몸 이식은 잇몸이 내려가 치아 뿌리(치근)가 드러난 부위를 덮어주기 위해 주변 조직을 덧대는 작은 수술입니다. 보통 입천장(구개)에서 본인 잇몸 조직을 채취해 부족한 부위에 이식해 보호층을 만들고 민감도와 심미성을 개선합니다. 이음치과에서도 국소마취로 시행하는 보편적 치주치료입니다.</p>

<h3>원리 또는 특징</h3>
<p>노출된 치근을 잇몸 조직으로 덮어 치아 뿌리를 보호하고 잇몸의 두께와 붙음(부착)을 늘립니다. 결합조직 이식(connective tissue graft)과 자유 치은 이식(free gingival graft) 같은 방법이 있으며, 봉합 후 몇 주간 서서히 자리잡아 회복됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>잇몸 퇴축으로 치근이 노출되어 민감하거나 충치 위험이 높은 경우</li>
  <li>치아 미관상 잇몸선이 고르지 않아 보철·심미치료 전 보완이 필요한 경우</li>
  <li>얇은 잇몸 조직(치은 biotype)으로 추가 손실 우려가 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>수술은 보통 국소마취로 안전하게 진행되지만 통증·부종·감염 가능성이 있으므로 금연과 엄격한 구강위생이 중요합니다. 봉합은 1~2주 뒤 제거하고 완전한 조직 안정에는 몇 달이 걸릴 수 있습니다. 개인차가 있으므로 치료 전후 상담을 통해 기대 결과와 관리법을 확인하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gum-graft';
UPDATE dict_terms SET full_desc='<p>치근 활택술은 스케일링으로 제거되지 않은 치아 뿌리 표면의 치석과 감염된 시멘트질을 부드럽게 깎아내어 뿌리를 매끈하게 만드는 치료입니다. 매끈한 뿌리면은 잇몸과 치아 사이에 세균이 덜 쌓이도록 도와 잇몸 염증을 가라앉히고 잇몸뼈 손실 진행을 늦출 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치근 표면에 남아 있는 세균 덩어리와 변성된 표층을 제거하면 잇몸 조직이 건강한 치아 표면에 다시 부착되기 쉬워집니다. 일반적으로 국소 마취 후 여러 부위를 나누어 시행하며, 깊은 치주낭에서는 더 세심한 치료가 필요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치주낭 깊이가 4mm 이상으로 잇몸염증이 지속될 때</li>
  <li>스케일링만으로 염증이 호전되지 않을 때</li>
  <li>치아 뿌리 표면에 착색·치석이 남아 있는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 후 일시적 과민증이나 통증이 있을 수 있으며 부드러운 칫솔질과 구강위생 유지가 중요합니다. 경우에 따라 여러 번에 나누어 치료하며, 필요 시 이음치과 등에서 추가 평가와 관리가 권장됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='root-planing';
UPDATE dict_terms SET full_desc='<p>잇몸 절제술은 과도하게 증식한 잇몸 조직을 외과적으로 잘라내어 잇몸 가장자리와 치아 모양을 정상에 가깝게 되돌리는 시술입니다. 국소마취로 외래에서 시행되며, 잇몸이 지나치게 덮여 치아 관리가 어렵거나 심미적 불만이 있을 때 적용합니다.</p>

<h3>원리 또는 특징</h3>
<p>잇몸 절제술은 부풀어 오른 연조직을 제거해 치아의 임상적 길이를 늘리고 치주포켓을 줄여 구강 위생을 개선합니다. 칼, 레이저, 전기소작기 등으로 조직을 절제하며 출혈과 치유 양상이 방법마다 다릅니다. 회복은 보통 1~2주가량 걸립니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>약물(항경련제, 칼슘차단제, 면역억제제)으로 인한 잇몸 비대</li>
  <li>만성 염증으로 잇몸이 과도하게 증식한 경우</li>
  <li>심미적 이유(거미 스마일)나 보철·충전 전 치아 길이 확보</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>뼈 손실이나 치주조직 부착이 심하면 단순 절제술보다 골격을 다루는 크라운 레이텅(crown lengthening)이 필요할 수 있습니다. 시술 후 통증, 민감감, 출혈이 있을 수 있으니 초기에는 부드러운 칫솔질과 구강위생 관리가 중요합니다. 자세한 평가는 이음치과에서 상담받으시기 바랍니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gingivectomy';
UPDATE dict_terms SET full_desc='<p>플랩 수술은 잇몸을 국소마취로 절개해 잇몸조직을 들어 올려 치아 뿌리와 뼈를 직접 보면서 치료하는 시술입니다. 스케일링으로 제거하기 힘든 깊은 치석과 염증 조직을 직접 제거하고, 필요하면 뼈 모양을 다듬거나 재생 치료를 병행해 염증을 줄이고 치주 상태를 개선합니다.</p>

<h3>원리 또는 특징</h3>
<p>잇몸을 열어 시야를 확보하면 치아 뿌리 표면과 뼈 결손을 정확히 보며 완전한 제거와 정리를 할 수 있습니다. 경우에 따라 뼈 성형(osteoplasty)이나 골재생재료를 사용하며 대부분 국소마취로 시행하고 봉합 후 1~2주에 실밥을 제거합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
<li>치주낭 깊이 5~6mm 이상으로 비수술적 처치로 호전되지 않을 때</li>
<li>지속적 출혈이나 농양, 염증이 반복되는 경우</li>
<li>치근 사이(퍼케이션) 침범이나 뼈 결손이 있는 경우</li>
<li>뼈 형성이나 재생 치료가 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>수술 후 붓기·통증·약간의 출혈이 있을 수 있으므로 처방약과 구강관리 지시를 따르는 것이 중요합니다. 흡연은 치유를 방해하므로 삼가야 하며, 정기적인 치주 관리로 재발을 예방하는 것이 성공률을 높입니다. 자세한 검진은 이음치과에서 확인할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='flap-surgery';
UPDATE dict_terms SET full_desc='<h3>턱관절 장애란?</h3>
<p>턱관절 장애(Temporomandibular Disorder)는 측두하악관절과 주변 저작근의 기능 이상으로 나타나는 증상들의 묶음입니다. 입을 벌리거나 닫을 때 통증, 딱딱거리거나 클릭 소리, 입 벌림의 제한 등으로 생활에 불편을 주며 스트레스, 이갈이(bruxism), 외상 등이 흔한 유발 요인입니다.</p>

<h3>원리 또는 특징</h3>
<p>관절 안의 디스크 위치 이상, 관절 연골의 염증, 또는 저작근의 과긴장 때문에 통증과 운동 제한이 생깁니다. 교합(어금니 맞물림) 문제나 보철물, 사고로 인한 손상도 영향을 주며 증상은 일시적이거나 만성으로 진행될 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>턱을 움직일 때 소리(딱딱·클릭)가 자주 남</li>
  <li>입을 크게 벌리기 어렵거나 걸림이 느껴짐</li>
  <li>지속적인 턱·얼굴·측두부 통증, 귀 주변 통증</li>
  <li>밤에 이갈이하거나 스트레스가 많은 경우 증상 악화</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단은 임상 검사와 필요 시 영상(파노라마, CBCT, MRI)으로 확인합니다. 대부분은 약물, 물리치료, 교합 안정장치(스플린트), 행동수정(이갈이·스트레스 관리) 같은 비수술적 치료로 호전됩니다. 수술은 일부에서만 고려되므로 전문의와 상담이 중요하며, 필요하면 이음치과에서 평가받을 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tmd';
UPDATE dict_terms SET full_desc='<h3>핵심 설명</h3>
<p><strong>이갈이(Bruxism)</strong>는 낮이나 수면 중 무의식적으로 이를 가거나 꽉 무는 습관입니다. 반복적인 마찰과 과도한 힘은 치아의 마모·균열, 턱관절 통증, 두통과 얼굴 근육의 긴장으로 이어져 일상생활에 영향을 줄 수 있으며 스트레스·수면장애·교합 이상이 복합적으로 작용합니다.</p>

<h3>원리 또는 특징</h3>
<p>턱 주변 근육의 반복적이고 과도한 수축으로 치아에 비정상적 힘이 가해집니다. 시간이 지나면 법랑질 마모, 치아파절, 보철물 손상과 함께 턱관절 증상이 나타나며 야간형과 주간형으로 나뉘고 본인이 인지하지 못하는 경우가 많습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>잦은 스트레스나 불안이 있을 때</li>
  <li>코골이·수면무호흡 등 수면 문제 동반 시</li>
  <li>턱관절 통증·두통이 지속되거나 보철물이 자주 손상될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치료는 원인 평가와 증상 완화가 목표입니다. 야간용 스플린트로 치아를 보호하고 물리치료, 스트레스 관리, 필요시 교합조정 등을 병행합니다. 증상이 오래가면 턱관절 전문 진료(예: 이음치과 TMJ클리닉)를 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='bruxism';
UPDATE dict_terms SET full_desc='<h3>스플린트란</h3>
<p>스플린트는 환자마다 맞춰 제작하는 얇은 투명 아크릴성 교합 장치로, 주로 취침 중 착용하여 이를 가는 습관(브룩시즘)에서 오는 치아 마모를 막고 턱관절과 씹는 근육에 가해지는 부담을 줄여주는 보조 치료기구입니다. 치료 전 진단 목적이나 통증 완화에도 사용됩니다.</p>

<h3>원리 또는 특징</h3>
<p>딱딱한 아크릴로 된 평활한 교합면이 상·하 악의 접촉을 조절해 불규칙한 힘을 분산시킵니다. 착탈식이라 관리·조정이 쉽고, 치과에서 개인 맞춤으로 교합고도를 조절해 증상 완화 효과를 얻습니다. 투명해 일상생활에 큰 불편이 적습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>밤에 이를 가는 습관으로 인한 치아 마모 또는 통증</li>
  <li>턱관절의 통증·소리(클릭) 또는 씹을 때 불편감</li>
  <li>치아 마모로 인한 시린 증상이나 교합불안정</li>
  <li>교정·보철 전 교합 진단 목적</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>스플린트는 증상 완화에 효과적이나 근본 원인(스트레스, 수면습관 등) 치료와 함께해야 합니다. 정기적인 치과 방문으로 맞춤 조정이 필요하며, 장기간 부적절 사용 시 치아 이동이 생길 수 있으므로 전문의 지시에 따라 관리하세요. 이음치과에서도 개별 맞춤 제작과 추적 관리를 제공합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='splint';
UPDATE dict_terms SET full_desc='<p>개구제한은 입을 벌리는 능력이 줄어 평소처럼 음식물 섭취나 말하기가 어려운 상태를 말합니다. 보통 앞니 간 최대 벌림이 <strong>약 40mm 미만</strong>이면 개구제한으로 판단하며, 갑작스러운 통증이나 서서히 진행되는 제한 모두 가능해 원인과 경과가 다양합니다.</p>

<h3>원리 또는 특징</h3>
<p>턱관절(Temporomandibular joint) 내부 구조 이상이나 주변 근육의 경련·염증, 관절염이나 외상으로 인한 섬유화가 주된 원인입니다. 증상으로 통증, 관절음(딱딱거림), 한쪽으로 치우친 개구 등이 나타날 수 있고 급성기와 만성기로 나뉩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>턱관절장애(TMJ disorder)로 인한 관절·디스크 문제</li>
  <li>치과 시술 후 근육 경직 또는 마비 관련 제한</li>
  <li>교통사고·안면 외상으로 인한 관절 손상</li>
  <li>퇴행성 관절염 또는 염증성 질환</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단은 문진과 앞니 간 거리 측정, 임상검사로 시작하며 필요 시 X선·MRI로 원인을 확인합니다. 치료는 통증조절 약물, 물리치료, 턱관절 운동치료, 교합 조정 등 단계적으로 진행하고 심한 경우 전문적 시술이 필요합니다. 자세 교정과 스트레스 관리가 증상 완화에 도움이 되고, 정확한 평가는 이음치과 턱관절 전문의와 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='limited-opening';
UPDATE dict_terms SET full_desc='<p>관절원판은 아래턱과 위턱사이 턱관절 내부에 납작하게 자리한 섬유성 연골조직으로, 입을 벌리고 닫을 때 관절면 사이에서 충격을 흡수하고 미끄러지며 움직임을 부드럽게 해주는 쿠션 역할을 합니다. 손상되면 소리나 통증, 개구장애가 생길 수 있습니다.</p>
<h3>원리 또는 특징</h3>
<p>섬유연골로 된 이 원판은 상·하 관절강을 나누어 회전과 번위(전방 이동)를 가능하게 하고, 하중을 넓게 분산합니다. 혈류가 적어 손상 시 회복이 느리고, 위치이탈(전위)이 흔합니다.</p>
<h3>관련 상황</h3>
<ul>
  <li>턱을 벌릴 때 딱소리(클릭)나 걸리는 느낌</li>
  <li>입이 잘 안 벌어지거나 한쪽으로만 열리는 경우</li>
  <li>턱관절 통증, 저작 시 불편감</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>초기에는 보존적 치료(자가관리, 물리치료, 야간 스플린트, 약물)가 우선이며, 정확한 진단은 <strong>MRI</strong>로 확인합니다. 상태가 심하면 전문의의 추가적 치료나 수술이 필요할 수 있으니 이음치과에서 상담받아 현재 상태와 적절한 치료계획을 확인하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='articular-disc';
UPDATE dict_terms SET full_desc='<h3>교정 치료란</h3>
<p>교정은 치아의 배열과 위아래 치아가 맞물리는 관계(교합)를 바르게 잡아 구강 기능과 외모를 개선하는 치과 전문 치료입니다. 브래킷·와이어나 투명 교정장치 등으로 치아에 일정한 힘을 가해 서서히 이동시키며, 성장기 아동부터 성인까지 개인 상태에 맞춰 계획합니다. <strong>이음치과</strong>에서도 맞춤형 평가를 통해 치료 방향을 제시합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아에 가해지는 지속적이고 조절된 힘이 치조골(치아를 둘러싼 뼈)을 재형성하여 치아 위치를 바꿉니다. 고정식(브래킷·와이어)과 가철식(투명 교정장치)이 있고, 치료 기간은 수개월에서 수년까지 다양합니다. 완료 후 재발을 막기 위해 유지장치가 필요합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치열이 고르지 않거나 덧니, 앞니 벌어짐</li>
  <li>과도한 깊은 교합·반대교합 등 물림 이상</li>
  <li>교합 불균형으로 인한 저작 장애나 턱관절 통증</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치료 중 초기 불편감이나 통증이 있을 수 있으나 대부분 일시적입니다. 치아 이동 속도와 기간은 개인차가 커 정기 관찰이 중요하며, 성인도 충분히 치료 가능합니다. 치료 전 X선·모형·사진으로 정밀 계획을 세우고, 유지관리(교정 후 유지장치 착용)가 성공에 큰 영향을 미칩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='orthodontics';
UPDATE dict_terms SET full_desc='<h3>투명교정이란</h3>
<p>투명교정은 환자의 치아모형을 3D로 분석해 얇은 투명 플라스틱 트레이를 순차적으로 교체하며 치아를 서서히 이동시키는 치료입니다. 눈에 잘 띄지 않아 사회생활이 많은 성인에게 인기이며, 치료계획과 경과 관리는 교정전문의가 직접 담당합니다(예: 이음치과).</p>

<h3>원리 또는 특징</h3>
<p>각 트레이는 치아를 조금씩 목표 위치로 밀어내는 모양으로 제작되어 일정 기간 착용하면 다음 단계로 넘어갑니다. 탈부착이 가능해 칫솔질·식사가 편하고, 금속장치보다 마찰·자극이 적은 편입니다. 다만 심한 골격성 부정교합이나 복잡한 치아 이동은 제한적일 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>덧니·벌어진 치아 같은 경도~중등도 배열 이상</li>
  <li>교정 후 재발로 인한 미세한 조정</li>
  <li>심미성을 우선시하는 성인 환자</li>
  <li>교합이나 턱관절 문제는 사전 평가가 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>성공률은 환자의 착용시간(일반적으로 하루 20~22시간)과 협조도에 크게 좌우됩니다. 치료 중에는 부착물(attachment)을 붙일 수 있고, 통증이나 저작 불편감이 일시적으로 생길 수 있습니다. 복잡한 골격성 문제나 심한 교합 불균형은 다른 치료가 필요할 수 있으니 전문의 상담을 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='clear-aligner';
UPDATE dict_terms SET full_desc='<h3>부정교합이란</h3>
<p>위아래 치아가 서로 맞물리는 방식이 정상에서 벗어난 상태를 말합니다. 단순한 치열 불균형에서부터 위턱 또는 아래턱의 위치 이상으로 인한 돌출입, 주걱턱 등까지 포함하며 저작, 발음, 얼굴 균형에 영향을 줄 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>부정교합은 치아 배열·턱뼈 위치·성장 패턴이 조화롭지 못해 발생합니다. 흔한 분류로 1급(치열 불균형), 2급(윗턱 상대적 돌출), 3급(아래턱 상대적 돌출)이 있고 유전, 성장 이상, 어린 시절 습관(손가락 빨기), 조기 치아 상실 등이 원인입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>씹거나 음식을 잘게 부수기 어려울 때</li>
  <li>발음 장애나 잇몸·치아 과도한 마모가 생길 때</li>
  <li>턱관절 통증, 두통 등 기능적 불편이 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>성장 시기 조기 진단으로 치료 범위가 넓어질 수 있으며, 성인에서는 교정치료만으로 개선이 어려운 경우 악교정수술이 필요할 수 있습니다. 치료는 교정과 턱관절 협진이 중요하며, 이음치과와 같은 전문 클리닉에서 정확한 진단 후 개인별 계획을 세우는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='malocclusion';
UPDATE dict_terms SET full_desc='<p>측두하악관절은 귀 바로 앞에서 아래턱뼈(하악골)와 머리뼈(측두골)가 만나는 관절로, 단순한 경첩이 아니라 관절원반(디스크)과 근육이 함께 움직이며 씹기·말하기·입 벌림 같은 복합 동작을 조절하는 중요한 구조입니다. 작은 이상에도 소리·통증·운동제한이 생길 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>관절원반이 관절면 사이에서 완충 역할을 하고, 회전(초기 개구)과 전진(큰 개구)이 결합된 이중 운동을 수행합니다. 교근·측두근·익돌근 등 여러 근육과 신경이 관여해 민감하며, 이갈이·외상·염증으로 문제가 생기기 쉽습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>턱에서 나는 클릭·딱거림 소리 또는 잡음</li>
  <li>턱 통증이나 씹을 때 불편감</li>
  <li>입이 잘 안 벌어지거나 한쪽으로 치우침</li>
  <li>두통·귀 통증 등이 함께 나타나는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>대부분은 생활습관 개선, 물리치료, 교합안정 장치(스플린트), 약물 등 보존적 치료로 호전됩니다. 필요 시 영상(MRI 등)과 전문적 평가가 도움이 되며, 증상이 지속되면 이음치과에서 정확한 진단과 맞춤 치료를 상담받으세요. 수술은 드뭅니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tmj-joint';
UPDATE dict_terms SET full_desc='<p><strong>교합지</strong>는 치아가 맞닿는 부위를 시각적으로 표시해 주는 매우 얇은 색종이입니다. 환자가 이를 깨물 때 색이 치아 표면에 묻어나와 접촉 지점과 범위를 보여 주므로 보철물이나 교정장치, 턱관절 치료 후 교합 상태를 확인하고 조정하는 데 쓰입니다.</p>

<h3>원리 또는 특징</h3>
<p>얇은 색층이 치아 표면에 잉크 자국을 남겨 접촉 위치를 표시합니다. 빨강·파랑 색이 흔하며 압력 크기나 접촉면적에 따라 자국 모양이 달라집니다. 간단하고 즉시 결과를 확인할 수 있어 임상에서 널리 사용됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>보철물(크라운·인레이) 장착 후 교합 조정</li>
  <li>교정치료나 스플린트(턱장치) 조정 시</li>
  <li>턱관절 증상으로 물었을 때의 접촉 확인</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>교합지는 유용하지만 단독 판단 기준은 아닙니다. 표기량은 기술자·환자의 힘에 따라 달라져 임상가의 경험과 환자 증상, 다른 검사 결과를 함께 고려해 조정합니다. 이음치과와 같은 진료실에서 보철 후 최종 교합을 확인할 때 자주 사용합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='articulating-paper';
UPDATE dict_terms SET full_desc='<p><strong>유치(젖니)</strong>는 아기가 처음 갖게 되는 치아로, 보통 생후 6개월경부터 차례로 나오며 모두 합쳐 20개가 됩니다. 단순히 영구치를 대신해 있다기보다 음식을 씹고 말하기를 돕고, 얼굴 형태를 유지하며 영구치가 올바르게 나올 수 있도록 길을 안내하는 중요한 역할을 합니다.</p>

<h3>원리 또는 특징</h3>
<p>유치는 법랑질이 얇고 치수(신경)가 상대적으로 커서 충치가 빨리 진행됩니다. 교환 시기에는 치근이 흡수되어 흔들리며 빠지고, 이 과정이 영구치 배열에 영향을 줍니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>정기 예방검진과 불소도포로 충치 예방이 필요할 때</li>
  <li>충치나 통증으로 보존치료(레진, 펄프치료)가 필요한 경우</li>
  <li>유치가 조기 상실되어 공간유지가 필요할 때</li>
  <li>발음·저작·치열 발달에 문제가 의심될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>유치는 영구치로 바뀌지만 관리가 소홀하면 영구치 건강에도 영향을 줍니다. 규칙적인 칫솔질, 당분 조절, 정기검진이 중요하며 필요하면 이음치과와 같은 소아치과 전문의에게 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='deciduous-tooth';
UPDATE dict_terms SET full_desc='<p>영구치는 유치가 빠진 뒤 자라나 성인기까지 평생 사용하는 치아를 뜻합니다. 유아기와 아동기·청소년기에 걸쳐 순서대로 맹출하며, 사랑니를 포함하면 보통 28개에서 최대 32개가 됩니다. 한번 상실되면 자연 재생되지 않아 평생 관리가 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>영구치는 절치·견치·소구치·대구치로 구분되며, 첫 큰어금니는 약 6세경, 앞니는 그 이후 순차적으로 나오고 사랑니는 17~30대에 나타날 수 있습니다. 법랑질이 단단하지만 충치나 외상으로 손상되면 회복 능력이 제한적입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>유치 탈락 후 정상적으로 영구치가 나오는 경우</li>
  <li>충치나 외상으로 치료가 필요한 경우(충전·신경치료 등)</li>
  <li>영구치 매복이나 맹출 이상으로 교정이 필요한 경우</li>
  <li>치아 상실 시 임플란트·브리지 등 대체 치료가 고려되는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>영구치는 재생되지 않기 때문에 올바른 칫솔질·불소도포·실란트·정기검진으로 예방이 최선입니다. 상실 시에는 보철 치료로 기능을 회복할 수 있으나, 치료 계획은 개인 상태에 따라 달라집니다. 필요하면 이음치과에서 전문의와 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='permanent-tooth';
UPDATE dict_terms SET full_desc='<p>실란트는 어금니의 좁고 깊은 홈에 투명하거나 흰색의 얇은 수지 코팅을 발라 세균과 음식물이 쌓이는 것을 물리적으로 막아 충치를 예방하는 간단한 처치입니다. 주로 통증 없이 짧은 시간에 끝나므로 어린이 예방치료로 널리 사용됩니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 표면을 깨끗이 한 뒤 액상 수지를 홈에 채우고 광원으로 경화시켜 표면을 밀봉합니다. 치아와 기계적·화학적으로 결합해 홈을 평탄하게 만들어 플라그 축적을 감소시키고, 일부 제품은 불소를 포함해 예방 효과를 보강합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>새로난 영구 어금니(6세·12세 전후)에 예방 적용</li>
  <li>깊고 좁아 칫솔로 닦기 어려운 치아 홈</li>
  <li>충치 발생 위험이 높은 어린이(과거 충치력·과도한 당 섭취 등)</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>이미 충치가 있는 부위에는 먼저 치료가 필요하며, 실란트는 영구적이지 않아 마모나 박리 시 보충해야 합니다. 정기검진으로 상태를 확인받고 불소도 병행하면 예방 효과가 큽니다. 자세한 상담은 이음치과에서 도와드립니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='sealant';
UPDATE dict_terms SET full_desc='<h3>불소 도포란</h3>
<p>불소 도포는 아이의 치아 표면에 고농도 불소제(젤·바니쉬)를 얇게 발라 법랑질을 강화하고 충치가 시작되는 것을 막는 짧은 예방 시술입니다. 시술은 아프지 않고 몇 분 안에 끝나며, 어린이의 초기 충치 예방에 효과적입니다.</p>

<h3>원리 또는 특징</h3>
<p>불소는 법랑질에 침착되어 산에 대한 저항성을 높이고 미네랄 손실을 되돌리는 재광화 과정을 돕습니다. 바니쉬는 표면에 오래 남아 지속효과를 주고, 젤이나 폼은 짧은 시간 접촉해도 효과를 냅니다. 삼키지 않게 주의하며 적용합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>충치 위험이 높은 영유아·소아(자주 간식 섭취, 낮은 구강위생)</li>
  <li>초기 백색반(법랑질 탈회) 소견이 관찰될 때</li>
  <li>교정치료 등 치아 관리가 어려운 시기</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술은 안전하지만 과다 복용은 피해야 하므로 삼킴을 최소화합니다. 바니쉬 도포 후 30분에서 1시간은 음식·음료 섭취를 피하는 것이 좋고, 필요 빈도는 3~6개월마다 위험도에 따라 달라집니다. 자세한 상담은 이음치과에서 구강 상태를 확인받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='fluoride-application';
UPDATE dict_terms SET full_desc='<h3>맹출이란</h3>
<p>맹출은 입 안에서 보이는 치아가 턱뼈 속에서 형성되어 잇몸을 뚫고 구강으로 나오는 과정입니다. 유치는 보통 생후 6개월경부터, 영구치는 약 6세경부터 시작되며 개인차가 큽니다. 잇몸 붓기·침흘림·장난감 물기 등 불편감이 있을 수 있으나 대개는 자연스럽게 진행됩니다.</p>

<h3>원리 또는 특징</h3>
<p>치아는 치근과 치관이 만들어지며 뼈와 잇몸을 따라 점차 위로 이동해 잇몸을 관통합니다. 시기와 순서는 유전·영양·전신 상태에 따라 달라지고, 때로는 매복(나오지 않음)이나 이상 위치로 맹출될 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>맹출 지연: 같은 연령대의 또래보다 늦게 나오는 경우</li>
  <li>통증·심한 부종: 일상생활에 지장을 주는 경우</li>
  <li>영구치의 맹출 이상: 어긋나거나 매복된 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>맹출기에는 젖은 거즈로 잇몸을 닦아 청결을 유지하고, 통증이 심하면 소아과·치과 상담이 필요합니다. 고열·과다 출혈이 있거나 맹출 이상이 의심되면 전문치과에서 평가를 받아야 하며, 정기검진은 이음치과 같은 전문기관에서 받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='eruption';
UPDATE dict_terms SET full_desc='<h3>무엇인가요?</h3>
<p>과잉치는 정상적으로 있어야 할 치아 수보다 추가로 생기는 여분의 치아를 말합니다. 특히 윗앞니(상악 전치) 부위에 생기는 경우가 많아 소아에서 쉽게 발견되며, 모양은 뾰족하거나 작은 치아 형태로 나타날 수 있습니다. 위치와 크기에 따라 영구치 맹출이나 배열에 영향을 줄 수 있어 방사선 검사로 확인합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 발생 시 치아원반(dental lamina)의 과다활동으로 생기는 것으로 추정됩니다. 대부분은 하나(단발성)로 나타나며 비대칭일 수도 있고, 드물게 여러 개이거나 유전성·증후군 관련으로 나타날 수 있습니다. 형태와 위치에 따라 메시오덴스(중앙부) 등으로 분류됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>영구치의 맹출 지연 또는 방향 변위</li>
  <li>치열의 혼잡·정렬 문제로 교정 치료가 필요한 경우</li>
  <li>낭종이나 주변 조직 손상 의심 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>예후는 위치와 증상에 따라 다릅니다. 문제가 없으면 관찰만 할 수 있고, 영구치 맹출을 방해하거나 교정계획에 지장을 주면 소아 마취 또는 국소마취로 발치합니다. 방사선 검사와 정기검진으로 시기를 판단하는 것이 중요하며, 의심되면 소아치과 전문의와 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='supernumerary-tooth';
UPDATE dict_terms SET full_desc='<p>유착치란 유치(젖니)의 뿌리 표면이 주변 치조골과 직접 붙어 치주인대 없이 고정된 상태를 말합니다. 정상적으로는 유치가 흔들리며 빠지고 그 자리에 영구치가 나오지만, 유착이 생기면 흔들지 않거나 아래로 내려가지 않아 영구치 맹출을 방해할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>정상 치아는 치주인대라는 결합조직으로 뼈와 분리되어 있지만, 외상이나 염증·발육 이상 등으로 치근 표면이 뼈와 직접 결합하면 유착이 발생합니다. 임상에서는 해당 유치가 주변 치아보다 낮게(함몰/저협) 보이거나 타진 시 높은 소리가 나는 특징이 있습니다. 방사선에서 뿌리와 뼈가 연속적으로 보이기도 합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>유치가 정상 시기에 빠지지 않고 주변치보다 낮게 보일 때</li>
  <li>외상력이나 반복 염증 병력이 있는 어린이</li>
  <li>영구치 맹출 지연이나 위치이상(옆으로 틀어짐, 공간 소실)이 의심될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단은 임상검사와 방사선 촬영으로 확인하며, 경미하면 경과 관찰, 증상이 있거나 영구치 맹출에 장애가 있으면 발치·외과적 박리·교정적 처치가 필요할 수 있습니다. 치료 계획은 나이와 영구치 상태에 따라 다르므로 소아치과 전문의와 상의하는 것이 좋고, 이음치과 소아치과에서도 개별 평가 후 적절한 치료를 안내합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='ankylosed-tooth';
UPDATE dict_terms SET full_desc='<h3>발치란 무엇인가요?</h3>
<p>발치는 치아가 회복이나 보존 치료로 더 이상 유지될 수 없을 때 구강에서 꺼내는 외과적 시술입니다. 간단히 집게로 빼는 단순 발치부터 잇몸을 절개하거나 뼈를 일부 깎아 분할해 빼는 외과적 발치까지 방법이 있으며, 통증 경감을 위해 국소마취나 필요 시 진정요법을 병행합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아를 둘러싼 조직을 분리하고 치아를 고정하는 결합조직과 골을 조절해 제거합니다. 매복치나 복잡한 골 구조에서는 뼈를 소량 제거하거나 치아를 분할해 꺼내며, 시술 후에는 출혈·부종·통증이 흔하지만 적절한 관리로 회복됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
<li>심한 충치로 치아 보존이 불가능할 때</li>
<li>치주질환으로 치아 지지 조직이 크게 손상된 경우</li>
<li>매복된 사랑니나 교정 치료를 위해 공간 확보가 필요할 때</li>
<li>반복적 감염 또는 치아 골절 등으로 통증·위험이 계속될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>발치 전 엑스레이와 진단으로 계획을 세워야 하며, 시술 후에는 지혈·진통제·구강 위생 지침을 잘 따라야 합니다. 흡연·과한 양치질·세게 헹구기는 합병증(예: 건조증)을 일으킬 수 있으니 주의하세요. 궁금한 점은 이음치과에서 상담받으시면 도움이 됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='extraction';
UPDATE dict_terms SET full_desc='<p><strong>사랑니(제3대구치)</strong>는 보통 17~25세 사이에 마지막으로 나오는 큰어금니입니다. 턱뼈와 잇몸에 공간이 부족하면 완전히 맹출하지 못하거나 옆으로 기울어 나오며 주변 치아와 충돌해 통증, 염증을 반복할 수 있습니다. 상황에 따라 관찰만 하거나 발치가 필요합니다.</p>

<h3>원리 또는 특징</h3>
<p>턱 성장·유전적 요인과 공간 부족이 맞물려 사랑니 문제를 만듭니다. 부분적으로만 나오면 음식물과 세균이 쌓여 주위염이 자주 생기고, 인접 치아 우식이나 낭종이 생길 수 있습니다. 매복 정도에 따라 치료 방법이 달라집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>반복되는 잇몸 붓기나 통증(주위염)</li>
  <li>옆 치아에 충치나 치열 이상이 생긴 경우</li>
  <li>완전 매복 또는 방사선상 낭종 의심 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>모든 사랑니를 뽑을 필요는 없습니다. 방사선 검사로 치아 위치와 하치조신경과의 관계를 확인한 뒤 발치 여부를 결정하며, 발치 시 드문 신경손상·출혈 위험이 있습니다. 경험 있는 구강외과에서 정확한 평가를 받는 것이 중요하며, 필요 시 이음치과에서 세부 계획을 세울 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='wisdom-tooth';
UPDATE dict_terms SET full_desc='<h3>매복치(Impacted Tooth)란?</h3>
<p>매복치는 잇몸이나 턱뼈 속에 전부 또는 일부가 남아 정상적으로 나오지 못한 치아를 말합니다. 특히 사랑니에서 흔하게 보이며, 완전히 매복되거나 일부만 보이는 경우가 있습니다. 증상은 없을 수도 있지만 염증이나 통증, 주변 치아 손상으로 이어질 수 있어 진단과 관리가 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>주된 원인은 공간 부족, 치아의 방향 이상(비정상 각도), 또는 앞치아의 위치에 의해 맹출 경로가 막히는 경우입니다. 방사선(파노라마)으로 위치와 뿌리 형태를 확인하면 완전 매복인지 부분 매복인지, 인접 조직과의 관계를 판단할 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>지속적이거나 반복되는 잇몸 염증·통증이 있을 때</li>
  <li>매복치가 인접 치아의 뿌리를 압박하거나 충치를 일으킬 때</li>
  <li>낭종이나 병리 소견이 의심될 때</li>
  <li>교정 치료 중 방해 요인이 될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치료는 증상과 위치에 따라 관찰, 항생제·배농, 또는 외과적 발치 등으로 달라집니다. 발치는 비교적 흔한 시술이지만 위치에 따라 난이도가 다르며 회복 기간과 합병증 위험을 고려해 결정합니다. 자세한 진단과 상담은 이음치과 같은 전문의에게 문의해 최적의 치료 계획을 세우는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='impacted-tooth';
UPDATE dict_terms SET full_desc='<h3>건성 소켓(드라이 소켓)이란?</h3>
<p>발치 자리에서 정상적으로 형성되어야 할 혈병(피떡)이 빠지거나 녹아 없어져 치조골이 드러나면서 심한 통증과 불편을 유발하는 합병증입니다. 보통 발치 후 2~4일 사이에 심한 통증이 시작되고, 입냄새나 씹을 때 통증이 악화되는 경우가 많습니다.</p>

<h3>원리 또는 특징</h3>
<p>혈병은 뼈와 신경을 보호하고 조직 재생을 돕는 역할을 합니다. 혈병이 소실되면 노출된 치조골이 타액이나 음식물에 자극을 받아 염증과 강한 통증이 생깁니다. 육안으로 발치 구멍이 깊게 보이고 통증이 퍼지는 양상이 특징이며, 방치하면 회복이 길어질 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>발치 후 2~4일 사이에 갑자기 통증이 시작될 때</li>
  <li>흡연이나 세게 가글하는 습관이 있는 경우</li>
  <li>난이도가 높은 발치나 기존 감염이 있던 부위</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>예방을 위해 발치 후 48~72시간은 금연하고 과도한 양치나 가글을 피하는 것이 좋습니다. 통증이 있으면 곧바로 치과를 방문해 상처 세척과 약물 드레싱, 진통 처치를 받으면 증상 경감에 도움이 됩니다. 필요하면 항생제나 통증 조절 약을 사용하며, 자세한 상담은 이음치과 등 전문 치과에서 받으시기 바랍니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dry-socket';
UPDATE dict_terms SET full_desc='<p>구강암은 혀·잇몸·입천장·입술·볼 안쪽 등 구강 점막에서 생기는 악성 종양입니다. 초기엔 작은 궤양이나 단단한 덩어리로 시작해 통증 없이 진행될 수 있어 조기 발견이 치료 결과에 큰 영향을 줍니다. 낫지 않는 구내염이나 변화가 있으면 치과나 구강외과에서 검사가 필요합니다.</p>

<h3>원리 또는 특징</h3>
<p>대부분 편평상피세포에서 시작하며 흡연·음주·인유두종바이러스(HPV) 감염 등이 위험요인입니다. 크기와 주변 침윤 정도, 림프절 전이 유무로 병기와 치료방법이 결정됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>2주 이상 낫지 않는 구강 궤양 또는 통증 없는 덩어리</li>
  <li>설소대나 혀의 지속적 통증·운동장애</li>
  <li>비정상 출혈·입냄새·발음 변화 또는 삼킴 곤란</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기 발견 시 수술·방사선·항암치료로 완치 가능성이 높아집니다. 조직검사로 확진하며 치료계획은 개인별로 달라집니다. 증상이 있으면 이음치과와 같은 전문 진료에서 조기에 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='oral-cancer';
UPDATE dict_terms SET full_desc='<h3>낭종이란 무엇인가요?</h3>
<p>턱뼈나 주변 연조직 안에 점차 커지는 막성 주머니로, 내부에 액체나 반고체 물질이 차는 병변입니다. 크기가 작을 때는 증상이 없지만 커지면 통증, 치아 이동, 뼈 흡수 등이 생길 수 있습니다. 구강X선이나 CT에서 우연히 발견되는 경우가 많습니다.</p>

<h3>원리 또는 특징</h3>
<p>대부분 치아 발생 과정과 관련된 상피로부터 유래하며 종류에 따라 성장 속도와 재발률이 다릅니다. 예를 들어 치근단 낭종(치아 감염에 따른 것), 함치성 낭종(맹출되지 않은 사랑니 주위) 등이 있고, 영상에서 뚜렷한 방사선 투과부로 보입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치아 감염 후 방사선 검사에서 투과음영이 보일 때</li>
  <li>사랑니 주변이 붓거나 통증이 반복될 때</li>
  <li>턱이 부어오르거나 치아 배열이 변할 때</li>
  <li>구강검진 중 우연히 음영 병변이 발견될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>확진을 위해 조직검사(생검)를 시행하고, 치료는 보통 낭종 제거술(낭종낭포절제)이나 일부는 봉합개방(marsupialization)이 필요합니다. 종류에 따라 재발 위험이 있으므로 수술 후 경과 관찰이 중요합니다. 의심되면 전문의 상담을 받아 이음치과 등에서 영상검사와 치료 계획을 세우는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cyst';
UPDATE dict_terms SET full_desc='<h3>봉합이란 무엇인가요?</h3>
<p><strong>봉합(수저)</strong>은 발치나 임플란트, 잇몸 수술 등으로 절개되거나 손상된 구강 조직을 실로 연결해 상처를 안정시키고 치유를 돕는 시술입니다. 적절히 조직 가장자리를 맞대어 출혈을 줄이고 재생이 잘 일어나도록 합니다.</p>

<h3>원리 또는 특징</h3>
<p>봉합은 조직을 물리적으로 고정해 조직간 접촉을 유지하고 지혈을 돕습니다. 실은 <strong>흡수성</strong>과 <strong>비흡수성</strong>으로 나뉘며, 흡수성은 시간이 지나 녹아 없어지고 비흡수성은 치료 후 제거해야 합니다. 입안 환경과 수술 부위에 따라 실 종류와 제거 시기가 달라집니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>사랑니·일반 발치 후 출혈 방지 및 조직 봉합</li>
  <li>임플란트 식립 시 절개부 봉합</li>
  <li>치주수술(잇몸 수술) 후 잇몸 재위치 고정</li>
  <li>구강 내 외상으로 찢어진 점막·연조직 봉합</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>일반적으로 5~14일 사이에 실을 제거하거나 흡수되는 것을 확인합니다. 과도한 통증·지속 출혈·고름·열이 있으면 즉시 진료가 필요합니다. 식사나 칫솔질 시 봉합부를 건드리지 말고, 따뜻한 소금물 가글로 청결을 유지하세요. 필요한 경우 이음치과에서 추후 관리와 실 제거를 안내받으실 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='suture';
UPDATE dict_terms SET full_desc='<h3>CBCT란 무엇인가요?</h3>
<p>CBCT(콘빔 CT)는 치과 전용 3차원 X선 촬영 장비로, 원뿔형 빔으로 짧은 시간에 턱뼈와 치아의 입체 영상을 얻습니다. 평면 X선이나 파노라마에서 보이지 않는 뼈의 두께, 신경관 위치, 치아의 기울기 등을 정확히 파악해 치료 계획의 안전성과 예측성을 높여 줍니다.</p>

<h3>원리 또는 특징</h3>
<p>원뿔 모양의 X선 빔과 평판 검출기를 회전시켜 다각도 영상을 획득하고 3D로 재구성합니다. 단단한 조직(뼈·치아) 표현에 우수하고 촬영 시간이 짧아 환자 부담이 적습니다. 다만 연조직 구별 능력은 낮고, 치아 금속물질로 인해 영상 왜곡(아티팩트)이 생길 수 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>임플란트 식립 전: 골량·신경 위치 확인</li>
  <li>매복치(사랑니 등) 위치와 인접 구조 평가</li>
  <li>복잡한 근관치료나 치근단 병소 진단</li>
  <li>턱뼈 골절·악관절 이상, 악성 또는 양성 병변 평가</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>일반 CT보다 방사선량이 낮지만 불필요한 촬영은 피하는 것이 좋습니다. 촬영 전 귀걸이 등 금속은 제거하고, 영상으로 얻은 정보를 바탕으로 이음치과에서 정확한 치료 계획을 설명받으시기 바랍니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cbct';
UPDATE dict_terms SET full_desc='<p>구강 스캐너는 입 안을 직접 촬영해 인상재(본뜨기) 없이 정밀한 3차원(3D) 디지털 모형을 만드는 장비입니다. 치아와 잇몸 표면을 빠르게 스캔해 보철물, 교정장치, 임플란트 수술계획에 활용할 수 있는 정확한 데이터를 얻습니다. 이음치과와 같은 치과에서 흔히 사용하는 장비입니다.</p>

<h3>원리 또는 특징</h3>
<p>광학식 센서가 빛을 쏘아 반사된 신호를 받아 형태를 재구성합니다. 기존의 물리적 인상보다 환자 불편이 적고, 데이터 전송이 쉬워 치과-기공소 간 소통이 빨라집니다. 색상 정보와 표면 질감까지 함께 기록되는 경우가 많습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>보철물 제작(크라운, 브릿지)의 정밀한 인상 대체</li>
  <li>교정 진단 및 가상 교정 시뮬레이션</li>
  <li>임플란트 식립 전 수술계획과 보철 디자인</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>스캔 품질은 구강 내 습기나 협조도에 영향받습니다. 치아 사이 교정장치나 반사성이 강한 재료는 추가 보정이 필요할 수 있고, 아주 깊은 치주낭이나 치아 밑부분은 보완 촬영이 필요할 때가 있습니다. 장단점을 진료 시 치과의사와 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='oral-scanner';
UPDATE dict_terms SET full_desc='<p>파노라마 X-레이는 위턱·아래턱과 모든 치아, 상악동(위턱의 공기 공간) 등을 한 장의 넓은 영상으로 촬영해 구강 전체 구조를 빠르게 살펴보는 검사입니다. 치아 배열, 매복치(매달린 사랑니), 낭종·골파괴 같은 큰 병변을 확인하는 초기 진단에 특히 유용합니다.</p>

<h3>원리 또는 특징</h3>
<p>환자 머리 주위를 X선 튜브와 검출기가 회전하면서 곡면상의 한 장 사진을 만듭니다. 촬영이 짧고 방사선량이 비교적 낮아 스크리닝 용도로 적합하지만, 영상이 2차원이라 구조가 겹칠 수 있어 미세한 병변이나 치근 단면은 잘 보이지 않습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>사랑니 매복 여부 및 대략적 위치 확인</li>
  <li>치아 배열·교합 상태의 전체적 평가</li>
  <li>낭종·종양, 골절 등 큰 병변의 선별 검사</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>방사선 노출은 낮지만 임신 초기에는 피하는 것이 원칙이고, 어린이·정밀 진단·임플란트 계획 등에서는 추가로 소아용 X선이나 3D CBCT가 필요할 수 있습니다. 이음치과와 같은 치과에서는 파노라마를 기본 검사로 활용해 필요한 추가 검사를 결정합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='panoramic-xray';
UPDATE dict_terms SET full_desc='<h3>3D 프린터란 무엇인가요?</h3>
<p>3D프린터는 컴퓨터로 설계한 치아와 턱 모양을 층층이 쌓아 실제 물체로 만드는 장비입니다. 치과에서는 환자 맞춤형 임플란트 수술용 가이드, 교정 장치, 임시 보철물 등 정밀한 보철·수술 보조물을 직접 제작해 치료 정확도와 작업 속도를 높입니다. 이음치과에서도 원내 가이드 제작에 활용합니다.</p>

<h3>원리 또는 특징</h3>
<p>광중합수지나 분말을 한 층씩 경화·융합해 형상을 완성합니다. CAD(컴퓨터 설계)데이터를 그대로 재현하므로 치아 형태와 수술 위치를 정밀하게 반영할 수 있고, 출력 해상도에 따라 세부 표현력이 달라집니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>임플란트 수술에서 정확한 드릴 가이드가 필요할 때</li>
  <li>임시 보철물(임시 크라운·브릿지) 제작 시</li>
  <li>교정장치(투명교정깍힘틀·리테이너) 제작이나 진단 모델이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>출력물은 재료와 후처리(세척·광중합)에 따라 강도와 생체적합성이 달라집니다. 인증된 치과용 재료와 장비를 사용하는지 확인하고, 치과에서 직접 제작하면 제작시간이 단축되지만 비용과 품질은 병원마다 차이가 있을 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='3d-printer';
UPDATE dict_terms SET full_desc='<p>CAD/CAM은 구강용 스캐너나 석고 모형으로 얻은 3차원 데이터를 컴퓨터에서 설계(CAD)한 뒤, 밀링 머신이나 3D프린터로 정밀 가공(CAM)하여 보철물을 만드는 디지털 시스템입니다. 수작업을 보완해 적합성과 심미성을 높이고 제작 시간을 줄이는 장점이 있어 심미보철에서 널리 쓰입니다. 이음치과에서도 적용하고 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>과정은 구강 스캐닝→컴퓨터에서 형태·맞춤 설계→밀링 또는 출력으로 가공의 3단계입니다. 지르코니아·세라믹·복합레진·PMMA 등 여러 재료를 쓸 수 있고, 밀링 후 연마·소결 같은 후처리가 필요할 수 있습니다. 디지털 파일 보관으로 재제작이 용이합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>단일 크라운(치관)이나 인레이·온레이 제작</li>
  <li>심미적 전치부 수복 및 맞춤 지대주 설계</li>
  <li>임플란트 보철의 수복물 설계 및 제작</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>장점은 정밀한 적합, 빠른 제작, 환자 맞춤 디자인 가능성이며 방문 횟수가 줄어듭니다. 단점으로는 장비·재료 비용과 일부 복잡한 경우에는 기존 수작업이나 추가 처리가 필요할 수 있다는 점을 염두에 두세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cad-cam';
UPDATE dict_terms SET full_desc='<p>플라즈마 소독기는 과산화수소를 이용해 저온에서 활성기(플라즈마)를 만들어 의료기구의 표면과 틈새에 남은 미생물을 제거하는 첨단 멸균장비입니다. 고온에 약한 플라스틱·광학부품이나 정밀수술 도구를 손상 없이 멸균할 수 있어 병원에서 감염관리를 강화할 때 쓰입니다.</p>

<h3>원리 또는 특징</h3>
<p>기기에 투입된 과산화수소가 전기에너지로 활성화되어 라디칼·활성산소를 생성하면 단백질과 핵산을 산화해 세균·바이러스·포자 등을 비활성화합니다. 증기멸균과 달리 비교적 낮은 온도에서 작동하고 잔류물이 거의 없어 민감한 기구에 적합합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>열·습기에 약한 플라스틱·광학 부품 멸균이 필요할 때</li>
  <li>소형 정밀 기구나 손잡이·소형 루멘을 가진 기구를 처리할 때</li>
  <li>수술실·시술실 등 고위험 환경에서 감염 관리를 강화할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>모든 물품에 적용 가능한 것은 아니며, 다공성 물질이나 긴 관은 제한됩니다. 기구의 전처리와 제조사 권고 사이클을 지켜야 안전하고 효과적입니다. 이음치과와 같은 의료기관에서는 고위험 기구 멸균에 활용되며 숙련된 인력이 운영합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='plasma-sterilizer';
UPDATE dict_terms SET full_desc='<p><strong>아쿠아케어(AquaCare)</strong>는 물과 아주 작은 분말을 고속으로 분사해 충치가 침범한 부위만 골라 제거하는 장비입니다. 일반 드릴보다 진동·소음이 적어 불안한 환자나 어린이에게 부담이 적고, 건강한 치아 조직을 최대한 보존해 수복물(레진) 유지에 유리합니다.</p>

<h3>원리 또는 특징</h3>
<p>미세한 분말(주로 생체친화적 탄산칼슘 등)을 물과 함께 분사하면 충치로 약해진 부분이 선택적으로 마모됩니다. 열·진동이 적어 마취 없이 시술 가능한 경우가 많고, 표면을 부드럽게 정리해 레진 접착성을 높여줍니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>초기~중등도 충치(우식) 제거</li>
  <li>치과 공포증이나 어린이 치료 시</li>
  <li>보존적 수복으로 레진을 사용할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>모든 충치에 적합한 것은 아니며, 깊은 충치나 치수 치료가 필요한 경우 드릴이나 추가 치료가 필요합니다. 분말에 따른 비용과 장비 제약이 있으므로 담당 치과의와 상담이 중요하며, 이음치과에서도 이 방법을 활용해 보존치료를 시행합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='aquacare';
UPDATE dict_terms SET full_desc='<h3>니트람(NiTi Rotary System)이란</h3>
<p>니트람은 니켈‑티타늄(NiTi) 합금으로 만든 회전형 근관 파일과 이를 구동하는 시스템을 말합니다. 탄성과 형태기억 특성이 있는 NiTi 파일이 회전하면서 좁고 구불구불한 치아 뿌리 속 근관을 보다 빠르고 균일하게 성형해 신경치료의 정확성과 안전성을 높여줍니다. 이음치과에서도 널리 쓰이는 장비입니다.</p>
<h3>원리 또는 특징</h3>
<p>NiTi 합금의 유연성 때문에 굴곡진 근관에 잘 따르며 원형 형상을 일정하게 만듭니다. 전동 모터로 일정한 속도와 토크로 회전시켜 수동 파일보다 시간 단축과 일관된 결과를 얻습니다. 다만 기구 파절을 줄이려면 적정 속도와 사용법, 교체 주기가 중요합니다.</p>
<h3>관련 상황</h3>
<ul>
  <li>근관(신경)치료 시 좁거나 심하게 굴곡된 근관</li>
  <li>치수폐색이나 재근관 치료가 필요한 경우</li>
  <li>정밀한 근관 형성과 시간 단축이 필요한 환자</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>전통적 수동 기구보다 치료가 빨라지고 통증과 불편감이 줄어들 수 있지만, 기구 파절 위험이 완전히 사라지지는 않습니다. 술자의 숙련도와 적절한 기구 관리가 결과에 큰 영향을 미치므로 담당의와 상담해 적절한 방법을 선택하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='nitram';
UPDATE dict_terms SET full_desc='<p><strong>교합기</strong>는 환자의 치아 맞물림과 턱 운동을 모형 위에서 재현하는 기계 장치입니다. 진료실에서 채득한 교합 기록이나 페이스보우를 이용해 석고 모형을 교합기에 장착하면 씹는 방향과 치아 간 접촉, 턱관절의 이동 경로를 모사하여 보철물의 형태와 접촉점을 미리 설계할 수 있습니다. 심미적 보철과 정밀 조정에 도움을 줍니다.</p>

<h3>원리 또는 특징</h3>
<p>교합기는 하악의 운동축과 관절 경로를 물리적으로 또는 소프트웨어로 모사합니다. 단순 고정형에서 반가동형, 완전가동형까지 정밀도가 다르며, 최근에는 디지털 스캔과 연동한 가상 교합기를 통해 컴퓨터상에서 시뮬레이션하는 방식도 널리 쓰입니다. 이를 통해 제작 오류와 의자간 조정 시간을 줄일 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>크라운·브릿지·베니어 같은 심미 보철물 제작 시</li>
  <li>부분 또는 총의치의 교합 균형을 확인할 때</li>
  <li>임플란트 보철이나 광범위한 교합 재건 계획 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>교합기는 매우 유용하지만 구강 내 근육·연조직 영향까지 완벽히 재현하지는 못합니다. 따라서 교합기에서 설계한 결과는 반드시 환자 구강에서 최종 확인하고 미세조정해야 합니다. 정확한 페이스보우와 교합 기록이 품질에 큰 영향을 미치며, 이음치과와 같은 전문 클리닉에서는 디지털과 아날로그 방법을 병행해 안전하게 활용합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='articulator';
UPDATE dict_terms SET full_desc='<p>바이트 등록은 위·아래 치아가 서로 맞물리는 위치와 높이(교합 관계)를 정확히 기록해 보철물이나 교정 장치 제작에 반영하는 과정입니다. 실리콘·왁스 같은 재료로 환자가 물린 상태를 본뜨거나, 디지털 스캐너로 물린 모습을 촬영해 치과 기공소나 CAD 소프트웨어에 전달합니다. 올바른 씹힘과 심미성 확보에 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>핵심은 환자가 편안한 상태에서 중심위(centric relation)와 수직고경을 고정해 형태를 보존하는 것입니다. 전통적 방법은 강성 재료로 인상체를 만들고, 디지털 방법은 구강 스캐너로 교합 스캔을 합성합니다. 정확하면 보철물 조정 횟수가 줄어듭니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>크라운·브리지·임플란트 보철 제작 시</li>
  <li>부분 또는 전체 틀니 제작과 조정 때</li>
  <li>심미적 재건이나 전악 수복을 계획할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>절차는 짧고 비침습적이며, 환자에게는 가볍게 물고 있으면 됩니다. 정확도가 결과 만족도에 큰 영향을 주므로 치과의사와 편안한 물림 위치를 상의하세요. 디지털 방법이 가능하면 의사와 상담해 선택하는 것이 좋습니다. (이음치과 기준으로도 동일한 원칙이 적용됩니다.)</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='bite-registration';
UPDATE dict_terms SET full_desc='<p><strong>디지털 인상</strong>은 구강 내를 비접촉 방식으로 촬영해 치아와 잇몸의 형태를 컴퓨터에서 처리 가능한 3차원(3D) 데이터로 만드는 방법입니다. 전통적 인상재를 사용한 본뜨기 대신 즉시 스캔 결과를 확인해 보철물 설계나 임플란트 보철 제작에 바로 활용할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>작은 광학 구강스캐너가 연속 촬영한 이미지들을 소프트웨어가 합성해 정밀한 3D 모델을 만듭니다. 실시간 화면 확인으로 재촬영 여부를 즉시 알 수 있고, 임플란트의 경우 스캔바디를 사용해 정확한 위치 정보를 얻습니다. 파일은 치과기공소로 전송되어 디지털 제작으로 이어집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>크라운·브릿지 등 보철물 제작 시</li>
  <li>임플란트 보철의 위치 확인 및 설계</li>
  <li>구강내 본뜨기 불편이 큰 환자(구역감, 구강소량)</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>환자에게는 구강불편이 적고 재촬영이 줄어드는 장점이 있습니다. 디지털 데이터 보관과 빠른 제작 연결도 강점이지만, 반사 표면이나 협소한 구강 환경에서는 스캔 정확도가 떨어질 수 있고 장비와 숙련도가 필요합니다. 이음치과에서 상담하면 환자 상황에 맞는 적용 여부를 안내받을 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='digital-impression';
UPDATE dict_terms SET full_desc='<p>티타늄은 치과 임플란트의 핵심 재료로, 뼈와 안정적으로 결합하면서도 가볍고 강한 금속입니다. 부식에 강한 표면 특성 덕분에 입안 환경에서도 오래 견디며, 픽스처(임플란트 몸체), 지대주, 고정용 나사 등에 주로 사용됩니다.</p>

<h3>원리 또는 특징</h3>
<p>티타늄 표면에 자연적으로 생기는 산화막이 골유착(osseointegration)을 돕고 조직 반응을 안정화합니다. 비자성에 가까워 MRI 검사 시 비교적 안전하고, 알레르기 반응은 매우 드뭅니다. 제조과정에서 합금화나 표면처리를 통해 강도와 골결합 성능을 개선합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
<li>빠진 치아를 대신할 인공치근(임플란트) 설치 시</li>
<li>보철물을 골에 단단히 고정해야 할 때(지대주·스크류)</li>
<li>골이식 후 고정 장치가 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>대부분 안전하지만 임플란트 주위 염증을 예방하려면 구강 위생과 정기검진이 필수입니다. 다른 금속과 함께 사용하면 전기화학적 반응이 생길 수 있으니 치과의사와 재료 선택을 상의하세요. 상세한 상담은 이음치과에서 받을 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='titanium';
UPDATE dict_terms SET full_desc='<h3>세라믹이란</h3>
<p>세라믹은 도자기 제작 원리를 치과용으로 응용한 재료로, 유리질과 결정상이 결합되어 자연치아와 유사한 색감과 광택을 재현합니다. 크라운·라미네이트·인레이 등에서 심미성과 생체적합성을 높이기 위해 널리 사용되며, 이음치과에서도 보편적으로 적용되는 재료입니다.</p>

<h3>원리 또는 특징</h3>
<p>주성분은 유리상과 결정상(예: 리튬디실리케이트, 지르코니아)으로 나뉘며, 유리상은 빛 투과성을, 결정상은 기계적 강도를 제공합니다. 표면이 매끄러워 착색이 잘 되지 않고 잇몸 친화적이지만, 금속보다 <strong>취성</strong>하여 충격에 의해 파절될 수 있습니다. 접착용 레진 시멘트로 결합하면 보존적 접착이 가능합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>앞니 심미 복원(라미네이트·베니어)</li>
  <li>치아 손상 부위 보철(크라운·온레이)</li>
  <li>충전재로서의 인레이·온레이 제작</li>
  <li>심미를 중시하는 임플란트 보철물</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>세라믹은 색 유지와 생체적합성이 뛰어나지만 두께가 얇거나 강한 교합력(이를 가는 습관)이 있으면 균열·파절 위험이 커집니다. 치료 전 치아 삭제량과 재료 선택(투명도·강도)을 치과의사와 충분히 상담하세요. 깨진 경우 수리가 어려워 보철물 교체가 필요할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='ceramic';
UPDATE dict_terms SET full_desc='<p>본딩은 치아 표면을 특별한 방법으로 처리한 뒤 레진(레진 복합재)을 치아에 붙여 모양과 색을 회복하거나 틈을 메우는 치료입니다. 보철처럼 씌우지 않고도 작은 깨짐이나 앞니의 모양 개선을 한 번의 내원으로 해결할 수 있어 심미적으로 많이 쓰입니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 표면에 산(에칭)을 이용해 미세한 요철을 만들고 본딩 에이전트를 도포하면 레진과 치아가 미세기계적·화학적으로 결합합니다. 최소한의 삭제로도 수복이 가능하고, 한 번의 진료에서 색 맞춤과 연마까지 마칠 수 있는 장점이 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>앞니의 작은 깨짐이나 모서리 손상 보수</li>
  <li>치아 사이 틈(빈칸) 메우기</li>
  <li>치아 변색의 국소적 개선이나 모양 교정</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>습기에 민감해 시술 시 건조한 환경이 중요하고, 큰 충치나 광범위한 손상에는 적합하지 않습니다. 시간이 지나면 변색·마모가 올 수 있어 유지·보수가 필요하며, 이음치과 같은 치과에서 상담 후 적절한 치료 계획을 세우는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='bonding';
UPDATE dict_terms SET full_desc='<h3>핵심 설명</h3>
<p>에칭은 치아표면에 약한 산을 짧게 발라 법랑질의 미세구조를 만들어 접착력을 높이는 전처리입니다. 주로 인산젤을 사용해 표면을 미세하게 거칠게 한 뒤 본딩제와 복합레진이 잘 흡착되도록 돕습니다. 충전이나 실란트, 교정 브라켓 접착 전에 흔히 시행됩니다.</p>

<h3>원리 또는 특징</h3>
<p>인산은 법랑질의 무기질 일부를 용해해 미세한 기공과 거칠기를 형성합니다. 이렇게 생긴 미세구조에 본딩제가 스며들어 기계적·화학적으로 결합하면 레진이 안정적으로 붙습니다. 농도는 보통 30~40% 인산젤, 적용 시간은 법랑질 15~30초, 상아질은 더 짧게 합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>복합레진 충전 또는 앞니 수복</li>
  <li>치아 홈 메우기(실란트) 시</li>
  <li>교정용 브라켓이나 라미네이트 접착</li>
  <li>보철물 수복 전 본딩 강화가 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 시 일시적인 시린감이 생길 수 있고 상아질을 과도하게 에칭하면 민감도가 증가합니다. 따라서 치과의사는 표면 상태에 따라 시간과 방법을 조절합니다. 안전하고 표준화된 절차로 이음치과 같은 치과에서 일상적으로 사용되는 방법입니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='etching';
UPDATE dict_terms SET full_desc='<h3>인상(치아 모형 채취) 안내</h3>
<p>인상은 치아와 잇몸의 실제 형태를 본떠 치료에 필요한 모형을 얻는 과정입니다. 알지네이트나 실리콘 같은 인상재를 맞춤 트레이에 넣어 입안에 위치시키고 굳히면 표면의 세부 모양을 복제해 보철물·틀니·교정장치 제작이나 심미 치료 계획에 활용합니다.</p>

<h3>원리 또는 특징</h3>
<p>인상재가 치아·점막 표면에 밀착해 경화되면 음영(negative) 형태가 만들어집니다. 알지네이트는 빠르고 비용이 적지만 시간이 지나면 변형되기 쉬우며, 실리콘 계열(추가중합 실리콘 등)은 정밀도와 안정성이 높아 크라운·브리지 등 정밀 보철에 적합합니다. 트레이 선택과 환자의 움직임이 결과에 큰 영향을 줍니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>크라운·브리지·임플란트 보철물 제작</li>
  <li>틀니·교정장치 등 보철·교정 장치 제작</li>
  <li>심미 치료 계획 및 진단용 모형 확보</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 중 약간의 이물감이나 구역감을 느낄 수 있고, 정확도를 위해 움직이지 않는 것이 중요합니다. 일부 경우 디지털 구강스캐너로 대체하면 더 편하고 변형 문제가 줄어듭니다. 재료별 비용과 목적에 따라 방법이 달라지므로 이음치과와 상담해 적절한 방식을 선택하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-impression';
UPDATE dict_terms SET full_desc='<p>왁스업은 최종 보철물이 구강 안에서 어떤 모양과 기능을 가질지 미리 모형 위에 왁스를 올려 만들어 보는 시뮬레이션입니다. 환자와 의사가 예상되는 치아 모양·높이·맞물림을 눈으로 확인하고 조정할 수 있어 치료 방향을 함께 결정하는 데 도움이 됩니다. 이음치과에서도 상담 단계에서 자주 사용하는 방법입니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 모형(또는 스캔 데이터)에 왁스를 조형해 수복물의 외형과 교합 접촉을 재현합니다. 보철물 설계, 심미성 평가, 치아 삭제 범위 결정, 보철물 제작을 위한 치기공 지시서 역할을 합니다. 구강 내 모형을 이용한 임시시뮬레이션(모크업)으로도 연결됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>심미적 보철(라미네이트·크라운) 전 환자 상담 시</li>
  <li>전체적 교합 재건이나 여러 치아를 동시에 치료할 때</li>
  <li>치아 형태·높이 변경으로 발음·저작이 영향을 받을 가능성 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>왁스업은 최종 결과의 예측을 돕지만 실제 보철물과 재료·임상 여건 차이로 결과가 달라질 수 있습니다. 필요하면 구강 내 임시물로 실제 느낌을 확인한 뒤 최종 제작에 반영합니다. 궁금한 점은 담당의와 충분히 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='wax-up';
UPDATE dict_terms SET full_desc='<p>치과용 시멘트는 크라운·브릿지·인레이·베니어 등 고정성 보철물을 본래 치아에 단단히 붙이고 가장자리를 막아 미세침투를 줄이는 접착 재료입니다. 종류에 따라 물리적 결합이나 화학적 결합을 통해 유지력을 제공하며, 일시적으로 사용하는 임시 시멘트부터 영구 고정용까지 목적과 재료에 따라 나뉩니다.</p>

<h3>원리 또는 특징</h3>
<p>시멘트는 치아나 보철물 표면과 결합해 유지력(기계적·화학적)을 만들고 가장자리를 밀봉합니다. 레진 시멘트는 강도와 심미성이 높고, 글라스아이오노머(GIC)는 플루오라이드 방출과 치아 친화성이 장점입니다. 경화 방식(광중합·자가중합·복합)도 다양합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>크라운·브릿지·인레이·온레이 등 영구 보철물 고정</li>
  <li>베니어·라미네이트 접착 시 심미적 고정</li>
  <li>근관 치료 후 포스트·코어 고정</li>
  <li>치료 중 임시 보철물 고정(임시 시멘트)</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>적절한 시멘트 선택은 보철물 재료, 치아 상태, 심미성 요구도에 따라 달라집니다. 시멘트 제거와 과량 정리는 중요하며, 일부는 광중합이 필요해 작업 장소의 접근성에 영향을 받습니다. 최종 선택은 치과의사가 평가해 결정하므로 자세한 상담은 이음치과에서 문의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-cement';
UPDATE dict_terms SET full_desc='<p>러버댐은 얇은 고무(라텍스 또는 논라텍스) 시트를 이용해 치료할 치아만 밖으로 노출시키고 입 안 나머지를 차단하는 방습 장치입니다. 근관치료나 레진 수복 중 타액·혈액·세균의 오염을 막아 접착력과 시술 정확도를 높이고, 작은 기구나 약제가 기도 쪽으로 들어가는 것을 예방합니다.</p>
<h3>원리 또는 특징</h3>
<p>치아에 클램프를 고정하고 고무 시트로 해당 치아만 물리적으로 격리하는 방법입니다. 멸균되고 건조한 작업 환경을 유지해 접착제가 제 성능을 발휘하고 세척액·오염물질의 유출을 차단합니다. 라텍스 알레르기가 있으면 논라텍스 재료를 사용합니다.</p>
<h3>언제 필요한가 / 적응증</h3>
<ul>
<li>근관치료(루트캔널) 시</li>
<li>복합레진 등 접착식 수복을 할 때</li>
<li>작업 중 이물질 흡입·삼킴 위험을 줄여야 할 때</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>처음엔 이물감이나 말하기 불편함이 있을 수 있으나 대부분 금방 적응합니다. 입 벌림 제한이나 심한 구역질 반응이 있는 경우 사용이 어려울 수 있고, 알레르기 병력이 있으면 미리 알려야 합니다. 이음치과에서는 안전하고 정밀한 치료를 위해 자주 사용합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='rubber-dam';
UPDATE dict_terms SET full_desc='<p>앞니(절치)는 입 앞쪽에 자리한 8개의 치아(위·아래 각각 4개)로, 음식물을 ''베어 자르는'' 첫 단계 역할을 하며 말소리와 웃을 때 보이는 모습에 큰 영향을 줍니다. 얇고 날카로운 절단면 때문에 손상이나 마모에 취약하며, 치아 배열과 색상은 심미성에 직결됩니다.</p>

<h3>원리 또는 특징</h3>
<p>앞니는 넓은 절단면과 비교적 단일한 뿌리를 가진 평판형 치아입니다. 단단한 법랑질로 표면이 보호되지만 앞쪽에 노출되어 충격·마모·착색이 잘 생기며, 발음 시 공기 흐름을 조절하는 역할도 합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>외상으로 앞니가 깨지거나 금이 갔을 때</li>
  <li>충치나 변색으로 미관·기능이 떨어질 때</li>
  <li>치아 배열 불량(벌어짐·덧니)으로 보이거나 씹기 불편할 때</li>
  <li>이갈이·마모로 절단면이 손상되었을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>앞니 치료는 심미성과 기능을 함께 고려합니다. 손상 정도에 따라 충전·레진 복원, 라미네이트·심미보철, 교정치료 등이 선택되며, 심한 경우 신경치료가 필요할 수 있습니다. 평소 불소 도포·야간 보호장치로 예방하고 정기검진을 받는 것이 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='incisor';
UPDATE dict_terms SET full_desc='<p><strong>견치(송곳니)</strong>는 앞니와 소구치 사이에 있는 뾰족한 치아로, 음식물을 찢고 고정하는 기능을 담당합니다. 뾰족한 첨과 다른 치아보다 긴 뿌리를 가져 물리적 부담을 잘 견디며, 치열의 형태와 저작 방향을 잡아 주는 역할도 합니다.</p>

<h3>원리 또는 특징</h3>
<p>견치는 하나의 뾰족한 첨을 가지며 영구치는 보통 어린 시기 이후에 맹출합니다. 긴 뿌리 덕분에 치아 지지력이 좋아 보철물의 지지치 또는 교정 치료의 기준점으로 자주 이용됩니다. 측면 운동 시에는 견치유도(canine guidance)로 후방치아를 보호합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>맹출장애(매복)으로 정상 위치에 나오지 않을 때</li>
  <li>교통사고·외상으로 파절되었거나 심한 마모가 있을 때</li>
  <li>충치나 치주질환으로 약해져 보존·보철 치료가 필요할 때</li>
  <li>치열 불균형으로 교정 치료가 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>견치는 구조상 한 번 손상되면 회복이 어려운 경우가 있어 조기진단과 관리가 중요합니다. 칫솔질과 정기검진으로 충치·치주질환을 예방하고, 문제가 있을 때는 보존치료·신경치료·교정·보철 등 다양한 선택지를 이음치과와 상의해 결정할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='canine';
UPDATE dict_terms SET full_desc='<p>소구치는 어금니와 견치 사이에 위치한 작은 어금니로, 음식물을 잘라내고 가는 중간 역할을 합니다. 어른에게는 위아래 각 4개씩 총 8개가 있으며, 앞부분에서 찢는 힘을 후방의 큰 어금니로 전달해 씹기 과정을 돕습니다.</p>

<h3>원리 또는 특징</h3>
<p>소구치는 윗니와 아랫니에서 형태가 다르며 보통 두 개의 봉우리(혹은 하나)를 가지고 있습니다. 상악 소구치는 경우에 따라 두 개의 뿌리를 가지기도 하고, 하악 소구치는 보통 한 뿌리입니다. 작은 윗면으로 음식물을 잘게 부수고 교합의 안정에 기여합니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>충치가 생겨 충전이나 보철 치료가 필요한 경우</li>
  <li>치수(신경) 감염 시 근관치료가 필요한 경우</li>
  <li>교정 치료에서 공간 확보를 위해 발치가 고려되는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>소구치는 크기가 작아 충치가 진행되기 쉽고, 금이 가기 쉬운 부위입니다. 정기적인 검진과 불소처치, 적절한 교합 관리로 손상을 줄일 수 있습니다. 이음치과에서는 소구치의 보존 치료와 교정 연계 치료에 대해 상담합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='premolar';
UPDATE dict_terms SET full_desc='<p><strong>대구치(Molar)</strong>는 입 뒤쪽에 자리한 가장 크고 넓은 어금니로, 여러 굴곡과 넓은 교합면을 이용해 음식을 잘게 부숴 소화 준비를 돕습니다. 상하 각 6개씩(사랑니 포함) 배열되며 다수의 뿌리로 저작력을 지탱해 입안에서 중요한 역할을 합니다.</p>

<h3>원리 또는 특징</h3>
<p>대구치는 넓은 씹는면과 깊은 홈으로 음식 분쇄에 특화되어 있습니다. 여러 뿌리가 있어 씹는 힘을 견디고 치아의 안정성을 유지하지만, 홈과 접촉부 때문에 충치나 치주질환이 생기기 쉽습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>깊은 충치로 인한 수복(충전이나 인레이)이 필요한 경우</li>
  <li>치수염으로 인한 근관치료(신경치료)가 필요한 경우</li>
  <li>치주염으로 치아 흔들림이나 보철 필요가 생겼을 때</li>
  <li>사랑니의 매복이나 통증으로 발치가 고려될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>대구치는 구조상 보존적 치료가 어려울 수 있어 정기검진과 조기 치료가 중요합니다. 씹는면 홈은 실란트나 불소 적용으로 예방할 수 있으며, 치료는 충전·크라운·근관치료·발치 등 상태에 따라 달라집니다. 구체적 진단과 치료계획은 이음치과에서 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='molar';
UPDATE dict_terms SET full_desc='<p>치관은 잇몸 위로 드러나 입안에서 보이는 치아의 겉부분을 뜻합니다. 표면은 단단한 법랑질로 덮여 저작과 발음, 얼굴미 관여하며 음식물을 부수는 역할을 합니다. 치근과 연결되어 있으나 손상이나 충치가 생기면 통증과 기능저하가 나타나며 필요 시 보존치료나 보철 치료를 시행합니다. 이음치과에서 쉽게 설명해드립니다.</p>
<h3>원리 또는 특징</h3>
<p>치관은 법랑질, 상아질, 치수로 구성됩니다. 법랑질은 몸에서 가장 단단한 조직으로 마모와 산에 비교적 강하지만 영구적 손상은 복구가 어렵습니다. 어금니와 앞니는 형태가 달라 저작과 절단 기능을 나눕니다.</p>
<h3>관련 상황</h3>
<ul>
  <li>충치로 인해 법랑질과 상아질이 손상될 때</li>
  <li>외상으로 치관이 깨지거나 금이 갔을 때</li>
  <li>심한 착색이나 심미적 개선이 필요할 때</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>치관 손상은 조기치료가 중요합니다. 불편감이나 색 변화, 통증이 있으면 검진을 받고 필요한 경우 충전·크라운 등 보존 치료로 형태와 기능을 회복할 수 있습니다. 평소 칫솔질과 불소로 보호하는 것이 최선입니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tooth-crown';
UPDATE dict_terms SET full_desc='<p>치근은 잇몸 아래 치조골 속에 묻혀 치아를 뼈에 단단히 고정하는 부분입니다. 표면은 시멘트질로 덮여 있고 치주인대를 통해 치조골과 연결되어 충격을 흡수하고 치아의 위치를 유지합니다. 내부에는 신경과 혈관이 지나가는 근관(치근관)이 있어 치아의 감각과 영양을 담당합니다. 이음치과에서 설명하듯 치근 상태는 치아의 수명과 기능에 직접적 영향을 미칩니다.</p>

<h3>원리 또는 특징</h3>
<p>치근은 형태와 개수가 치아 종류에 따라 다릅니다(어금니는 다근, 앞니는 단근). 시멘트질‑치주인대‑치조골의 연결로 물리적 지지와 미세한 움직임 조절이 가능하며, 근관을 통한 혈관·신경 공급이 끊기면 치수 괴사가 발생할 수 있습니다. 치주 질환이나 외상으로 치근 손상이 생기면 치아 지지력이 떨어집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치수염·치근단염으로 인한 근관치료(신경 치료)가 필요할 때</li>
  <li>심한 치주질환으로 치조골이 소실되어 치근 노출 또는 흔들림이 있을 때</li>
  <li>치근파절이나 외상으로 발치 또는 치료가 필요한 경우</li>
  <li>교정 치료 중 치근 흡수 여부 관찰이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치근은 눈에 보이지 않아 문제가 생겼을 때까지 증상이 늦게 나타날 수 있습니다. 통증, 이상한 흔들림, 잇몸의 농양 또는 색 변화가 있으면 조기에 검진을 받는 것이 중요합니다. 근관치료로 치근을 보존할 수 있는 경우가 많지만, 예방적 구강관리로 지지를 유지하는 것이 최선입니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tooth-root';
UPDATE dict_terms SET full_desc='<h3>치주인대란?</h3>
<p>치주인대는 치아뿌리와 치조골을 연결하는 얇은 결합조직입니다. 콜라겐 섬유, 혈관, 신경과 세포들로 이루어져 있어 저작 시 발생하는 충격을 흡수하고 힘을 뼈로 전달하며 압력·통증을 감지합니다. 치주염이나 외상으로 손상되면 치아의 흔들림이나 통증이 생길 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>섬유는 치근 표면에 박혀 뼈로 연결되는 형태(Sharpey 섬유)를 이루며 폭은 매우 좁습니다. 섬유세포·파골세포·시멘트세포 등이 있어 뼈와 치근 사이의 재형성과 수리를 돕고, 신경말단은 감각·반사 작용에 관여합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치주염으로 인한 섬유 파괴 및 치아동요</li>
  <li>교정치료 중 치아 이동과 치조골 재형성</li>
  <li>외상으로 인한 치아 충격이나 탈구</li>
  <li>발치·임플란트 계획 시 잔존 조직 평가</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치주인대는 어느 정도 치유능력이 있으나 만성 염증이 지속되면 회복이 어렵습니다. 정기적인 스케일링과 잇몸 관리로 염증을 예방하고, 외상 발생 시 빠른 진료가 중요합니다. 증상이나 검사 결과에 따라 이음치과에서 적절한 치료 방침을 안내받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='periodontal-ligament';
UPDATE dict_terms SET full_desc='<p>치은은 치아를 둘러싸고 보호하는 구강 점막으로, 치아와 치조골 사이를 밀착해 외부 자극·세균의 침투를 막는 역할을 합니다. 건강한 치은은 연한 분홍빛에 탄력이 있고 단단하게 치아에 붙어 출혈이나 통증이 없으며, 이음치과 같은 병원에서 정기 검진으로 상태를 확인할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치은은 상피층과 결합조직으로 구성되어 봉쇄막 역할을 하며, 혈관과 면역세포가 염증을 감지해 방어합니다. 치주인대와 연계되어 치아의 안정성을 돕고, 손상이나 세균 증식 시 충혈·부종·출혈 같은 염증 징후가 나타납니다.</p>

<h3>관련 상황</h3>
<ul>
<li>잇몸 붓기나 칫솔질 시 출혈이 있는 경우</li>
<li>구취나 잇몸 통증 등 불편감이 지속될 때</li>
<li>보철·교정 치료 전 잇몸 상태를 확인해야 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>정기적인 스케일링과 올바른 칫솔법이 치은 건강의 핵심입니다. 출혈·색 변화·통증이 이어지면 치과 검진을 받으세요. 흡연, 당뇨 등 전신 상태가 잇몸 건강에 영향을 줄 수 있으므로 함께 관리하는 것이 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gingiva';
UPDATE dict_terms SET full_desc='<p>구강 건조증은 침(타액) 분비가 줄어 입안이 마르고 끈적거리며 말하거나 삼키기 불편한 상태를 말합니다. 단순한 불편을 넘어서 음식물 분해와 항균 작용이 줄어들어 충치·구강염 등 구강 건강에 영향을 줄 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>침은 음식의 윤활, 소화 시작, 구강 내 세균 조절 역할을 합니다. 약물 부작용, 노화, 자가면역질환(예: 시르그렌), 당뇨나 두경부 방사선 치료 등이 타액선 기능을 떨어뜨려 건조감을 일으킵니다. 주관적 느낌과 객관적 분비량은 차이가 날 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
<li>항고혈압제·항우울제 등 약물 복용</li>
<li>시르그렌 증후군 등 자가면역 질환</li>
<li>두경부 방사선 치료 후, 당뇨나 탈수 상태</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>수분 섭취, 무당 껌이나 인공타액 사용, 국소 불소 도포로 증상을 완화할 수 있고, 복용 약물 검토가 필요할 때도 있습니다. 충치 예방과 정확한 원인 진단을 위해 치과(예: 이음치과)나 내과 상담을 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dry-mouth';
UPDATE dict_terms SET full_desc='<h3>구내염이란</h3>
<p>구내염은 입 안의 점막에 염증이 생겨 발적이나 궤양, 통증을 일으키는 상태를 말합니다. 가장 흔한 형태는 아프타성 구내염(입병)으로 작은 둥근 궤양이 반복적으로 생기며, 그 외에도 헤르페스성 감염, 물리적 자극, 알레르기나 영양결핍·자가면역 질환과 관련될 수 있습니다. 증상 완화와 원인 파악이 치료의 핵심입니다.</p>

<h3>원리 또는 특징</h3>
<p>점막의 미세손상이나 국소 면역 반응으로 염증이 발생하면 통증과 작열감이 생기고 식사나 말하기가 불편해집니다. 아프타성은 경계가 뚜렷한 궤양으로 자주 재발하는 반면, 헤르페스성은 초기 물집이 터지며 궤양으로 이어지는 점이 다릅니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>반복되는 입병(아프타)이 있는 경우</li>
  <li>입술·구강에 물집이 생기거나 퍼지는 경우</li>
  <li>치아·보철물의 반복적 자극으로 생긴 궤양</li>
  <li>영양결핍(비타민B·철분)이나 자가면역 질환이 의심될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>대부분은 며칠에서 2주 내 자연 회복되며 국소 진통제·항염·보호제 등으로 증상을 줄일 수 있습니다. 크거나 오래 지속되거나 재발이 잦으면 혈액검사나 바이러스 검사 등 추가 검사가 필요하므로 전문 진료를 받는 것이 좋습니다. 심한 경우 이음치과 등에서 정밀검사와 치료를 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='stomatitis';
UPDATE dict_terms SET full_desc='<p><strong>타액(침)</strong>은 타액선에서 계속 만들어져 구강 안을 적시고 보호하는 투명한 체액입니다. 음식의 분해를 돕는 효소와 점액성분, 칼슘·인산염 같은 무기질, 항균 단백질을 포함해 말하고 삼키고 씹는 기능을 원활하게 하고 충치와 구강감염을 억제하는 중요한 역할을 합니다. 구강검진이나 치료 전 이음치과에서 기능을 확인할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>타액은 주로 물로 구성되며 아밀라아제 같은 소화효소, 뮤신(점액단백질)으로 윤활하고, 산을 중화하는 완충능과 치아 재광화에 필요한 칼슘·인산염을 공급합니다. 또한 IgA·라이소자임 등 항균성 물질로 세균 증식을 억제하며, 자극에 따라 분비량이 늘거나 줄어듭니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>약물복용·쇼그렌증후군 등으로 인한 구강건조(타액감소)</li>
  <li>충치 발생이 잦거나 구강세균 관련 염증이 있는 경우</li>
  <li>두경부 방사선치료나 타액선 수술 후 타액 기능 저하</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>입이 자주 마르거나 맛이 변하면 타액량과 성분을 확인받는 것이 좋습니다. 수분 섭취, 무설탕 껌 씹기 등으로 분비를 자극할 수 있고, 필요시 타액대체제나 전문적 치료가 도움됩니다. 장기적 변화는 치아우식과 구강건강에 영향을 주므로 조기에 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='saliva';
UPDATE dict_terms SET full_desc='<p>치아 번호는 구강 내 각 치아를 일관되게 표시하는 방법으로, 진단·치료 계획·기록에서 같은 치아를 정확히 가리키도록 돕습니다. 의사와 치과팀이 엑스레이나 수술, 보험 처리 때 혼동 없이 소통할 수 있게 해 주며, 환자도 자신의 치아 위치를 빠르게 이해할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>가장 널리 쓰이는 FDI 표기법은 두 자리 숫자를 사용합니다. 첫 자리(1~4)는 사분면을 나타내어 1은 오른쪽 위, 2는 왼쪽 위, 3은 왼쪽 아래, 4는 오른쪽 아래를 뜻하고, 둘째 자리는 중심(1)에서 어금니(8)까지의 순서를 나타냅니다. 미국식 유니버설(1~32) 등 다른 체계도 존재합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>충치 치료, 신경치료 등 특정 치아를 지정할 때</li>
  <li>엑스레이·치료기록에 위치를 명확히 남길 때</li>
  <li>다른 병의원이나 보험사와 소통할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진료 중 치아 번호로 설명을 들으면 위치 확인이 쉽습니다. 어린이 유치는 FDI에서 첫 자리가 5~8로 따로 표기되므로 성인 표기와 달라 혼동될 수 있습니다. 한국에서는 주로 FDI 표기법을 사용하며, 이음치과에서도 동일한 방식을 사용합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tooth-numbering';
UPDATE dict_terms SET full_desc='<p>치식은 한 사람의 치아를 종류별로 정리한 약식 표기입니다. 흔히 성인 치식은 한 사분면당 절치·견치·소구치·대구치가 각각 2‑1‑2‑3개로 표기되며, 한 쪽에 8개, 좌우·상하 모두 합쳐 총 32개의 치아 구조를 간단히 나타냅니다. 치아 위치와 수를 빠르게 표시하는 방법입니다.</p>

<h3>원리 또는 특징</h3>
<p>치식은 각 사분면을 기준으로 치아 종류별 수를 적는 방식입니다. 예컨대 성인은 2-1-2-3으로 표기하고, 유치는 2-1-0-2(총 20개)로 다릅니다. 선천적 결손이나 발치로 인해 실제 수는 달라질 수 있으며, 치식은 진단·기록·치료계획에 유용합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>초진 시 치아 차트 작성 및 치료 이력 기록</li>
  <li>교정 치료 계획 수립과 장기적 배치 예측</li>
  <li>발치·임플란트 등 구강수복 시 필요한 치아 수 확인</li>
  <li>소아치과에서 유치와 영구치 교체 관찰</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치식은 표준적인 수를 보여주지만 개인차가 흔합니다. 선천적 결손(치아 결여)이나 과잉치, 이전 치료로 인한 변화가 있을 수 있으니 정확한 상태는 진료실에서 확인받는 것이 좋습니다. 궁금하면 이음치과에서 치아수를 함께 점검해 보세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-formula';
UPDATE dict_terms SET full_desc='<h3>교두란 무엇인가요?</h3>
<p>교두는 소구치와 대구치의 교합면에 솟아 있는 뾰족하거나 둥근 돌기입니다. 음식물을 자르고 빻는 기능을 담당해 저작 효율을 높이며, 반대쪽 치아와 맞물려 안정적인 교합을 만듭니다. 치아 모양과 위치에 따라 크기와 수가 달라집니다.</p>

<h3>원리 또는 특징</h3>
<p>교두는 법랑질로 덮인 단단한 구조로, 내부는 상아질이 받쳐줍니다. 저작 시 힘을 분산시키고 음식물을 절단·분쇄하는 역할을 하며, 끝부분(교두첨)은 마모나 충격에 취약해 금이 가거나 깎일 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>충치가 교두를 침범해 통증이나 구멍이 생긴 경우</li>
  <li>심한 마모나 이갈이로 교두가 닳거나 깨진 경우</li>
  <li>교합 불균형으로 특정 교두에 과도한 힘이 가해지는 경우</li>
  <li>수복(충전·크라운)이나 교정 치료가 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>작은 돌기 하나도 저작과 교합에 영향을 주므로 손상 시 방치하지 않는 것이 좋습니다. 통증, 음식물 걸림, 날카로운 느낌이 있으면 검진을 받아 적절한 수복으로 교두를 재건할 수 있습니다. 증상 평가와 치료 상담은 이음치과에서 도와드립니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cusp';
UPDATE dict_terms SET full_desc='<p><strong>치경부</strong>는 치아의 머리(치관)와 뿌리(치근)가 만나는 목 부분을 말합니다. 정상적으로는 잇몸에 가려져 있으나 잇몸이 내려가거나 마모가 생기면 이 부위의 얇은 구조가 드러나 시리고 민감한 증상이 나타날 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치경부는 법랑질이 끝나고 시멘트질이 시작되는 경계로, 법랑질보다 보호층이 얇아 외부 자극에 취약합니다. 플라그가 쌓이기 쉬운 형태여서 충치(치경부 우식)나 마모가 잘 생기며, 치은퇴축 시 상아질이 노출되어 통증이 발생합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치은퇴축(잇몸이 내려가면서 치경부 노출)</li>
  <li>과도한 칫솔질이나 나쁜 칫솔법으로 인한 마모·어브랙션</li>
  <li>치경부 우식(충치)이 생긴 경우</li>
  <li>나이·치주질환으로 인한 자연스러운 노출</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>증상이 있으면 부드러운 칫솔과 올바른 칫솔법으로 관리하고, 불소 도포나 민감증 치료제, 필요 시 레진 수복 등으로 증상을 줄일 수 있습니다. 상태가 지속되면 이음치과 같은 전문 기관에서 정확한 평가와 치료 계획을 받는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cervical-area';
UPDATE dict_terms SET full_desc='<p>백악질은 치아의 뿌리 표면을 얇게 감싸는 석회화 조직으로, 치주인대의 콜라겐 섬유가 여기 붙어 치아를 턱뼈에 단단히 연결합니다. 에나멜과 달리 혈관이 적어 스스로 영양공급이 제한되지만, 평생 동안 조금씩 증식하거나 손상 부위를 덮어 치아 지지에 기여합니다. 치주 치료 시 이 구조를 보호하는 것이 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>백악질은 цемента세포(시멘토블라스트)가 만들어내며, 무세포성 백악질과 세포성 백악질로 나뉩니다. 무세포성은 주로 치경부에 분포하고, 세포성은 근단 쪽에서 더 두껍습니다. 혈관이 거의 없어 회복 속도가 느리지만 치주인대 섬유의 부착점으로서 치아 안정성에 필수적입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>잇몸퇴축으로 인한 치근 노출 및 민감증</li>
  <li>치주염으로 백악질이 노출되거나 손상될 때</li>
  <li>스케일링·루트플래닝 후 표면이 드러나는 경우</li>
  <li>근단 우식(루트카리) 위험이 있는 환자</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>노출된 백악질은 법랑질보다 약해 충치와 민감에 취약합니다. 과도한 칫솔질이나 부적절한 스케일링으로 더 손상될 수 있으므로 전문의와 상의해 치료 방향을 정하는 것이 좋습니다. 보존적 처치나 치주재생이 필요한 경우 이음치과 등에서 상담받아 적절한 관리를 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cementum';
UPDATE dict_terms SET full_desc='<p>치과 마취는 치료 중 통증을 줄여 편안하게 치료받을 수 있도록 약물을 사용하거나 방법을 적용하는 것입니다. 대부분 국소마취를 통해 특정 치아나 주변조직의 감각을 일시적으로 차단하며, 필요에 따라 표면마취나 경구·정맥 진정과 병행하기도 합니다. 이음치과에서도 주로 국소마취를 사용합니다.</p>

<h3>원리 또는 특징</h3>
<p>국소마취제는 신경 세포의 전기 신호 전달을 막아 통증 감각이 뇌로 전달되지 않게 합니다. 침윤마취(조직에 직접 주사)와 전달마취(신경 다발 차단)가 대표적이며, 약제에 따라 작용 시작 시간과 지속 시간이 다릅니다. 대개 회복 후 감각은 완전히 돌아옵니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>충치 치료·심한 통증이 예상되는 수복 치료</li>
  <li>발치·임플란트·잇몸 수술 등 침습적 시술</li>
  <li>신경치료와 같은 깊은 처치가 필요할 때</li>
  <li>치과 불안으로 통증에 대한 우려가 큰 환자</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>대부분 안전하지만 주사 부위 저림, 멍, 드문 알레르기나 전신 반응이 있을 수 있습니다. 항응고제 복용, 심혈관 질환, 임신 여부, 약물 알레르기는 사전에 알려야 합니다. 마취가 풀릴 때까지 뜨거운 음식은 피하고, 의심 증상 발생 시 즉시 치과에 문의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='anesthesia';
UPDATE dict_terms SET full_desc='<p>치아 외상은 얼굴이나 턱에 가해진 충격으로 치아와 주변 조직에 생기는 손상입니다. 낙상·교통사고·운동 중 충돌로 치아가 금이 가거나 깨지고, 흔들리거나 완전히 빠질 수 있습니다. 초기 응급처치와 빠른 치과 진료가 치료 방향과 예후를 좌우합니다.</p>
<h3>원리 또는 특징</h3>
<p>충격은 단단한 법랑질부터 치아 내부의 치수(신경)와 지지하는 치주조직까지 영향을 줍니다. 금이 가는 표층 손상부터 치아가 탈구되거나 완전히 빠지는 완전탈락까지 다양하며, 통증·출혈·감각 이상·치아 색 변화가 동반될 수 있습니다.</p>
<h3>관련 상황</h3>
<ul>
  <li>낙상이나 넘어짐</li>
  <li>운동 중 충돌(축구·농구 등)</li>
  <li>교통사고 또는 얼굴에 가해진 외상</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>출혈은 압박으로 지혈하고, 빠진 치아는 치근을 만지지 말고 우유나 본인 침에 담아 보존하세요. 문질러 씻지 말고 가능한 빨리 치과 응급진료를 받는 것이 중요합니다. 응급 상황에서는 이음치과 등 전문기관의 평가를 받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-trauma';
UPDATE dict_terms SET full_desc='<p>이소맹출은 치아가 원래 나와야 할 자리나 방향을 벗어나 비정상적인 위치나 각도로 돋아나는 상태입니다. 유치든 영구치든 발생할 수 있으며, 눈에 보이는 배열 이상 외에도 주변 치아 뿌리를 압박하거나 맹출 지연을 초래해 전체 치열에 영향을 줍니다.</p>

<h3>원리 또는 특징</h3>
<p>치아의 발생 위치와 맹출 경로가 정상과 어긋나면 이소맹출이 생깁니다. 특히 영구 제1대구치나 견치에서 흔하고, 방향이 틀어지면 인접 유치의 흡수나 조기 상실, 교합 어긋남을 유발할 수 있습니다. 성장 과정에서 턱뼈와 공간의 여건이 중요합니다.</p>

<h3>관련 상황</h3>
<ul>
<li>영구치가 비스듬히 나오거나 잇몸 속에 머물러 보일 때</li>
<li>옆 유치가 예상보다 빨리 흔들리거나 빠질 때</li>
<li>앞니·어금니의 맞물림이 어긋나 치열이 흐트러질 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기에 진단하면 단순 관찰, 유치 발치, 공간 유지장치나 교정적 유도가 효과적입니다. 방치하면 교정 치료가 복잡해질 수 있으니 소아치과나 통합치의학과에서 평가를 받으세요. 필요 시 이음치과에서 적절한 시기와 치료 방향을 안내받을 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='ectopic-eruption';
UPDATE dict_terms SET full_desc='<p>지각 과민(일반적으로 ''시린이'')은 치아 표면의 보호층이 손상되어 상아질이 드러나고, 그 속의 미세한 상아세관을 통해 외부 자극이 신경으로 전달되며 찬물·달콤한 음식·공기 접촉 시 짧고 날카로운 통증이 발생하는 상태입니다. 원인에 따라 시린이 전용 치약이나 치과 처치로 증상이 많이 호전될 수 있으며, 정확한 진단은 이음치과에서 받으시길 권합니다.</p>

<h3>원리 또는 특징</h3>
<p>상아질에 분포한 상아세관 내부의 액체가 자극을 받으면 움직여 신경을 자극하는 ''유체역학 이론''이 주요 기전입니다. 특징은 자극에 즉각적으로 나타나고 지속 시간은 짧은 편이며, 주로 치경부나 치근 부위에 흔히 생깁니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>잇몸 퇴축으로 치근(뿌리)이 노출된 경우</li>
  <li>과도한 칫솔질이나 마모로 인해 상아질이 노출된 경우</li>
  <li>산성 음식·위식도역류로 인한 부식(침식)이 있는 경우</li>
  <li>치아 미백, 균열 등으로 자극이 증가한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기 관리로는 마모를 줄이는 올바른 칫솔질, 산성 음식 제한, 민감성 전용 치약(칼륨 이온 성분 등) 사용이 도움됩니다. 치과에서는 불소 도포, 레진 봉합, 글라스아이오노머 수복 또는 잇몸 이식 등 원인에 맞는 치료를 시행합니다. 증상이 지속되면 정확한 원인 진단과 적절한 치료 계획이 필요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='hypersensitivity';
UPDATE dict_terms SET full_desc='<p>All‑on‑4(올-온-포)는 한 악궁에 4개의 임플란트만 심어 전체 치아를 하나의 고정 보철로 복원하는 방법입니다. 뒤쪽 두 개를 경사지게 식립해 길게 연결된 보철을 안정적으로 지지하고, 조건이 맞으면 수술 당일 임시 치아를 올려 빠르게 씹는 기능을 회복할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>앞쪽 임플란트는 수직, 뒤쪽은 일정 각도로 경사지게 심어 골질이 좋은 부위를 활용합니다. 경사 식립으로 임플란트 길이를 확보하고 골이식 가능성을 낮추며, 적은 개수로도 전체 악궁을 지지합니다. 완성 후에는 고정식 보철로 자연스러운 착용감을 제공합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
<li>상악 또는 하악 전체 치아를 상실했을 때</li>
<li>광범위한 골 소실로 다수 임플란트가 부담스러울 때</li>
<li>치료 기간을 단축하고 즉시 기능 회복을 원할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>모든 환자에게 적합한 치료는 아니며 CT 기반의 정밀 계획과 잇몸·전신 상태 평가가 필수입니다. 구강 위생 관리와 정기 검진이 성공률에 큰 영향을 주므로 꾸준한 관리가 필요하며, 이음치과에서는 환자 상태에 맞춘 맞춤 상담을 진행합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='all-on-4';
UPDATE dict_terms SET full_desc='<h3>발치 직후 임플란트 식립이란</h3>
<p>손상되거나 치료할 수 없는 치아를 뽑은 즉시 그 자리에 임플란트를 심는 방법입니다. 발치와 식립을 한 번에 진행해 전체 치료 기간을 줄이고 주변 치조골의 형태를 보존할 수 있어 환자 만족도가 높습니다. 다만 모든 경우에 적용되는 것은 아니므로 검사와 계획이 필수입니다.</p>

<h3>원리 또는 특징</h3>
<p>발치 소켓에 임플란트를 바로 넣어 골유착을 유도합니다. 잔존 골의 양과 두께, 연조직 상태에 따라 소켓 보강용 골이식이나 인접 조직의 재건이 함께 필요할 수 있고, 초기 안정성이 확보되면 즉시 또는 지연 보철을 진행합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>건전한 잔존 치조골이 충분할 때</li>
  <li>급성 농양이나 심한 감염이 없는 경우</li>
  <li>심미성이 중요한 전치 영역에서 골·연조직 보존이 필요할 때</li>
  <li>치료 기간을 단축하고 싶은 환자</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>모든 환자에게 적합하지 않으며, CBCT 촬영과 정밀 평가로 계획을 세워야 합니다. 감염 잔존이나 골 부족 시 실패 위험이 커져 추가 골이식이나 지연 식립이 권장될 수 있습니다. 치료 가능 여부는 상담을 통해 확인하며, 필요시 이음치과에서 전문 평가를 받으시기 바랍니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='immediate-placement';
UPDATE dict_terms SET full_desc='<h3>임플란트 보증은 무엇인가요?</h3>
<p>임플란트 보증은 시술 후 발생할 수 있는 제조상 결함이나 구조적 문제에 대해 일정 기간 수리나 재시술을 보장하는 제도입니다. 제조사와 시술 치과가 보증 범위를 명시하여 픽스처(임플란트 본체)의 파절이나 초기 골유착 실패 같은 특정 상황에서 재치료를 지원합니다. 이음치과는 정기 검진을 지키는 환자에 한해 보증을 제공합니다.</p>

<h3>원리 또는 특징</h3>
<p>보증은 보통 기간·적용 범위·조건으로 구성됩니다. 제조 결함과 재료 파손은 대상이지만, 외상·과실·심한 흡연이나 구강 위생 불량으로 인한 문제는 제외될 수 있습니다. 보증을 받으려면 보증서와 치과의 지침을 따르고 정기검진을 유지하는 것이 중요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>시술 직후 골유착이 이루어지지 않아 초기 실패가 확인된 경우</li>
  <li>픽스처의 파절이나 제조상 결함이 의심되는 경우</li>
  <li>임플란트 연결부(나사 등)의 구조적 손상 발생 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>보증은 환자의 불안을 줄여주지만 모든 비용을 무조건 부담하는 것은 아닙니다. 보증 범위·기간·제외 항목은 치과마다 다르니 시술 전 서면 설명을 받고 보증서 내용을 꼼꼼히 확인하세요. 정기검진과 올바른 구강관리로 보증 적용 조건을 지키는 것이 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='implant-warranty';
UPDATE dict_terms SET full_desc='<p>임플란트 식립 각도는 임플란트를 턱뼈에 삽입할 때 결정하는 방향과 기울기를 말하며, 최종 보철물의 모양·치아 높이·교합력이 어떻게 전달되는지를 함께 고려한 계획입니다. 단순한 뼈 위치만이 아니라 심미성과 힘의 분산, 나사구멍 위치까지 영향을 주므로 시술 전 정밀한 계획이 필요합니다. 이음치과에서는 디지털 가이드를 통해 계획을 구현합니다.</p>

<h3>원리 또는 특징</h3>
<p>적절한 각도는 교합 힘을 임플란트와 뼈에 고르게 전달해 과부하를 줄이고, 보철물의 배치(출구 위치, 심미적 라인)를 맞추는 데 중요합니다. 좁은 골간이나 상악동 회피 같은 해부학적 제약이 있으면 각도를 조정해 보철적 해결책(각도형 어버트먼트 등)을 사용합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>앞니 등 심미 구역에서 자연스러운 치아 배열이 필요할 때</li>
  <li>골 폭이 좁거나 상악동·신경을 피해야 할 때</li>
  <li>여러 개의 임플란트를 연결해 하중을 분산시켜야 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>계획과 실제 식립 각도 차이는 임플란트 수명과 보철 편의성에 영향을 줍니다. 최근엔 CT 기반 디지털 가이드로 계획 각도를 정확히 구현하는 경우가 많지만, 필요하면 각도형 어버트먼트나 보철 수정을 통해 최종 결과를 맞춥니다. 시술 전 담당의와 계획을 충분히 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='implant-angulation';
UPDATE dict_terms SET full_desc='<p>치조골 보존술은 발치 직후 빈 소켓에 골이식재와 필요 시 차폐막을 넣어 자연적인 뼈 소실을 줄이는 시술입니다. 이렇게 하면 치아를 뽑은 부위의 잇몸 모양과 뼈 폭을 유지해 향후 임플란트 식립이나 보철 치료 시 더 좋은 결과를 얻을 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>발치 후 뼈는 빠르게 흡수되는데, 골이식재가 소켓을 채워 주면 뼈가 줄어드는 폭을 완화할 수 있습니다. 이식재 종류로는 동종(사람), 이종(동물), 합성 재료가 있으며 대부분 흡수되며 점차 환자 본인의 뼈로 대체됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>향후 임플란트 식립을 계획할 때</li>
  <li>심미성이 중요한 앞니 부위 발치 시</li>
  <li>발치로 인한 골 결손이 생길 가능성이 클 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>국소마취로 시행하며 회복기간은 보통 3~6개월입니다. 완전한 뼈 재생을 보장하지는 않아 추가 골이식이 필요할 수 있고, 흡연·감염은 결과에 영향을 줍니다. 자세한 상담은 이음치과에서 환자 상태에 맞춰 권유합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='ridge-preservation';
UPDATE dict_terms SET full_desc='<h3>핵심 설명</h3>
<p>서브머지드 임플란트는 임플란트(픽스처)를 식립한 뒤 잇몸으로 완전히 덮어 외부와 차단한 상태에서 뼈와 단단히 붙을 때까지 치유시키는 2단계 치료법입니다. 초기 치유 기간 동안 보철물이나 음식물의 압력과 오염을 피해 안정적인 골유착을 기대할 수 있어 골이식 등 병행 시 유리한 방법입니다.</p>

<h3>원리 또는 특징</h3>
<p>첫 단계에서 픽스처를 골내에 넣고 덮개(커버스크류)를 닫아 봉합합니다. 일정 기간(통상 수개월) 골유착을 기다린 뒤 2차 수술로 잇몸을 열어 어버트먼트를 연결합니다. 치료 기간은 더 길지만 임플란트가 외부 자극 없이 안정적으로 치유되는 것이 장점입니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>골이식이나 뼈량 보강을 함께 시행할 때</li>
  <li>초기 고정도가 낮아 외부 자극 차단이 필요할 때</li>
  <li>구강 위생이 어려워 감염 위험을 줄여야 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치료기간이 비교적 길고 2차 수술이 필요하므로 방문 횟수가 늘어납니다. 수술 후 흡연이나 구강위생 불량은 골유착 실패 위험을 높이므로 주의해야 합니다. 합병증(노출, 감염)은 드물지만 발생 시 적절한 처치가 필요하므로 담당 치과의사와 계획을 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='submerged-implant';
UPDATE dict_terms SET full_desc='<h3>논서브머지드 임플란트란?</h3>
<p><strong>논서브머지드 임플란트</strong>는 식립한 기둥(fixture)의 상부가 잇몸 밖으로 나오게 한 채로 골과 붙는 것을 기다리는 1단계 방식입니다. 두 번의 수술을 거치지 않아 회복 기간과 환자의 불편이 줄고 보철까지의 절차가 비교적 간단해집니다.</p>

<h3>원리 또는 특징</h3>
<p>임플란트 식립 후 치유기둥(healing abutment)이 구강 내에 노출되어 점막이 자연스럽게 형성되는 것이 특징입니다. 초기 고정력이 충분해야 하며, 골유착 상태를 외부에서 관찰·관리할 수 있어 2차 수술이 불필요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>충분한 골량과 초기 고정력이 확보된 경우</li>
  <li>전신 상태가 양호해 치유가 예상될 때</li>
  <li>수술 횟수를 줄이고자 하는 환자</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>수술 횟수는 줄지만 임플란트 상부가 구강 내에 노출되어 있어 청결 관리가 중요합니다. 과도한 힘이나 감염 위험을 줄이기 위해 정기검진과 구강위생 지도가 필요하며, 실제 적용 여부는 이음치과에서 환자 상태를 보고 결정합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='non-submerged-implant';
UPDATE dict_terms SET full_desc='<p>치유 기간은 임플란트 표면과 주변 뼈가 단단히 결합되어 안정화되는 데 필요한 시간입니다. 이를 골유착이라고 하며, 잇몸과 뼈가 회복되면서 임플란트에 가해지는 힘을 안전하게 견딜 수 있게 되는 과정입니다. 개인별 골질과 치료 방법에 따라 소요 기간이 달라집니다.</p>

<h3>원리 또는 특징</h3>
<p>임플란트는 인공치근 표면에 뼈가 새로 붙어 뼈와 하나로 통합되는 과정으로 안정성을 얻습니다. 일반적으로 하악은 골밀도가 높아 2~3개월, 상악은 골질이 약해 4~6개월 정도 소요됩니다. 골이식, 전신질환, 흡연 등은 치유를 늦출 수 있으며 이 기간에는 과도한 하중을 피해야 합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>단순 임플란트 식립 후 표준 치유 경과 관찰</li>
  <li>동시 골이식이나 상악동 거상술을 시행한 경우 치유 기간 연장</li>
  <li>즉시 부하(바로 보철을 올리는 경우) 적용 여부 판단</li>
  <li>흡연, 당뇨 등 전신 상태로 인해 추가 관리가 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>정해진 치유 기간을 지키면 임플란트의 장기적 성공률이 높아집니다. 치료 중에는 정기 검진과 꼼꼼한 구강위생이 중요하며, 경우에 따라 조기 또는 지연 부하 전략을 선택할 수 있습니다. 자세한 평가와 계획은 이음치과에서 개별 상담을 통해 안내받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='healing-period';
UPDATE dict_terms SET full_desc='<h3>오버덴처란</h3>
<p>오버덴처는 소수의 임플란트를 잇몸 뼈에 심고 그 위에 고정장치를 연결해 착탈 가능한 틀니를 얹어 사용하는 보철입니다. 임플란트가 틀니의 움직임을 줄여 말하기·씹기 기능을 개선하며, 완전 고정형 임플란트보다 비용과 유지관리 면에서 현실적인 선택이 됩니다.</p>

<h3>원리 또는 특징</h3>
<p>보통 2~4개의 임플란트에 바(bar)나 볼형·클립형의 유지장치를 부착해 틀니가 걸리게 설계합니다. 환자가 스스로 착탈할 수 있으면서도 기존의 일반틀니보다 유지력과 안정성이 우수하고, 필요시 유지장치만 교체하거나 틀니를 보정할 수 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치아가 모두 빠져 일반틀니로는 유지가 잘 안될 때</li>
  <li>아래턱 틀니가 쉽게 빠져 불편감을 겪는 경우</li>
  <li>완전 고정형 임플란트 부담이 크고 탈착형을 원할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>정기적인 임플란트와 유지장치 점검, 틀니 세척이 필요하며 유지장치의 마모로 교체가 발생할 수 있습니다. 잇몸 뼈 상태에 따라 추가 치료가 필요할 수 있으므로 이음치과에서 상담받아 개인 상태에 맞는 계획을 세우는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='overdenture';
UPDATE dict_terms SET full_desc='<h3>상악동 천공이란</h3>
<p>상악동 천공은 임플란트를 위해 시행하는 상악동 거상술 중 윗턱 안쪽의 매우 얇은 점막(상악동 내막)이 찢어지는 합병증입니다. 천공 크기와 위치에 따라 치료 방식과 예후가 달라지며, 적절히 관리하면 임플란트 치료를 계속할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>상악동은 공기로 채워진 공간으로 내부 점막이 보호막 역할을 합니다. 점막이 찢어지면 이식재가 상악동으로 유입되거나 코·부비동 감염 위험이 커집니다. 작은 천공은 봉합이나 흡수성 콜라겐막으로 수복 가능하고, 큰 천공은 수술을 일시 중단하고 치유를 기다릴 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>상악동 거상술(임플란트 전 뼈 이식) 중 발생</li>
  <li>윗어금니·소구치 부위에 골량이 부족할 때</li>
  <li>기존 상악동 질환이나 해부학적 변이(점막이 더 얇은 경우)</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>경험 많은 술자일수록 발생 위험이 낮습니다. 작은 천공은 적절한 수복 후 임플란트 성공률에 큰 영향을 주지 않는 경우가 많고, 감염 예방과 충분한 치유기간 확보가 중요합니다. 흡연이나 코를 세게 풀기 등은 회복을 방해하므로 피하는 것이 좋습니다. 이음치과에서는 수술 전 정밀 검사와 상황에 맞는 수복법으로 합병증을 최소화합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='sinus-perforation';
UPDATE dict_terms SET full_desc='<p>임시치아(Provisional Restoration)는 최종 보철물이 완성될 때까지 임시로 장착하는 보철물입니다. 치료 기간 동안 보이는 모습과 씹는 기능을 지켜주고, 치아 형태나 맞물림을 미리 점검할 수 있게 도와줍니다. 보통 레진이나 PMMA로 제작하여 빠르게 만들고 필요 시 수리·조정합니다.</p>

<h3>원리 또는 특징</h3>
<p>준비한 치아에 맞춰 임시로 씌우거나 붙여서 보호하고 공간을 유지합니다. 심미성과 발음, 교합을 시험해 최종 보철물 설계를 보완할 수 있으며, 장기간 사용에는 적합하지 않아 정기적으로 상태를 확인해야 합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>크라운·브릿지 제작 중 최종물 완성 전까지 보호가 필요할 때</li>
  <li>심미적 위치나 모양을 환자가 미리 확인하고 싶을 때</li>
  <li>치아 삭제 후 민감증이나 감염 위험을 줄이려 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>임시치아는 영구적이지 않아 깨지거나 닳을 수 있으므로 단단한 음식과 끈적한 음식은 피하는 것이 좋습니다. 수리나 재조정이 가능하므로 불편하면 치과에 알려야 하며, 최종 보철물 제작 전 평가를 통해 결과를 개선할 수 있습니다. 자세한 상담은 이음치과에서 가능합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='provisional-tooth';
UPDATE dict_terms SET full_desc='<p>IPS e.max는 리튬디실리케이트 계열의 금속 없는 올세라믹 소재로, 강도와 투명도를 동시에 갖춰 자연치아와 유사한 빛 반사와 색감을 재현합니다. 앞니 크라운이나 라미네이트처럼 심미성이 중요한 부위에 주로 사용되며, 접착(본딩)을 통해 보철 수명을 높일 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>유리-세라믹 구조로 미세한 결정이 분산되어 있어 광학적 특성이 우수하고 기계적 강도가 높습니다. CAD/CAM 밀링이나 프레스 방식으로 제작 가능하며, 금속이 없어 잇몸 경계의 어두운 테두리가 생기지 않습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>앞니 크라운이나 심미적 보철이 필요한 경우</li>
  <li>라미네이트(얇은 도재 베니어) 제작</li>
  <li>부분 인레이·온레이로 자연치와 조화가 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>접착 치료가 중요해 치아 상태와 시술법에 따라 결과가 달라집니다. 저작력이 매우 큰 대규모 교합 부위의 긴 다리 교량에는 적합하지 않을 수 있어, 필요하면 이음치과에서 적절한 재료를 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='emax';
UPDATE dict_terms SET full_desc='<h3>포스트 코어란</h3>
<p>포스트 코어는 근관치료로 신경을 제거한 치아에 뿌리 안에 기둥(포스트)을 넣고 그 위에 치아 모양의 심(코어)을 만들어 크라운이 안정적으로 자리 잡도록 돕는 보철 치료입니다. 약해진 치아를 보강해 보철물의 지지력과 유지력을 높이는 목적을 가집니다.</p>

<h3>원리 또는 특징</h3>
<p>포스트는 금속이나 유리섬유 등으로 만들어져 뿌리관에 삽입되고, 코어는 소실된 치질을 대체해 크라운의 받침 역할을 합니다. 주조형(맞춤형)과 제조형(프리패브) 방식이 있으며, 섬유포스트는 심미성과 탄성률에서 이점이 있어 치근 파절 위험을 낮추는 편입니다. 충분한 근단 길이와 잔존 치질 확보가 중요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치아 상부가 많이 손상되어 크라운만으로 지지 불충분할 때</li>
  <li>근관치료 후 크라운을 계획할 때</li>
  <li>기존 보철물이 파손되었거나 탈락했을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>포스트 코어는 모든 근관치료 치아에 필요한 것은 아니며, 잔존 치질이 충분하면 불필요할 수 있습니다. 시술은 정확한 진단과 적절한 재료 선택이 중요하며, 과도한 포스트 삽입은 치근 파절 위험을 높일 수 있습니다. 이음치과와 같은 전문의와 상담해 개인 상태에 맞는 방법을 결정하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='post-core';
UPDATE dict_terms SET full_desc='<h3>금관(금 크라운)이란</h3>
<p>금관은 치아 전체를 덮는 크라운으로, 금합금을 주재료로 만들어진 보철물입니다. 인체에 친화적인 금속 특성으로 잇몸 자극과 부식이 적고, 자연치아와 유사한 마모도를 보여 씹는 기능을 오래도록 안정적으로 유지할 수 있습니다. 심미성이 낮아 주로 어금니 치료에 권장됩니다.</p>

<h3>원리 또는 특징</h3>
<p>금합금은 연성과 정밀 가공성이 좋아 치아에 밀착되는 맞춤형 크라운 제작이 가능합니다. 마모 속도가 자연치아와 비슷해 대합치 손상을 줄이고, 부식·균열에 강해 장기간 사용에 유리합니다. 알레르기 반응은 드물게 발생합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>광범위한 충전이나 치질 손실로 치관 전체 복원이 필요할 때</li>
  <li>씹는 힘이 큰 어금니의 내구성이 중요할 때</li>
  <li>대합치 마모를 최소화해야 할 경우</li>
  <li>브릿지 지대주로 강도가 요구될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>심미성이 낮아 앞니보다는 구치부에 적합합니다. 금관은 수리가 용이하고 수명이 길지만 초기 비용이 높을 수 있습니다. 금속 색을 수용할 수 있는지, 치아 삭제량과 잇몸 상태를 고려해 이음치과와 상담하여 적절한 재료를 선택하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gold-crown';
UPDATE dict_terms SET full_desc='<p>잔존 치질은 충치나 파절 등 손상된 부위를 제거한 뒤 남아 있는 건강한 치아 조직을 말합니다. 남은 치질의 양과 질이 수복물의 종류와 장기적 성공에 큰 영향을 주기 때문에, 가능한 한 건강한 치질을 보존하면서 적절한 수복 계획을 세우는 것이 중요합니다. 이음치과에서도 이 원칙을 바탕으로 진단합니다.</p>

<h3>원리 또는 특징</h3>
<p>잔존 치질은 치아의 기계적 지지와 접착면을 제공합니다. 법랑질은 접착 강도가 높아 수복물 고정에 유리하고, 상실이 많을수록 크라운·포스트·코어 등 추가 보강이 필요합니다. ''페룰 효과''처럼 남은 치질이 둥글게 감싸는 형태가 있으면 파절 위험이 줄어듭니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>광범위 충치 제거 후 수복물 종류 결정 시</li>
  <li>치아 파절이나 심한 마모로 조직이 부족할 때</li>
  <li>근관치료 후 치질이 많이 소실된 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치아를 최대한 보존하는 것이 우선이며, 남은 치질이 많으면 간단한 레진 수복으로도 회복이 가능합니다. 반대로 조직이 적으면 인레이·온레이·크라운 또는 포스트·코어가 필요할 수 있으며, 예후는 남은 치질의 양과 적절한 치료 선택에 좌우됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='remaining-tooth-structure';
UPDATE dict_terms SET full_desc='<p>핫셋(Hot Set)은 치과 보철물을 제작할 때 도재(세라믹)를 가마에서 고온으로 소성해 단단하게 만드는 과정입니다. 단순히 ‘굽는’ 단계지만 보철물의 강도, 표면광택과 최종 색조에 큰 영향을 주므로 기공소에서 매우 신중하게 진행합니다. 환자 눈에는 보이지 않는 제작 공정이며, 이음치과에서도 심미 보철 제작 시 거치는 표준 작업입니다.</p>

<h3>원리 또는 특징</h3>
<p>전용 소성로에서 도재의 입자들이 융합하거나 유리상층이 형성되며 강도와 광택을 얻습니다. 보통 초기 소성(비스크)으로 형태를 정한 뒤, 색조와 광택을 맞추기 위한 추가 소성이 반복됩니다. 소성 온도와 냉각 속도, 횟수에 따라 수축이나 미세균열, 색상 변화가 발생할 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>도재-금속(PFM) 또는 지르코니아 위에 세라믹을 올리는 보철물 제작 시</li>
  <li>심미적 색상과 투명도 조절이 필요한 전치부 크라운·브리지 제작</li>
  <li>표면광택 및 마모 저항성을 높여 장기내구성을 확보할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>환자는 소성 과정을 직접 보지 못하지만, 정확한 색상 선택과 치과-기공소 간 의사소통이 결과에 큰 영향을 줍니다. 소성 횟수가 늘어나면 색조가 미세하게 변할 수 있고, 가끔 재조정이 필요합니다. 기공사의 숙련도와 장비가 품질을 좌우하므로 궁금하면 담당의에게 문의해 제작 과정을 확인하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='hot-set';
UPDATE dict_terms SET full_desc='<p>크라운 마진은 보철물(크라운)의 가장자리가 삭제된 치아 표면과 만나는 미세한 경계선입니다. 이 부분의 맞물림 상태가 좋아야 시멘트가 잘 유지되고 음식물과 세균이 들어가지 않아 보철 수명과 치아 건강, 잇몸 상태에 큰 영향을 줍니다. 이음치과에서도 마진 확인을 치료의 핵심으로 둡니다.</p>

<h3>원리 또는 특징</h3>
<p><strong>마진</strong>은 형태(숄더, 챔퍼 등)와 위치(치은위·치은하)에 따라 설계됩니다. 매끄럽고 연속적인 접촉이 있으면 시멘트 유실과 미세누출을 줄여 2차 충치와 잇몸 염증 위험을 낮춥니다. 불완전한 마진은 플라그 축적과 치아 파절을 초래할 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>새 크라운 제작 시 마진 위치 결정이 필요할 때</li>
  <li>치관 주위 색 변화나 통증, 잇몸 염증이 생겼을 때</li>
  <li>심미적 이유로 잇몸 라인에 맞춘 마진 조정이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>정확한 마진은 치과 의사의 치아 삭제, 인상(스캔)과 치과기공소의 정밀도가 모두 중요합니다. 치은하 마진은 심미에 유리하지만 관리가 어려워 충치나 잇몸 문제를 일으킬 수 있으니 정기검진과 꼼꼼한 구강위생이 필요합니다. 마진 부위가 들리거나 변색되면 교체를 고려해야 합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='margin';
UPDATE dict_terms SET full_desc='<p>프로비저널은 최종 보철물이 들어가기 전 임시로 씌우는 수복물로, 준비된 치아를 보호하면서 씹는 기능과 외모를 유지시켜 환자가 최종 보철의 형태와 색상을 미리 경험해 볼 수 있게 해 줍니다. 제작 기간 동안 치아 민감도를 줄이고 잇몸 조직을 안정시키는 역할을 합니다.</p>

<h3>원리 또는 특징</h3>
<p>아크릴이나 복합레진 등으로 빠르게 제작하고 임시 시멘트로 고정해 필요하면 쉽게 제거하거나 조정할 수 있습니다. 최종 보철만큼 내구성은 높지 않지만 형태·색상·교합(물리는 관계)을 시험하고 주변 치아와 잇몸 상태를 유지하는 데 유용합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>크라운·브리지 제작 기간 동안 치아 보호가 필요할 때</li>
  <li>임플란트 최종 보철물을 장착하기 전 임시 보철이 필요할 때</li>
  <li>심미적 형태나 색상을 환자가 미리 확인하고자 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>임시 보철물은 영구보철보다 약하므로 단단한 음식은 피하고 세심히 관리해야 합니다. 임시 시멘트로 고정되어 느슨해지거나 빠질 수 있으니 불편하면 방문해 조정받으세요. 필요 시 이음치과에서 형태·색상 조정과 재장착을 도와드립니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='provisional';
UPDATE dict_terms SET full_desc='<p>치아 삭제는 크라운이나 브릿지 같은 보철물을 올리기 위해 자연치아의 표면을 필요한 만큼 다듬어 형태와 두께를 만드는 치료입니다. 충전물 제거와 함께 보철물이 안정적으로 맞도록 치아 모양과 경계를 만드는 과정이며, 치아신경을 보호하면서 가능한 최소량만 삭제하는 것이 원칙입니다.</p>
<h3>원리 또는 특징</h3>
<p>보철물 재료(지르코니아, 금속-도재 등)의 두께와 강도에 따라 삭제 깊이가 달라집니다. 주변 치아와의 접촉점과 마진(경계)을 균일하게 만들고, 치수(신경) 손상을 피하기 위해 국소마취하에 정교하게 진행합니다.</p>
<h3>관련 상황</h3>
<ul>
  <li>치아가 크게 손상되어 크라운을 씌워야 할 때</li>
  <li>신경치료 후 치아를 보호하기 위해 보철이 필요할 때</li>
  <li>심미적으로 형태 개선이나 색 개선이 필요할 때</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>치아 삭제는 필요한 만큼 최소한으로 시행되며, 치료 후 임시보철을 통해 기능과 심미를 유지합니다. 삭제량은 재료와 환자 상태에 따라 달라지므로 자세한 상담은 이음치과에서 받으시는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tooth-preparation';
UPDATE dict_terms SET full_desc='<h3>무엇인가요?</h3>
<p><strong>대합치 (Opposing Tooth)</strong>는 위턱과 아래턱에서 서로 맞물려 닿는 반대편 치아를 뜻합니다. 보철 치료에서는 새 보철물이나 수복물이 대합치와 어떻게 접촉하는지가 치료 성공을 좌우하므로, 높이·형태·접촉점 등을 면밀히 평가해 기능과 편안함을 유지합니다. 이음치과에서도 대합치 상태를 먼저 확인합니다.</p>

<h3>원리 또는 특징</h3>
<p>교합 시 대합치는 교합면(force distribution)을 받아 씹는 힘을 전달합니다. 정상적이면 힘이 고르게 분포되어 수명과 편안함이 유지되지만, 대합치의 과도한 높낮이 차이나 결손은 치아 마모, 보철물 파절, 턱관절 문제를 초래할 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>크라운·브리지 등 보철물 제작 시</li>
  <li>임플란트 수복물을 맞출 때</li>
  <li>교합 조정(높이 조절)이나 교정 치료가 필요한 경우</li>
  <li>치아 마모·파절 또는 대합치 결손이 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>대합치 상태는 보철 설계와 재료 선택에 영향을 줍니다. 대합치가 없거나 불안정하면 보철물의 형태를 바꾸거나 추가 치료(임플란트, 교정 등)가 필요할 수 있으니, 치료 전 교합 검사와 모형 분석을 통해 적절한 계획을 세우는 것이 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='opposing-tooth';
UPDATE dict_terms SET full_desc='<h3>치아 재식이란</h3>
<p>치아 재식은 외상으로 완전히 빠져나간 영구치를 원래 자리(치조와 치주인대)에 다시 심어 자연치아를 최대한 보존하려는 응급 시술입니다. 빠른 시간 내에 적절히 보관한 치아는 치주인대 세포가 살아있어 성공률이 높아집니다.</p>

<h3>원리 또는 특징</h3>
<p>치아를 제자리에 넣으면 남아있는 치주인대 세포가 뼈와 재부착을 시도합니다. 이를 위해 치아는 뿌리 표면을 다치지 않게 잡고 세균 오염을 줄여야 하며, 보통 치료 후에는 고정(스플린트)과 필요시 근관치료를 병행합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>완전히 빠진(완전탈구) 영구치가 있을 때</li>
  <li>치아가 깨지지 않고 구조적으로 재식 가능할 때</li>
  <li>빠르게 치아를 찾을 수 있고 보관 상태가 양호할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>발견 즉시 뿌리를 만지지 말고 왕복(우유·식염수)이나 입 안 볼에 넣어(어린아이는 주의) 갖고 오는 것이 중요합니다. <strong>30분 이내</strong>가 가장 유리하고, 늦어지면 성공률이 떨어집니다. 재식 후에도 치근 흡수나 치주 문제로 추가 치료 및 장기 관찰이 필요하며, 이음치과와 같은 전문 진료기관에서 빠르게 평가받는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='replantation';
UPDATE dict_terms SET full_desc='<p>디지털 스마일 디자인(DSD)은 환자의 얼굴 사진과 구강 스캔, 사진·비디오 자료를 합쳐 치료 후의 ‘미소’를 화면으로 미리 만들어보는 과정입니다. 단순한 예쁜 그림이 아니라 치아 크기·배열·보철물 모양을 실제 치료 흐름에 맞춰 설계해 환자와 치의가 목표를 공유하는 계획 도구입니다.</p>

<h3>원리 또는 특징</h3>
<p>DSD는 얼굴의 중심선·입술 움직임·미소 라인 등을 기준으로 디지털 모델을 구성하고 CAD 소프트웨어로 보철물 형태를 설계합니다. 가상 디자인을 바탕으로 임시장착(모형·바이트)이나 3D 프린트 시물레이션을 통해 실제 느낌을 확인할 수 있으며, 치과와 치기공실 간 의사소통이 명확해집니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>심미적 보철(라미네이트·도자기 크라운 등)을 계획할 때</li>
  <li>치아 형태·색상 변경을 미리 확인하고 싶은 경우</li>
  <li>복합 치료(임플란트·교정 포함)에서 전체적인 미소 밸런스를 설계할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>디지털 시뮬레이션은 치료 결과를 예측하는 강력한 도구지만 100% 보증은 아닙니다. 환자의 해부학적 조건이나 조직 반응에 따라 최종 결과는 조정이 필요할 수 있습니다. 정확한 사진·스캔이 중요하며, 이음치과 같은 전문 팀과의 상담을 통해 현실적인 계획을 세우는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='digital-smile-design';
UPDATE dict_terms SET full_desc='<h3>교합 조정이란?</h3>
<p>교합 조정은 물릴 때 치아와 보철물 사이의 접촉을 세밀하게 맞추는 치료입니다. 보철물을 장착하거나 자연치의 맞물림이 한쪽으로 치우였을 때 교합지를 이용해 높은 접촉점을 찾아서 아주 조금씩 다듬어 균형 잡힌 물림을 만드는 비수술적 처치로, 씹기 편안함과 턱·두통 완화가 목적입니다. 이음치과에서도 흔히 시행합니다.</p>

<h3>원리 또는 특징</h3>
<p><strong>교합지</strong>로 접촉 위치를 표시한 뒤 고점을 소량씩 삭제하거나 보철물 면을 조정하여 힘이 고르게 분포되도록 합니다. 대개 국소마취 없이 진행하며, 치아 구조는 가능한 한 보존하는 것이 원칙입니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>보철물(크라운·인레이 등) 장착 후 불편감이나 높은 부위가 느껴질 때</li>
  <li>치아 마모·깨짐이나 특정 부위에만 통증이 있는 경우</li>
  <li>턱관절 통증·두통·클락킹 증상이 교합 불균형으로 의심될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>교합 조정은 간단해 보여도 과도한 삭제는 피해야 하므로 경험 많은 진료진의 판단이 중요합니다. 필요하면 여러 차례에 걸쳐 미세조정하고, 경우에 따라 보철물 재제작이 필요할 수 있으니 경과 관찰이 요구됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='occlusal-adjustment';
UPDATE dict_terms SET full_desc='<h3>심미 라인이란</h3>
<p>심미 라인은 웃을 때 보이는 치아와 잇몸의 경계가 형성하는 전체적인 곡선을 말합니다. 일반적으로 윗 앞니의 절단면 모양이 아랫입술의 곡선과 조화될 때 심미적으로 안정된 미소로 평가됩니다. 보철치료나 미세한 형태수정으로 이 균형을 맞출 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>심미 라인은 입술 위치, 치아 길이·배열, 잇몸의 노출 정도가 함께 결정합니다. 개인마다 입술 움직임이 달라 같은 치아라도 보이는 모습이 다르며, 좌우 대칭성과 적절한 치아 비율(비율 및 각도)이 중요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>잇몸이 많이 드러나는 ‘가미미소(gummy smile)’를 개선하고 싶을 때</li>
  <li>치아 길이·형태를 보철(크라운·베니어)로 조정할 때</li>
  <li>교정·치주치료 등 다학제적 접근이 필요한 경우</li>
  <li>미소의 좌우대칭이나 연령에 따른 변화가 걱정될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>심미 라인 개선은 환자 개개인의 얼굴·입술 움직임을 고려한 맞춤 설계가 필요합니다. 단순 보철만으로 해결되지 않으면 교정이나 잇몸 수술이 병행될 수 있으며, 치료 계획은 이음치과와 같은 전문의 상담을 통해 결정하는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='smile-line';
UPDATE dict_terms SET full_desc='<p>치관 길이 연장술(클라운 렝스닝)은 잇몸 조직과 필요하면 잇몸 아래 뼈를 일부 정리해 겉으로 보이는 치아 길이를 늘리는 수술입니다. 보철물을 올릴 충분한 치아가 없거나 잇몸이 많이 보여 미용적 불만이 있을 때 치아를 더 드러내어 보철의 지지력과 심미성을 개선합니다.</p>

<h3>원리 또는 특징</h3>
<p>잇몸(연조직)만 제거하거나 잇몸을 들춰 뼈(치조골)를 깎아 치아의 임상치관을 연장합니다. 국소마취로 시행하고 봉합이 필요하며 생체폭(biologic width)을 확보해 치주건강을 유지하는 것이 원칙입니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>보철(크라운·브릿지) 장착을 위해 충분한 치아 높이가 부족할 때</li>
  <li>웃을 때 잇몸이 과도하게 보이는 ‘거미스마일’ 보정</li>
  <li>치아가 깨지거나 충치가 잇몸 아래에 있어 노출이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 후 6~12주 정도 치유 기간이 필요해 최종 보철물 장착까지 시간이 걸립니다. 시술로 인해 일시적 민감함이나 치근 노출이 생길 수 있고, 경우에 따라 교정적 치아견인을 대안으로 고려합니다. 안전한 치료 계획은 이음치과에서 상담으로 결정합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='crown-lengthening';
UPDATE dict_terms SET full_desc='<p>2차 충치는 이미 치료해 넣은 충전물(레진·아말감) 주위에서 새로 생기는 우식으로, 충전물과 치아 경계가 벌어지거나 접착이 약해져 세균이 침투하면서 발생합니다. 초기에는 통증 없이 진행되는 일이 많아 시각적 변화나 방사선으로 발견되는 경우가 흔합니다.</p>
<h3>원리 또는 특징</h3>
<p>충전물과 치질 사이의 미세누출로 음식물 찌꺼기와 세균이 들어가 경계부가 탈회되어 재우식이 생깁니다. 탐침으로 연화된 부위를 확인하거나 방사선 사진에서 음영을 보고 진단하며, 재발 위험은 재료·시술기법·구강위생에 좌우됩니다.</p>
<h3>관련 상황</h3>
<ul>
  <li>오랜 시간 사용한 충전물의 마모나 균열이 있는 경우</li>
  <li>충전물 가장자리에 착색이나 염증 반응이 보일 때</li>
  <li>과거 치료 시 잔존 우식이나 접착 불량이 의심되는 경우</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>조기 발견 시 충전물 교체나 보수로 끝나지만 진행되면 신경치료나 발치가 필요할 수 있습니다. 정기 검진과 엑스선 촬영, 철저한 칫솔질로 예방 가능하므로 이상이 느껴지면 이음치과 같은 전문의에게 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='secondary-caries';
UPDATE dict_terms SET full_desc='<p>직접 수복은 치아의 손상된 부분에 레진 등 수복재를 곧바로 채워 모양과 기능을 회복시키는 치료입니다. 치아 표면에 접착제를 바르고 겹겹이 재료를 쌓아 형태를 만들기 때문에 기공소 작업이 필요 없어 한 번 내원으로 끝나는 경우가 많습니다.</p>

<h3>원리 또는 특징</h3>
<p>충전재와 치아를 접착시키는 방식으로 결손을 밀착 봉합합니다. 색 맞춤이 가능해 앞니 심미 수복에 유리하며, 수복부를 최소한으로 삭제해 치아 조직을 보존합니다. 다만 기술에 민감하고 수축이나 마모 가능성이 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>초기 충치나 소규모 치아 결손</li>
  <li>치아 파절의 소규모 수복</li>
  <li>심미적 결손 보정(앞니 색 맞춤 등)</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 후 변색이나 마모가 생길 수 있어 정기검진과 관리가 중요합니다. 매우 큰 결손은 내구성이 떨어질 수 있어 인레이나 크라운 같은 간접 수복을 권할 수 있습니다. 자세한 상담은 이음치과에서 치아상태를 확인한 뒤 결정합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='direct-restoration';
UPDATE dict_terms SET full_desc='<h3>간단한 설명</h3>
<p>간접 수복은 환자의 치아 본을 떠 기공소에서 제작한 인레이·온레이·크라운 같은 수복물을 치과에서 접착해 손상된 치아를 회복하는 방법입니다. 직접 채우는 방식보다 형태와 색조를 정밀하게 맞출 수 있어 심미성과 강도가 우수합니다.</p>
<h3>원리 또는 특징</h3>
<p>치아를 본떠 만든 정밀 모형을 바탕으로 기공사가 도자기·금속·복합레진 등으로 수복물을 제작합니다. 임시 수복으로 상태를 유지한 뒤 최종 기공물을 맞춰 접착하므로 정확한 적합성과 높은 내구성을 얻을 수 있습니다. 치료 횟수가 늘고 비용이 비교적 높을 수 있습니다.</p>
<h3>언제 필요한가 / 관련 상황</h3>
<ul>
<li>큰 충치로 치아 삭제 범위가 넓을 때</li>
<li>심미적 복원이 특히 중요할 때(앞니 등)</li>
<li>직접 충전으로는 내구성이 부족할 것으로 예상될 때</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>간접 수복은 장점이 많지만 제작 기간과 비용, 치아 삭제량을 고려해야 합니다. 신경치료 여부나 접착력에 따라 예후가 달라질 수 있으니 세부 재료와 과정은 이음치과에서 상담을 통해 결정하는 것이 좋습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='indirect-restoration';
UPDATE dict_terms SET full_desc='<p>광중합은 충치 치료나 심미 수복에 쓰이는 레진 복합재를 LED에서 나오는 가시광선으로 굳히는 과정입니다. 빛에 반응하는 개시제가 활성화되어 단량체들이 서로 결합하며 단단한 플라스틱 형태로 변합니다. 한 번에 두껍게 굳히기보다 얇게 나누어(적층법) 빛을 조사하면 수축과 간극 발생을 줄여 수복물의 내구성을 높일 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>대부분의 레진에는 캄포로퀴논 같은 광개시제가 들어 있어 약 450nm 전후의 청색광에 의해 라디칼 중합이 시작됩니다. LED 광원은 강도와 파장이 안정적이라 빠른 경화가 가능하고, 조사시간·광강도·팁 위치가 경화 깊이와 완성도에 영향을 줍니다. 불완전 경화는 변색이나 탈락의 원인이 됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치아 충전(레진 수복) 시</li>
  <li>치아 색상 보철물의 접착 및 보강 작업</li>
  <li>실런트(홈메우기)나 접착제 경화</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치료 시 광원 팁과 치면 사이 거리를 줄이고 제조사 권장 조사시간을 준수하는 것이 중요합니다. 과도한 열감이나 빛 노출을 줄이기 위해 보호장비를 사용하며, 불완전 경화가 의심되면 보철물 교정이나 재시술이 필요할 수 있습니다. 이음치과에서는 광중합 장비와 작업 방식을 표준화해 안정적인 수복 결과를 제공합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='light-curing';
UPDATE dict_terms SET full_desc='<p><strong>치수 괴사(Pulp Necrosis)</strong>는 충치나 외상, 또는 혈류 차단 등으로 치아 내부의 신경과 혈관(치수) 조직이 사멸한 상태를 말합니다. 죽은 치수는 통증을 가라앉힐 수 있지만 세균 감염에 취약해 근단부(치아 뿌리 주변)로 염증이 확산될 수 있으므로 조기 진단과 치료가 필요합니다.</p>

<h3>원리 또는 특징</h3>
<p>사멸한 치수는 생존 반응(열·전기 자극)에 무반응이고, 치아 변색이 생길 수 있습니다. 방사선 사진에서 근단부에 어두운 그림자(골 소실)가 보일 수 있으며, 장기간 방치하면 농양이나 치주 손상을 초래합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>깊게 진행된 충치로 치수까지 감염이 미친 경우</li>
  <li>교통사고 등으로 인한 치아 외상이나 파절</li>
  <li>반복적인 수복치료나 치수 혈류 손상</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>통증이 사라졌더라도 방치하면 합병증 위험이 커집니다. 일반적으로 근관치료(신경치료)로 치아를 보존할 수 있고, 치아 상태에 따라 발치가 필요할 수 있으므로 임상검사와 방사선 촬영으로 정확한 진단을 받아야 합니다. 필요 시 이음치과에서 평가와 치료 계획을 세울 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='pulp-necrosis';
UPDATE dict_terms SET full_desc='<p><strong>치근단 병변</strong>은 치아 뿌리 끝 부위에 생기는 염증성 변화로, 주로 치아 내부(치수)가 괴사하면서 세균이 뿌리 끝 주변 뼈로 퍼져 발생합니다. 염증이 진행되면 고름 주머니(농양)나 낭종 형태가 되기도 하며, 방사선 사진에서는 뿌리 끝 부위의 어두운 음영으로 관찰됩니다. 이음치과에서 흔히 검토하는 문제입니다.</p>

<h3>원리 또는 특징</h3>
<p>치수 조직이 감염되면 세균과 염증 산물이 근단을 통해 주변 골조직으로 나옵니다. 초기에는 증상이 없을 수 있으나, 염증이 악화되면 통증·부종·압통이 나타나고 X‑ray상 방사선 투과성 병소로 확인됩니다. 병소는 육아종, 농양, 혹은 낭종으로 분류됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>깊은 충치나 외상으로 치수가 괴사한 경우</li>
  <li>치아가 눌리거나 욱신거릴 때, 잇몸에 부종·고름이 보일 때</li>
  <li>무증상이나 정기검진 X‑ray에서 뿌리끝의 검은 그림자가 관찰될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치근단 병변은 크기와 원인에 따라 근관치료, 재치료, 혹은 외과적 치료(근단절제술)나 발치가 필요할 수 있습니다. 증상이 없다고 방치하면 뼈 손실이 진행될 수 있으니 영상 및 임상 평가를 받아 적절한 치료 계획을 세우는 것이 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='periapical-lesion';
UPDATE dict_terms SET full_desc='<p>치아 파절은 충격이나 지속적인 과도한 교합력으로 인해 치아 표면에 금이 가거나 일부가 깨지는 상태를 말합니다. 손상은 법랑질만 국한된 작은 금에서부터 치수와 치근까지 침범해 발치가 필요한 심한 파절까지 다양하며, 증상과 치료법이 달라집니다.</p>

<h3>원리 또는 특징</h3>
<p>치아는 법랑질·상아질·치수로 구성되어 손상 깊이에 따라 통증·감염 위험이 달라집니다. 미세균열은 시간이 지나며 진행될 수 있고, 이전에 큰 수복물이나 신경치료를 받은 치아는 더 취약합니다. 증상으로는 씹을 때 통증·시린감·치아색 변화·교합 불편감 등이 나타납니다.</p>

<h3>관련 상황</h3>
<ul>
<li>낙상이나 스포츠·교통사고 등 외상으로 인한 급성 파절</li>
<li>이갈이(브룩시즘)나 과도한 교합압으로 생기는 점진적 금</li>
<li>대형 수복물이나 신경치료로 약해진 치아</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단은 시진·방사선·치아 착색검사·교합검사로 합니다. 치료는 연마나 직접 수복, 인레이·크라운, 필요시 근관치료 또는 발치까지 다양하며 조기 치료가 예후를 좋게 합니다. 의심되면 빠르게 진단받아 적절한 보존치료 계획을 세우는 것이 중요하며, 이음치과에서 평가받을 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tooth-fracture';
UPDATE dict_terms SET full_desc='<p>미세 누출은 충전물(예: 레진)과 치아 사이에 남은 아주 작은 틈으로, 타액이나 세균이 그 틈을 통해 들어가면서 2차 충치, 변색, 시린 증상이나 염증을 유발할 수 있는 현상입니다. 접착이 완전하지 않거나 수복물의 수축·열변형이 있을 때 흔히 발생하며, 정밀한 술식으로 예방합니다. 이음치과에서는 층별 적층과 정확한 접착 기법을 권합니다.</p>

<h3>원리 또는 특징</h3>
<p>레진의 중합수축, 치아와 수복물의 열팽창률 차이, 마진부의 불완전한 적합이 미세한 간극을 만듭니다. 이 간극을 통해 유체 이동과 세균 침투가 일어나며 시간이 지나면 2차 우식이나 착색, 치수 자극으로 진행될 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>복합레진 수복 후 접착 불량이 의심될 때</li>
  <li>오래된 충전물의 가장자리에 착색이나 시린 증상이 있는 경우</li>
  <li>치아 마진이 손상되거나 수복물이 느슨해진 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>예방은 정확한 접착제 사용, 건조·오염 방지, 층별 광중합 등 술기의 질에 달려 있습니다. 증상(시린 감각, 착색, 통증)이 있으면 정기검진을 통해 조기 진단하고 필요시 재수복을 고려해야 합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='microleakage';
UPDATE dict_terms SET full_desc='<h3>수산화 칼슘이란</h3>
<p>수산화 칼슘은 치아 치료 시 치수(치아 속 신경과 혈관)를 보호하고 감염을 억제하기 위해 쓰이는 알칼리성 약제입니다. 충치로 인해 치수가 드러났을 때 보호재로 쓰거나 근관치료 중 근관 내 소독과 임시 충전제로 사용됩니다. 상아질 재생을 촉진하는 특성이 있어 임상에서 널리 활용됩니다.</p>

<h3>원리 또는 특징</h3>
<p>강한 알칼리성(pH 약 12)으로 세균을 억제하고 염증을 가라앉혀 치수 조직이 새로운 상아질을 만들도록 자극합니다. 페이스트나 페이스트를 담은 약봉으로 적용하며 서서히 용해되어 작용합니다. 조직 친화적이나 단독 사용만으로 모든 감염을 완전히 제거하지 못할 수 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치수 복조술(충치 제거 후 치수가 일부 노출된 경우)</li>
  <li>근관치료 중 근관 내 소독 및 임시 내복약</li>
  <li>치근단 병소 치료 시 보조적 사용</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>즉시 통증을 완전히 없애는 약은 아니며, 치료 경과에 따라 재적용이나 추가 치료가 필요할 수 있습니다. 드물게 자극이나 민감 반응이 있을 수 있으므로 이상 증상이 있으면 의료진에게 알리세요. 이음치과에서는 환자 상태에 맞춰 적절히 선택해 사용합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='calcium-hydroxide';
UPDATE dict_terms SET full_desc='<p>치수 생활력 검사는 충치나 외상으로 손상된 치아 속 신경(치수)이 아직 기능하는지 확인하는 간단한 진단입니다. 냉검사나 전기적 자극으로 환자에게 감각 반응이 있는지를 관찰해 치수의 생존 가능성을 추정하며, 진단과 치료 계획을 세우는 데 중요한 정보가 됩니다. 이음치과에서도 자주 시행합니다.</p>
<h3>원리 또는 특징</h3>
<p>냉검사는 차가운 자극이 상아질을 통해 신경을 자극하면 통증 반응으로 생존을 유추하고, 전기 생활력 검사(EPT)는 약한 전류로 신경의 감각 반응을 확인합니다. 두 검사는 신경의 감각 반응을 본다는 점에서 혈류를 직접 측정하지 않아 거짓 음성·양성 가능성이 있습니다.</p>
<h3>언제 필요한가 / 적응증</h3>
<ul>
<li>원인 불명의 치통 원인 감별</li>
<li>치아 외상 후 신경 손상 여부 평가</li>
<li>근관치료 필요성 판단 및 치료 전 진단</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>검사는 짧고 대체로 편안하지만 순간적인 불편감이 있을 수 있습니다. 나이, 약물, 보철물, 치아 발육 상태 등에 따라 반응이 달라질 수 있어 검사 결과만으로 확정하지 않고 방사선 검사 등 다른 소견과 함께 종합 판단합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='pulp-vitality-test';
UPDATE dict_terms SET full_desc='<p>치주 프로빙은 얇은 금속 탐침을 치아와 잇몸 사이에 넣어 치주낭의 깊이를 밀리미터 단위로 재는 검사입니다. 단순하지만 잇몸 염증과 치주질환의 유무 및 진행 정도를 객관적으로 평가해 치료 계획을 세우는 기초 정보가 됩니다.</p>

<h3>원리 또는 특징</h3>
<p>프로브를 잇몸 틈에 수평·수직으로 일정한 압력으로 넣어 치아마다 통상 6곳의 깊이를 기록합니다. 깊이가 4mm 이상이면 치주낭 확장으로 의심하며, 탐침 시 출혈이 있으면 활동성 염증을 시사합니다. 숫자(mm)로 관리해 치료 전후 비교가 가능합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>정기 구강검진 시 치주 상태 평가</li>
  <li>잇몸에서 피가 나거나 붓기가 있을 때</li>
  <li>치주치료(스케일링·루트플레인) 전후 경과 관찰</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>검사는 짧고 안전하지만 가벼운 통증이나 출혈이 있을 수 있습니다. 출혈이 많거나 항응고제를 복용 중이면 미리 알려 주세요. 측정 결과는 스케일링, 치주치료 여부와 추적 관찰 주기를 결정하는 데 쓰이며, 필요 시 이음치과에서 상세 상담을 받을 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='periodontal-probing';
UPDATE dict_terms SET full_desc='<p>치태 조절은 입 안 치아 표면과 치아 사이에 생기는 세균막(치태)을 올바른 칫솔질과 치실·치간칫솔 같은 보조기구로 규칙적으로 제거해 잇몸과 치아 건강을 지키는 자기관리입니다. 치태를 꾸준히 억제하면 잇몸 염증을 줄이고 치주치료의 효과를 오래 유지할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치태는 침과 세균이 결합한 바이오필름으로 표면에 단단히 붙습니다. 기계적 제거가 핵심이어서 칫솔만으로 닿지 않는 치간부위는 치실이나 치간칫솔로 청소해야 합니다. 규칙적인 제거는 염증과 치석 형성을 늦추고 구취 개선에도 도움됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>잇몸이 붓거나 칫솔질 시 출혈이 있을 때</li>
  <li>치주치료 후 유지관리가 필요할 때</li>
  <li>지속적인 입냄새가 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>도구 선택과 사용법은 개인 차가 있어 치과에서 직접 교육받는 것이 가장 효과적입니다. 칫솔모는 약 3개월마다 교체하고, 치간칫솔 사이즈는 치과에서 확인하세요. 정기 스케일링과 병행하면 더 안정적인 관리가 됩니다. 필요 시 이음치과에서 상담받으십시오.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='plaque-control';
UPDATE dict_terms SET full_desc='<h3>무엇인지 한눈에</h3>
<p>잇몸 퇴축은 잇몸이 아래로 내려가 치아 뿌리 부분이 드러나는 상태로, 단순한 미용 문제를 넘어서 시린 증상이나 뿌리 충치 위험을 높입니다. 원인은 여러 가지이며 서서히 진행되므로 조기 진단과 적절한 관리가 중요합니다.</p>
<h3>원리 또는 특징</h3>
<p>잇몸 조직이 염증이나 기계적 자극으로 얇아지거나 소실되면 지지 조직이 줄어들어 잇몸선이 후퇴합니다. 초기에는 국소적이고 진행되면 치아 민감성, 치아 이동, 치주낭 형성 등이 동반될 수 있습니다.</p>
<h3>관련 상황</h3>
<ul>
<li>과도한 힘의 칫솔질이나 수평 양치 습관</li>
<li>치주염 같은 잇몸 염증으로 조직 손실이 있을 때</li>
<li>부적절한 교합(맞물림)이나 교정치료 후의 교합 외상</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>예방은 올바른 칫솔질, 구강위생 개선, 교합 조정으로 시작합니다. 증상이 있으면 스케일링·루트플래닝, 민감치료, 심한 경우 잇몸이식술 등으로 치료할 수 있으며, 상세한 평가는 이음치과에서 가능합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gum-recession';
UPDATE dict_terms SET full_desc='<p>에어플로우는 글리신 같은 미세 분말을 공기와 물과 함께 분사해 치아 표면과 잇몸 경계의 착색, 바이오필름(미생물막), 연성 침착물을 부드럽게 제거하는 예방치료 장비입니다. 마찰로 오염물을 떼어내기 때문에 치질 손상을 최소화하면서 빠르고 효과적인 클리닝이 가능합니다.</p>

<h3>원리 또는 특징</h3>
<p>미세한 분말 입자가 분사되어 오염물을 물리적으로 박리합니다. 글리신 분말은 입자가 가늘어 잇몸 가장자리와 일부 잇몸 아래 부위까지 안전하게 접근할 수 있고, 통증과 민감도가 비교적 낮습니다. 보철물이나 임플란트 표면에도 적용 가능하며, 기존 스케일링의 보조적 역할을 합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>담배·커피·차 등으로 인한 치면 착색 제거</li>
  <li>치주질환 관리 시 바이오필름 제거</li>
  <li>보철물·임플란트 표면의 유지관리</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>이미 굳은 치석은 에어플로우만으로 제거되지 않아 별도의 스케일링이 필요합니다. 호흡기 질환이나 분사에 민감한 분은 미리 알려주시면 안전하게 시행하며, 감염 우려가 있을 때는 의료진이 적절히 평가합니다. 정기적인 예방치료로 구강 건강 유지에 도움이 되며, 이음치과에서도 일반적인 클리닝 옵션으로 제공됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='airflow';
UPDATE dict_terms SET full_desc='<h3>유지 관리란</h3>
<p>유지 관리(Periodontal Maintenance)는 치주 치료의 활동기를 마치고 잇몸 상태를 안정적으로 유지하기 위해 주기적으로 시행하는 장기 관리 프로그램입니다. 정기 검진과 전문적인 치석·치면세척, 구강위생 교육을 통해 잔존 염증을 억제하고 치주조직의 건강을 오래 유지하는 것을 목표로 합니다.</p>

<h3>원리 또는 특징</h3>
<p>치주질환은 한 번의 치료로 완전히 끝나지 않으므로 주기적인 염증 평가와 기계적 제거로 박테리아 부하를 낮추는 것이 핵심입니다. 치주낭 깊이, 출혈 여부, 치석 재축적, 치아동요 등을 정기적으로 확인해 치료 효과를 점검하고 필요 시 추가 치료로 이어집니다. 개인 위험요인에 따라 관리 간격을 조정합니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>활동기 치주 치료(스케일링·루트플래닝)를 완료한 경우</li>
  <li>임플란트나 보철물 주변 염증을 예방해야 할 때</li>
  <li>흡연·당뇨 등 재발 위험이 높은 환자</li>
  <li>잇몸 출혈이나 구취가 반복되는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>정해진 간격을 지키는 것이 재발 방지에 가장 중요하며, 개인 구강위생 습관과 전신 상태에 따라 간격을 3~6개월로 조정합니다. 검사 결과에 따라 추가 스케일링이나 재치료가 필요할 수 있으니 의사와 계획을 상의하세요. 이음치과 등에서 개인 맞춤 관리로 장기 예후를 개선할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='maintenance-therapy';
UPDATE dict_terms SET full_desc='<p>치은 비대는 잇몸 조직이 과도하게 커지거나 두꺼워지는 상태로, 잇몸이 부풀어 치아 일부를 덮거나 잇몸선이 불규칙해 보일 수 있습니다. 원인으로는 약물 복용(예: 항경련제·면역억제제·칼슘통로차단제), 치태(플라그) 축적, 호르몬 변화 등이 있고 염증과 섬유성 증식이 함께 나타납니다. 출혈, 냄새, 칫솔질 어려움 등이 동반될 수 있으며 정확한 진단과 치료계획은 이음치과에서 개별적으로 평가합니다.</p>

<h3>원리 또는 특징</h3>
<p>치은 비대는 염증성 세포반응으로 인한 부종성 변화와 섬유아세포 증식에 따른 섬유화가 섞여 발생합니다. 약물 유발성일 경우 잇몸 결합조직이 과다 성장하고, 치태가 많으면 만성 염증으로 더 악화됩니다. 증상의 정도는 약물용량·구강위생·호르몬 상태 등에 따라 달라집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>특정 약물 복용 후 잇몸이 점점 커지는 경우(항경련제·면역억제제·칼슘통로차단제)</li>
  <li>칫솔질이 어려워 치태가 쌓이고 잇몸이 붓는 경우</li>
  <li>사춘기·임신 등 호르몬 변화로 잇몸이 민감해진 경우</li>
  <li>유전적 소인이나 전신질환으로 잇몸 변화가 반복되는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기에는 철저한 구강위생 관리와 전문적인 스케일링으로 호전될 수 있으나, 약물 관련 성장이나 섬유화가 심하면 치은 절제술이 필요할 수 있습니다. 약물 영향이 의심되면 담당 의사와 상의해 약 조정 가능성을 검토하고, 정기적인 치과 검진과 관리로 합병증을 줄이는 것이 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='gingival-hyperplasia';
UPDATE dict_terms SET full_desc='<h3>출혈 지수(Bleeding on Probing)란</h3>
<p><strong>출혈 지수</strong>는 치과에서 치주 탐침기로 잇몸 주머니를 검사할 때 탐침 자극으로 피가 나는지를 기록하는 간단한 검사입니다. 잇몸에서 탐침 시 출혈이 관찰되면 그 부위에 염증이 남아 있음을 시사해, 치주 질환의 활동성을 판단하고 치료 경과를 확인하는 데 유용합니다.</p>

<h3>원리 또는 특징</h3>
<p>치주 탐침이 잇몸 조직을 자극하면 염증으로 인해 혈관이 약해진 부위에서 쉽게 출혈이 발생합니다. 출혈의 유무를 부위별로 기록해 전체 치아 중 출혈이 있는 비율로 지수를 계산하거나, 각 치아면별로 평가합니다. 단순하고 재현성이 높아 임상에서 널리 사용됩니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>치주염 의심 시 초기 평가와 치료 전·후 비교</li>
  <li>정기 검진에서 잇몸 염증의 활동성 확인</li>
  <li>치주 치료 후 치유 상태 모니터링</li>
  <li>항응고제 복용자나 임신 등 출혈 경향 평가 시 참고</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>출혈이 있다고 해서 항상 중증 치주염을 의미하지는 않으며, 탐침 압력이나 칫솔질 상태, 약물 영향 등이 결과에 영향을 줄 수 있습니다. 반대로 흡연자는 혈관수축으로 출혈이 적게 나타나 활동성 염증이 은폐될 수 있습니다. 검사 결과는 구강위생 개선, 스케일링 등 치료 방향 설정에 도움되며, 필요 시 이음치과와 상의해 맞춤 관리를 받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='bleeding-index';
UPDATE dict_terms SET full_desc='<h3>치주 재생술이란</h3>
<p>치주 재생술은 잇몸염증으로 파괴된 치조골(치아를 지지하는 뼈)과 치주인대를 가능한 한 원래 상태로 되돌리기 위해 시행하는 수술입니다. 골이식재, 차폐막(막으로 상피세포를 차단)과 성장인자 등을 함께 사용해 잇몸 주위의 소실된 구조를 재구성하여 치아의 지지력을 회복하는 것을 목표로 합니다.</p>

<h3>원리 또는 특징</h3>
<p>핵심 원리는 선택적 세포 재생입니다. 차폐막으로 빠르게 자라는 상피와 결합조직이 들어오는 것을 막아 골·치주인대를 형성하는 세포가 자리를 잡도록 하고, 골이식재는 뼈가 자랄 틀을 제공하며 성장인자는 세포 증식과 분화를 촉진합니다. 치유에는 수개월이 걸릴 수 있고 결과는 결손 형태와 환자 상태에 따라 달라집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>깊은 수직형 치조골 결손(치조골이 국소적으로 크게 소실된 경우)</li>
  <li>치근분기부(퍼케이션) 침범으로 지지력 저하가 우려될 때</li>
  <li>잇몸뼈 소실로 치아 흔들림이 생겨 치아를 보존하고자 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 성공률은 환자의 구강위생, 흡연 여부, 전신질환(예: 조절되지 않는 당뇨)과 결손의 모양에 크게 좌우됩니다. 시술 후 적절한 관리와 정기 관찰이 필수이며, 재생이 항상 완전하게 이루어지지 않을 수 있다는 점을 미리 알고 계셔야 합니다. 자세한 진단과 치료계획은 이음치과에서 상담을 통해 확인받으실 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='periodontal-regeneration';
UPDATE dict_terms SET full_desc='<h3>무엇인가요?</h3>
<p>턱관절 안에는 뼈 사이의 충격을 흡수하는 관절원판(디스크)이 있습니다. 디스크가 정상 위치에서 앞쪽이나 다른 위치로 벗어나면 입을 벌릴 때 ''딸깍'' 소리가 나거나 입이 잘 안 열리고 통증이 생길 수 있는 상태를 말합니다. 증상과 심한 정도는 사람마다 다릅니다.</p>

<h3>원리 또는 특징</h3>
<p>정상에서는 관절면 사이에 디스크가 균형을 유지해 움직임을 돕습니다. 디스크가 앞쪽으로 밀리면 턱뼈가 움직일 때 디스크가 걸렸다가 돌아오면서 소리가 나고(감축성), 완전히 걸려 돌아오지 않으면 개구 제한(비감축성)이 나타납니다. 원인은 외상, 이갈이·과도한 사용, 관절염 등 다양합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>입을 크게 벌릴 때 딸깍거리는 소리나 마찰감이 날 때</li>
  <li>입이 잘 안 열리거나 한쪽으로 치우쳐 열릴 때</li>
  <li>턱·귀 주변에 통증이나 뻣뻣함이 지속될 때</li>
  <li>스트레스나 이를 악물 때 증상이 악화될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기에는 물리치료, 교합장치(스플린트), 약물, 생활습관 교정으로 호전되는 경우가 많습니다. 정확한 진단은 진찰과 필요시 MRI로 확인하며, 중증·만성에서는 전문의의 추가치료나 수술적 접근을 고려합니다. 자세한 상담은 이음치과에서 평가받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='disc-displacement';
UPDATE dict_terms SET full_desc='<h3>턱관절 클릭이란</h3>
<p>턱을 벌리거나 닫을 때 나는 ''딸깍'' 소리로, 관절 안의 쿠션 역할을 하는 관절원반(디스크)이 제자리에서 벗어났다가 입을 벌릴 때 다시 제자리로 돌아오며 소리가 나는 현상입니다. 많은 경우 통증 없이 소리만 나므로 즉시 큰 치료가 필요하지는 않습니다.</p>

<h3>원리 또는 특징</h3>
<p>턱뼈(하악골)와 두개골의 관절면 사이에 있는 디스크가 정상 위치보다 앞이나 옆으로 이동하면, 개구 시 디스크가 되돌아오면서 소리가 납니다. 소리는 한 번만 나거나 반복적으로 들릴 수 있고, 때로는 통증·개구장애·근육 긴장이 함께 나타날 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>통증이나 입 벌림의 제한이 동반될 때</li>
  <li>턱이 걸리거나 잠김(락)이 생길 때</li>
  <li>소리만 있고 통증이 없으면 경과 관찰이 가능한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>증상이 가벼우면 온찜질·부드러운 식사·턱 사용 제한·자가 운동이나 물리치료로 호전되는 경우가 많습니다. 통증이나 기능장애가 심하면 보존적 치료(스플린트 등)나 전문적 평가가 필요하니 이음치과의 턱관절 클리닉에서 정확한 진단을 받아보는 것이 좋습니다. 수술은 드물게 고려됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tmj-clicking';
UPDATE dict_terms SET full_desc='<p>턱관절 잠김은 턱뼈와 관절원반(디스크) 또는 관절 위치의 문제로 인해 입이 제대로 열리지 않거나 반대로 다물어지지 않는 증상입니다. 갑자기 입이 안 열리거나 닫히지 않아 식사·말하기에 불편을 주며, 원인과 형태에 따라 치료법이 달라집니다.</p>

<h3>원리 또는 특징</h3>
<p>관절원반이 정상 위치에서 벗나 턱뼈에 걸리면 입이 잘 열리지 않는 폐구장애가 생기고, 턱뼈가 앞쪽으로 빠지면 다물기 어려운 개구장애가 나타납니다. 통증, 딱거리는 소리(크리피투스), 턱의 편위가 흔히 동반됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>크게 하품하거나 한 번에 많이 벌린 뒤 갑작스럽게 발생</li>
  <li>이갈이·교합 이상으로 관절에 지속적 스트레스가 쌓인 경우</li>
  <li>얼굴에 외상이나 급성 근육 경련이 있었던 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기엔 휴식, 부드러운 음식 섭취, 온찜질, 진통제와 물리치료로 좋아지는 경우가 많고, 필요 시 전문의의 수동정복이나 교정장치로 조정합니다. 입이 전혀 안 열리거나 심한 통증·삼킴장애가 있으면 턱관절 전문(예: 이음치과)에서 빠른 평가를 받는 것이 안전합니다. 만성화하면 맞춤장치나 주사·수술적 치료가 고려될 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tmj-locking';
UPDATE dict_terms SET full_desc='<p><strong>교합 간섭</strong>은 턱을 다물거나 옆으로 움직일 때 특정 치아가 먼저 닿아 정상적인 턱 운동 경로를 방해하는 상태입니다. 이런 불균형한 접촉은 턱 근육의 긴장, 치아 마모, 턱관절 통증을 유발할 수 있으며 정확한 진단을 통해 원인과 위치를 파악합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 접촉이 균등하지 않으면 하악의 이동 경로가 바뀌어 근육 과긴장이나 관절 부담이 생깁니다. 보철물이나 충전물 높이, 치아 이동 등이 원인이며 소리(딱거림), 통증, 편두통 유발과 연관될 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>새 보철·크라운 시술 후 부적절한 높이</li>
  <li>교정 치료나 치아 이동으로 교합 변화가 생긴 경우</li>
  <li>이갈이(브럭시즘)나 강한 클렌칭이 있는 환자</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치료는 간단한 교정, 보철물 재조정, 스플린트(야간 보호장치) 등으로 시작합니다. 원인이 다양해 턱관절 상태를 함께 평가하는 것이 중요하며, 전문적인 진단과 맞춤 치료를 위해 이음치과 등에서 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='occlusal-interference';
UPDATE dict_terms SET full_desc='<p>보톡스 치료는 교근(씹는 근육)에 보툴리눔톡신을 소량 주사해 과도한 근육 긴장을 풀고 턱관절에 가해지는 부담과 통증을 줄여주는 보조적 치료입니다. 이갈이·악물기로 인해 생긴 근육성 통증이나 교근 비대 개선에 도움이 될 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>보톡스는 신경-근육 접합부에서 신경전달물질의 방출을 억제해 근육 수축을 감소시킵니다. 효과는 주사 후 며칠 내 시작되고 2주쯤 최대로 나타나며 보통 3~6개월 지속하므로 필요 시 반복 시술합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>밤새 이갈이·심한 악물기로 교근이 비대해진 경우</li>
  <li>근육성 턱 통증이나 긴장이 주된 원인일 때</li>
  <li>교정·보존치료 과정에서 턱 긴장 완화가 보조적으로 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>보톡스는 증상 완화의 보조수단이며 근본적 치료가 아닙니다. 씹기 약화, 표정 변화 등이 일시적으로 나타날 수 있고 임신·수유 중이거나 중증 신경근육질환이 있는 경우 피해야 합니다. 정확한 진단과 숙련된 시술이 중요하므로 이음치과에서 상담 후 결정하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='botox-tmj';
UPDATE dict_terms SET full_desc='<h3>브래킷이란</h3>
<p>브래킷은 교정 기구에서 치아 표면에 붙여 와이어를 고정하는 작은 장치로, 치아에 전달되는 힘을 정확히 통제해 이동을 돕습니다. 금속·세라믹 등 재질이 있으며, 심미성이나 치료 방식에 따라 선택합니다. 이음치과에서도 환자 상태에 맞춰 적합한 종류를 권합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 표면에 본딩제로 고정하고 아치와이어와 결합해 지속적인 힘을 줍니다. 전통적 묶음(라텍스·철선) 방식과 와이어 자체로 고정하는 셀프라이게이션형이 있어 유지력·마찰 정도가 다릅니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>고르지 않은 치열을 바로잡을 때</li>
  <li>교합(위·아래 맞물림) 개선이 필요할 때</li>
  <li>심미적 이유로 치아 위치를 조정할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>부착 후 초기 불편감이나 잇몸 자극이 있을 수 있고, 단단하거나 끈적한 음식은 브래킷 손상을 유발하니 주의하세요. 탈락 시 재부착이 필요하며, 제거 시에는 전문의가 안전하게 떼어내므로 과다한 힘으로 제거하지 마십시오.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='bracket';
UPDATE dict_terms SET full_desc='<h3>교정 와이어란 무엇인가요?</h3>
<p>교정 와이어는 브래킷에 걸어 치아를 이동시키는 금속 선으로, 치아 배열을 바르게 잡는 데 핵심 역할을 합니다. 니켈티타늄(NiTi)계와 스테인리스강계 등 재료에 따라 탄성력과 강도가 달라 초기·중기·마무리 단계에 맞춰 교체하며, 교정 장치의 설계에 따라 다양한 굵기와 단면을 사용합니다. 이음치과에서도 환자 상태에 맞게 와이어를 선택합니다.</p>

<h3>원리 또는 특징</h3>
<p>와이어의 탄성력이 브래킷을 통해 치아에 지속적이고 조절된 힘을 전달하면 치주조직이 재형성되어 치아가 이동합니다. NiTi는 저온에서 유연하고 형태기억성이 있어 초기 정렬에 유리하고, 스테인리스는 강성이 높아 치아 회전·교합 조정 등 마무리 단계에서 사용됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치열의 초기 정렬(비대칭·험한 배열)이 필요할 때</li>
  <li>공간 폐쇄나 간격 조절이 필요할 때</li>
  <li>교합 조정이나 치아 회전·앵글 교정이 요구될 때</li>
  <li>치료 중 와이어 교체·조정으로 세밀한 이동을 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기에는 통증이나 쓴 느낌이 있을 수 있고, 와이어가 입술·볼을 자극할 수 있으니 왁스 사용이나 병원 방문으로 조정을 받으세요. 니켈 알레르기 병력이 있다면 미리 알려야 합니다. 와이어가 휘거나 끊어지면 즉시 내원하는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='orthodontic-wire';
UPDATE dict_terms SET full_desc='<p>교정 치료가 끝난 뒤 새로 맞춘 치아 배열을 안정적으로 잡아주는 장치가 유지 장치(orthodontic retainer)입니다. 치아를 둘러싼 인대와 뼈는 서서히 회복되므로, 초기 몇 개월에서 수년간 유지 장치를 착용해 재발을 막습니다. 이음치과에서도 개인 상태에 맞는 고정식 또는 가철식 중 선택해 처방합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아는 교정 중 이동한 뒤에도 주변 조직이 원래 위치로 돌아가려는 성질이 있어 유지 장치가 필요합니다. 고정식은 치아 뒤쪽에 소구치로 붙여 지속적으로 지지하고, 가철식은 탈착이 가능해 청결 관리가 쉽습니다. 소재는 금속 와이어, 투명 플라스틱 등입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>교정 장치(브라켓·플라스틱 트레이) 제거 직후</li>
  <li>치아 회전이나 간격이 있었던 경우 재발 위험이 클 때</li>
  <li>성장기 또는 사랑니 발치 등으로 치열 변화가 예상될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>처방된 착용 시간(주간·야간)을 지키는 것이 가장 중요합니다. 가철식은 식사 시 빼고 전용 세정제로 관리하고, 고정식은 치실·워터픽 등으로 청결을 유지해야 합니다. 파손이나 불편함이 있으면 빠르게 치과에 상담하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='retainer';
UPDATE dict_terms SET full_desc='<p>안면 비대칭은 얼굴의 좌우 균형이 어긋나 보이는 상태로, 턱뼈(상악·하악) 위치 차이, 얼굴 근육의 불균형, 치아 배열 및 턱관절 기능의 불일치 등이 원인이 됩니다. 단순한 미용적 차이를 넘어서 저작, 발음, 턱관절 통증을 유발할 수 있어 증상과 정도에 따라 보존적 치료부터 교정·악교정수술까지 다양한 치료법을 고려합니다. 이음치과의 턱관절·교정 진료에서는 정밀평가를 통해 치료계획을 세웁니다.</p>

<h3>원리 또는 특징</h3>
<p>안면 비대칭은 선천적 성장편차, 성장기 동안의 불균형, 외상이나 치아상실로 인한 보상성 변화 등으로 발생합니다. 임상적으로는 턱중앙선 편위, 얼굴벌레(cheek canting), 한쪽 악골의 과성장 또는 저성장 등이 관찰되며, 근육 습관(한쪽으로만 씹기 등)이 악화를 유발할 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>심한 외관상의 불만으로 교정·수술을 고려하는 경우</li>
  <li>저작장애·치아맞물림(교합) 문제 또는 발음 이상 동반 시</li>
  <li>턱관절 통증·소리(클릭) 또는 진행성 악화가 있을 때</li>
  <li>성장기 아동의 비대칭 진행 여부 관찰 및 계획이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단은 임상검사와 사진, 파노라마·측두부방사선·필요시 CBCT 같은 영상으로 이루어집니다. 치료는 교정치료 단독으로 가능한 경우와 악교정수술이 필요한 경우로 나뉘며, 연령과 성장상태, 환자의 기대에 따라 접근이 달라집니다. 경미한 비대칭은 흔하며 완전한 대칭 회복이 항상 보장되는 것은 아니므로 현실적인 목표 설정이 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='facial-asymmetry';
UPDATE dict_terms SET full_desc='<p>턱관절 물리치료는 수술을 하지 않고 손이나 기기, 운동을 이용해 턱 주변 근육과 관절의 통증·긴장을 줄이는 치료법입니다. 온찜질, 초음파 치료, 전문 마사지와 함께 환자 맞춤형 턱 운동을 통해 관절 가동범위를 회복하고 일상생활의 통증을 줄이는 데 초점이 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>열과 초음파는 혈류를 증가시켜 염증과 통증을 완화하고, 마사지와 스트레칭은 근육의 과긴장을 풀어 관절 움직임을 개선합니다. 꾸준한 자기운동은 재발을 줄이고 자세를 바로잡는 데 도움됩니다. 비수술적이고 부작용이 적은 편입니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>턱을 벌리거나 씹을 때 통증이 있을 때</li>
  <li>턱이 잘 안 열리거나 잠깐 걸리는(잠금) 증상이 있을 때</li>
  <li>턱 주변 근육이 뻣뻣하고 잦은 근육통이 있는 경우</li>
  <li>턱에서 소리가 나거나 교합 불편감이 동반될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치료는 개인 상태에 따라 기간과 방법이 달라 꾸준한 관리가 필요합니다. 일부 환자는 물리치료만으로 증상이 호전되지 않아 보존적 치료와 치과적 교합 조정 또는 전문의 상담이 병행될 수 있습니다. 치료 전 정확한 평가를 위해 이음치과에서 진단을 받는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='physical-therapy';
UPDATE dict_terms SET full_desc='<p>소대 절제술은 입술이나 혀 밑의 점막 띠(소대)가 지나치게 짧거나 두꺼워 입모양·발음·치열에 영향을 줄 때 해당 소대를 짧게 하거나 제거하여 기능을 회복시키는 간단한 수술입니다. 수유 문제나 앞니 사이 벌어짐을 개선하고자 소아에게서 자주 시행됩니다. 이음치과에서도 외래에서 시행합니다.</p>

<h3>원리 또는 특징</h3>
<p>짧은 소대를 절개하거나 레이저로 정리해 길이를 늘리면 움직임이 좋아집니다. 국소마취(또는 영아의 경우 간단한 진정)로 진행하며 출혈은 적고 봉합은 흡수사로 하는 경우가 많아 외래에서 빠르게 회복됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>젖물기나 수유에 어려움이 있는 영아</li>
  <li>발음이 또렷하지 않거나 특정 음을 낼 때 어려움이 있는 경우</li>
  <li>앞니 사이 벌어짐(중앙열공)이나 교정 치료에 방해가 될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>회복은 수일~수주로 통증은 경미한 편이며 간단한 스트레칭 운동이 필요할 수 있습니다. 드물게 출혈·감염·재발이 있을 수 있어 경과 관찰이 필요하고, 경우에 따라 언어치료나 교정치료가 병행됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='frenectomy';
UPDATE dict_terms SET full_desc='<p>영구치 결손은 태어날 때부터 특정 영구치의 싹(치배)이 형성되지 않아 해당 영구치가 나오지 않는 상태입니다. 유치가 오랫동안 남아 있거나 빈 공간으로 인해 보기·씹기에 문제가 생길 수 있어 소아 치과와 교정, 보철적 접근이 필요할 수 있습니다. 이음치과에서도 성장과 시기에 맞춘 치료계획을 세웁니다.</p>

<h3>원리 또는 특징</h3>
<p>치아는 태아기 동안 치배가 만들어져야 자라납니다. 치배가 발생하지 않으면 영구치가 결손되며, 주로 측절치(앞니 옆)와 제2소구치(두번째 소구치)에서 자주 나타납니다. 한 개만 없을 수도 있고 여러 개가 결손되는 경우도 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>유치가 정상시기에도 빠지지 않아 장기간 잔존하는 경우</li>
  <li>치열의 공간 문제(틈이나 배열 이상)가 생긴 경우</li>
  <li>가족력이나 증후군(예: 외피배 발달 이상)이 의심되는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단은 구강검사와 방사선 사진으로 확정합니다. 치료는 성장 상태에 따라 달라져, 유치는 가능한 한 보존해 임시 대체물로 쓰거나 교정으로 공간을 닫고, 성장 완료 후 임플란트나 보철로 영구 대체를 고려합니다. 치과 전문의와의 맞춤상담이 중요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='congenitally-missing';
UPDATE dict_terms SET full_desc='<h3>바이트 윙(X-ray)이란?</h3>
<p><strong>바이트 윙</strong>은 어린이가 작은 필름이나 센서를 물고 이를 꽉 깨물게 한 뒤 촬영하는 구강 내 방사선 검사입니다. 어금니의 씹는 면과 특히 치아 사이(접촉면)를 자세히 보여줘서 겉으로는 보이지 않는 초기 충치나 충치 진행 상태를 확인하는 데 유용합니다.</p>

<h3>원리 또는 특징</h3>
<p>필름을 물고 촬영하면 치아의 맞닿는 부분과 뼈 주변까지 얇은 단층 영상처럼 보입니다. 방사선량이 매우 적고 촬영 시간이 짧아 소아 진료에 적합하며, 디지털 센서를 쓰면 즉시 결과를 확인해 설명하기 쉽습니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>눈에 보이지 않는 어금니 사이 충치 의심 시</li>
  <li>우식 진행 정도를 치료 전·후로 비교할 때</li>
  <li>혼합치열기(유치와 영구치 혼재) 검진 및 치료계획 수립 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>촬영은 짧고 통증이 없지만 센서가 불편해 울거나 구역감을 느낄 수 있어 아이의 협조가 중요합니다. 보호자께서는 검사에 대해 미리 부드럽게 설명해 주시면 도움이 됩니다. 방사선 노출은 최소화하며 보호장비를 사용합니다. 이음치과에서는 어린이 맞춤 설명과 안전한 촬영으로 검사합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='bitewing';
UPDATE dict_terms SET full_desc='<p>치아 나이는 아이의 치아가 나고 자라는 속도를 바탕으로 평가하는 생물학적 연령입니다. 치아의 맹출 순서와 치근 발육 정도를 관찰해 실제 나이와 비교함으로써 성장 발달 단계를 가늠합니다. 교정치료 시기 결정이나 전반적인 성장평가에 유용하며, 이음치과에서는 다른 검사와 함께 종합적으로 판단합니다.</p>

<h3>원리 또는 특징</h3>
<p>치아는 맹출 시기와 뿌리 완성 시점이 비교적 일정한 패턴을 보입니다. 구내 검사와 방사선 사진(파노라마 등)으로 치아의 발육 단계를 보고 표준화된 방법으로 등급화합니다. 치아 나이는 유전, 영양, 전신질환 등에 영향을 받아 만나이와 차이가 날 수 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>교정 치료의 최적 시작 시기를 판단할 때</li>
  <li>성장 지연이나 조기 맹출 의심이 있을 때</li>
  <li>외상으로 치아 발육에 영향이 우려될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치아 나이는 유용한 지표이지만 단독 판단 기준은 아닙니다. 필요하면 방사선 검사가 동원되며, 개인차가 있어 전문가가 전반적 성장 상태와 함께 해석해야 합니다. 부모님은 치아 나이가 늦거나 빠르다고 지나치게 걱정하지 않으셔도 됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-age';
UPDATE dict_terms SET full_desc='<h3>공간 유지 장치란</h3>
<p>공간 유지 장치는 유치가 정상 시기보다 일찍 빠져 영구치가 날 자리가 줄어들 우려가 있을 때 그 공간을 물리적으로 지켜주는 치과 장치입니다. 주로 금속 밴드와 와이어로 만들어져 주변 치아의 이동을 막아 영구치가 제 위치에서 바르게 맹출하도록 돕습니다. 이음치과 소아 진료에서 흔히 사용합니다.</p>

<h3>원리 또는 특징</h3>
<p>빠진 유치 쪽으로 이웃 치아가 앞쪽으로 이동(근심 이동)하면 영구치의 공간이 부족해지므로, 장치가 그 이동을 차단해 치열 길이를 보존합니다. 형태는 고정식(밴드-루프, 링구얼 홀딩 아치, Nance)과 가철식이 있으며, 시술은 비교적 간단하고 정기 점검이 필요합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>유치가 영구치 맹출 전 조기에 상실된 경우</li>
  <li>주요 유치(특히 유구치·어금니) 상실로 공간 손실 위험이 큰 경우</li>
  <li>향후 교정치료 전까지 공간을 유지해야 할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치아와 잇몸 위생을 잘 관리하고 정기 검진으로 고정 상태를 확인해야 합니다. 장치가 느슨해지거나 파손되면 교체나 수리가 필요하고, 주변에 충치나 잇몸염이 생기지 않도록 주의해야 합니다. 영구치가 충분히 맹출하면 장치를 제거하거나 이후 교정 계획을 결정합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='space-maintainer';
UPDATE dict_terms SET full_desc='<h3>치면 착색 검사란</h3>
<p>치면 착색 검사는 아이의 치아에 붙은 치태(플라그)를 착색제로 눈에 보이게 하는 검사입니다. 빨간색·파란색 알약이나 액체를 이용해 칫솔이 닿지 않은 부분을 색으로 표시함으로써 부모와 아이가 문제 부위를 바로 확인하고 양치 습관을 개선할 수 있도록 돕습니다. 이음치과에서도 교육 목적으로 자주 사용합니다.</p>

<h3>원리 또는 특징</h3>
<p>착색제는 치태의 성분에 달라붙어 색소가 남아 보이게 합니다. 색은 일시적이며 물로 헹구거나 양치하면 대부분 없어집니다. 타액으로 희석되지 않으면 입술·옷에 묻을 수 있어 주의가 필요하며, 소아에게 안전한 약제가 사용됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>아이의 양치 습관을 교육할 때(올바른 칫솔질 지도)</li>
  <li>충치 위험이 높은 부위(어금니 고랑, 치아 사이) 확인할 때</li>
  <li>교정 장치 착용으로 칫솔질이 어려운 경우</li>
  <li>구강 위생 상태를 정기적으로 점검할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>검사는 간단하고 통증이 없지만 착색제가 혀·입술·옷에 묻을 수 있으니 보호가 필요합니다. 착색 결과는 교육 목적이며, 색이 보인다고 해서 즉시 치료해야 하는 것은 아닙니다. 자주 반복해 양치법을 교정하면 충치 예방에 도움이 됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='disclosing-test';
UPDATE dict_terms SET full_desc='<h3>수복물 탈락이란</h3>
<p>수복물 탈락은 어린이의 충전물이나 크라운 등이 입안에서 분리되어 빠지는 상태입니다. 레진, 인레이, 스테인리스 스틸 크라운(SSC) 등 원래 붙어 있어야 할 수복물이 접착력 저하, 2차 우식, 강한 교합력이나 행동 문제 등으로 떨어질 수 있으며, 방치하면 통증이나 추가 손상이 생길 수 있어 조치가 필요합니다.</p>

<h3>원리 또는 특징</h3>
<p>수복물은 접착제와 치아 구조의 결합으로 유지됩니다. 접착면의 습기·오염, 기존 우식의 진행, 씹는 힘(교합) 과다, 임시 수복물의 취약성 등으로 유지력이 약해져 탈락합니다. 유치에서는 자연 유실과 혼동될 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>레진 충전물이 씹힘으로 깨지거나 빠진 경우</li>
  <li>스테인리스 스틸 크라운이 빠지는 경우</li>
  <li>충전물 가장자리에서 2차 우식이 진행된 경우</li>
  <li>치아가 자연스럽게 흔들려서 수복물이 떨어지는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>빠진 수복물은 가능한 빨리 치과에서 재접착하거나 재제작해야 합니다. 떨어진 조각은 깨끗한 지퍼백에 보관해 가져오고, 집에서 무리하게 붙이려 하지 마세요. 통증·과민이 있거나 유치는 남은 교환 시기 등을 고려해 이음치과 등 전문의와 상담하면 적절한 치료 계획을 세울 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='restoration-dislodgement';
UPDATE dict_terms SET full_desc='<p>구호흡은 코로 숨 쉬기보다 입으로 주로 호흡하는 습관을 말합니다. 어린이에게서는 비염이나 아데노이드 비대 같은 코 막힘이 원인인 경우가 많고, 습관화되면 얼굴 골격 발달과 치아 배열에 영향을 줍니다. 조기 발견과 원인 치료가 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>정상적으로 코는 공기를 따뜻하게 하고 거르는 역할을 합니다. 코가 막히면 저항이 높아져 입으로 숨을 쉬게 되고, 입을 벌리고 오래 호흡하면 혀 위치와 얼굴 근육의 균형이 바뀌어 상악(윗턱) 협착, 개방교합 등 악화가 생길 수 있습니다. 잠잘 때 입을 벌리거나 코골이가 동반되는 경우가 흔합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>알레르기성 비염이나 만성 코막힘</li>
  <li>아데노이드(편도) 비대나 편도 비대</li>
  <li>상악 협착·부정교합의 초기 징후</li>
  <li>수면 중 코골이·주간 피로 등 호흡장애 증상</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>장기간 방치하면 안면 발육과 교합에 영구적 영향을 줄 수 있어 이음치과 등 치과·이비인후과와 협진으로 원인을 찾는 것이 좋습니다. 치료는 약물·알레르기 관리, 필요 시 아데노이드 제거, 구강근 기능 치료(마이오펑셔널)나 교정치료를 포함합니다. 구강건조로 충치 위험이 높아져 구강위생과 수분 공급을 신경 써야 합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='mouth-breathing';
UPDATE dict_terms SET full_desc='<p>절개 배농은 잇몸이나 구강연조직에 고름(농양)이 찼을 때, 작은 절개를 통해 고름을 빼내어 압력과 통증을 낮추고 감염을 조절하는 응급 처치입니다. 보통 국소마취로 시행하며 필요하면 배액관을 넣거나 배양 검사를 해 적합한 항생제를 결정합니다. 빠른 처치가 주변 조직 손상과 전신 합병증을 줄입니다.</p>

<h3>원리 또는 특징</h3>
<p>농양 내부의 고름을 배출하면 압력이 감소하고 통증이 경감되며, 세균 수가 줄어들어 항생제 효과가 좋아집니다. 시술은 간단하지만, 원인 치아의 치료(근관치료·발치)나 추가 항생제 처방이 동시에 필요할 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치근단 농양이나 치주농양으로 인한 국소 부종과 통증</li>
  <li>입술·턱·혀 등 연조직에 국소 농양이 형성된 경우</li>
  <li>발열·림프절 종대 또는 삼키기·호흡 곤란이 동반된 급성 감염</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 후에는 처방된 항생제와 진통제를 복용하고, 처방대로 내원해 배액 상태와 원인치료 여부를 확인받아야 합니다. 재발하거나 증상이 악화되면 즉시 진료가 필요하며, 이음치과와 같은 의료기관에서 신속한 평가를 받는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='incision-drainage';
UPDATE dict_terms SET full_desc='<p>이식 수술은 본인의 다른 위치에 있는 치아를 뽑아 결손 부위에 옮겨 심는 치료입니다. 주로 불필요한 사랑니나 맹출하지 않은 치아를 이용해 빠진 치아를 자연 치아로 대신하는 방법으로, 성공하면 바로 씹는 기능과 잇몸·치조골의 건강을 오래 유지할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치아를 옮길 때 치근과 주위의 치주인대가 보존되면 자연스러운 부착과 감각 회복이 가능합니다. 특히 뿌리 형성 단계가 적절한 젊은 환자에서 예후가 좋고, 이식 중 조직 손상 최소화와 빠른 재식이 중요합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>사랑니 등 사용할 수 있는 치아가 있어 결손 치아를 대체할 때</li>
  <li>성장이 남아 있어 임플란트 적합하지 않을 때</li>
  <li>임플란트나 가교를 피하고 자연 치아 회복을 원할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>성공률은 환자 연령, 기증치아의 뿌리 상태, 수술 시간과 처치에 따라 달라집니다. 뿌리가 완성된 치아는 신경치료가 필요할 수 있고, 실패 시 치아 흡수나 유합(ankylosis)이 발생할 수 있습니다. 이음치과와 같은 전문의와 충분한 검사·계획 후 결정하는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='autotransplantation';
UPDATE dict_terms SET full_desc='<p>구강 상악동 누공은 윗어금니 발치 등으로 입안과 위턱 뒤편의 빈 공간인 상악동이 비정상적으로 연결된 상태를 말합니다. 이로 인해 음식물이나 액체가 코 쪽으로 넘어가거나 공기가 통하면서 불편함이 생기고, 장기적으로는 부비동염(축농증)이 반복될 수 있습니다.</p>
<h3>원리 또는 특징</h3>
<p>위턱 어금니의 뿌리가 상악동과 가까워 발치 과정에서 상악동 점막이 손상되면 구멍이 생깁니다. 작은 결손은 수주 내 자연 치유될 수 있지만, 결손이 크거나 점막 손상이 심하면 자가치유가 어려워 지속적인 누공이 됩니다.</p>
<h3>관련 상황</h3>
<ul>
<li>상악 어금니 발치 직후</li>
<li>발치 후 코로 음식물이 넘어가는 경우</li>
<li>반복되는 부비동염이나 만성 콧물</li>
</ul>
<h3>알아두면 좋은 점</h3>
<p>보통 1~2주 이내 증상이 개선되는지 관찰하지만, 2주 이상 지속되거나 염증·증상이 있으면 수술적 폐쇄가 필요합니다. 폐쇄는 국소 조직을 이용한 봉합이나 이동술로 이루어지며, 정밀검사 후 적절한 치료계획을 세우는 것이 중요합니다. 치료는 이음치과 같은 구강외과에서 시행할 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='oroantral-fistula';
UPDATE dict_terms SET full_desc='<p>턱뼈 골절은 상악(위턱)이나 하악(아래턱)이 외상으로 금이 가거나 부러지는 상태로, 얼굴 부위 충격이 원인입니다. 통증·부기·출혈과 함께 이가 맞물리지 않는 교합 이상, 입 벌림 제한, 감각 이상이 나타날 수 있으며 진단과 치료 시 빠른 평가가 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>골절은 뼈가 외력에 의해 연속성이 깨지는 것으로, 위치와 형태에 따라 안정성에 차이가 납니다. 단순골절은 보존적 치료로 치유될 수 있으나, 분쇄·불안정 골절은 정복과 고정(플레이트·나사)을 통한 정렬이 필요합니다. 영상(파노라마X선, CT)으로 정확히 평가합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>교통사고·낙상·스포츠 충돌 등 강한 얼굴 외상</li>
  <li>부정교합·발음·저작 기능 저하가 동반될 때</li>
  <li>개방성 골절이나 출혈·기도문제가 의심되는 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기 처치와 정확한 영상검사가 치료 결과를 좌우합니다. 감염·신경손상·부정유합 같은 합병증이 있을 수 있어 전문 구강외과의 평가가 필요합니다. 이음치과 구강외과에서는 상태에 따라 보존적 치료부터 수술적 고정까지 맞춤 치료를 제공합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='jaw-fracture';
UPDATE dict_terms SET full_desc='<p>하치조 신경은 아래턱뼈(하악골) 속을 지나며 아래 치아와 아랫입술·턱 피부의 감각을 전달하는 주요 감각신경입니다. 치과 치료에서 위치가 가까워 발치나 임플란트, 국소마취 시 신경 손상 여부를 항상 고려해야 합니다. 일시적 저림부터 드물게 영구 감각소실이 나타날 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>이 신경은 하악관이라는 뼈 속 통로를 통해 앞쪽으로 이동하다가 정신공을 통해 피부로 분지됩니다. 치아의 통증·촉각을 뇌로 전달하며, 국소마취(하치조 신경차단)를 통해 아래턱 전체 감각을 차단할 수 있습니다. 해부학적 위치 차이로 개인별 위험도가 달라집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>사랑니(제3대구치) 발치 시 신경 근접으로 인한 손상 위험</li>
  <li>하악 임플란트 수술에서 드릴링 깊이·위치 관리 필요</li>
  <li>하치조 신경차단을 이용한 치과 수술 및 진통 조절</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 전 파노라마·CT로 신경 위치를 확인하면 안전성이 높아집니다. 수술 후 저림·감각이상 발생 시 조기 진료가 중요하며, 대부분은 시간이 지나 회복되지만 드물게 영구 손상이 남을 수 있습니다. 이음치과에서도 치료 전 위험과 대안을 충분히 설명드립니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='inferior-alveolar-nerve';
UPDATE dict_terms SET full_desc='<p>이신경은 하악(아래턱)에서 나오는 신경으로 혀 앞쪽 2/3의 촉각·온도·통증 같은 일반 감각을 담당합니다. 미각(맛)은 얼굴신경의 가지인 고실윤상신경(chorda tympani)이 이신경을 따라 함께 이동해 전달되므로 맛과 감각이 함께 영향을 받을 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>이신경은 삼차신경의 하악신경 분지로, 혀 점막의 감각을 전달합니다. 치과 치료 중 특히 하악 사랑니(매복사랑니) 발치나 국소마취 주사 위치에 가까워 손상될 위험이 있으며, 손상 시 감각저하·저림·미각 변화가 나타납니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>하악 사랑니(매복치) 발치 시</li>
  <li>악안면 수술이나 종양 절제 후</li>
  <li>구강 내 외상 또는 임플란트 시술 관련 손상</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>증상은 일시적일 수 있어 수주에서 수개월 내 호전되는 경우가 많지만, 지속되면 신경 평가 및 치료(약물, 신경치료 또는 외과적 재건)를 고려해야 합니다. 수술 전 위험 설명을 받고, 증상이 걱정되면 이음치과 같은 전문의에게 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='lingual-nerve';
UPDATE dict_terms SET full_desc='<h3>국소 마취란</h3>
<p>국소 마취는 치료가 필요한 치아나 잇몸 등 한정된 부위의 통증 감각만 선택적으로 차단해 시술 중 불편을 없애는 방법입니다. 리도카인 등 국소마취제를 주사로 투여하면 신경 신호 전달이 멈춰 환자는 의식은 유지한 채 해당 부위만 무감각해집니다.</p>

<h3>원리 또는 특징</h3>
<p>국소마취제는 신경세포의 나트륨 채널을 억제해 통증 신호가 전달되지 않도록 합니다. 에피네프린 같은 혈관수축제를 섞으면 약효 지속시간이 길어지고 출혈을 줄일 수 있습니다. 주입 방법은 잇몸에 직접 놓는 침투마취와 신경에 가까운 곳에 놓는 차단(블록)마취로 나뉩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>발치, 충전, 근관치료 등 일반 치과 치료</li>
  <li>임플란트, 낭종 제거 등 구강외과적 소수술</li>
  <li>국소적 통증 조절이나 봉합, 치주 치료 시</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>효과는 보통 몇 분 내 시작해 수십 분에서 몇 시간까지 지속됩니다. 무감각 상태에서는 씹거나 뜨거운 음식으로 입 안을 다칠 수 있으니 주의하세요. 드물게 알레르기, 어지러움, 일시적 감각 이상(저림)이 발생할 수 있으니 복용 중인 약, 심장질환, 항응고제 복용, 임신 여부 등은 반드시 알려주십시오. 이음치과에서는 환자 상태에 맞춰 약물과 용량을 조절해 안전하게 시행합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='local-anesthesia';
UPDATE dict_terms SET full_desc='<h3>의식 하 진정이란</h3>
<p>의식 하 진정은 약물을 사용해 불안과 통증 반응을 낮추되 환자가 스스로 눈을 뜨고 말할 수 있는 상태를 유지하게 하는 방법입니다. 구강외과에서 긴 시술이나 치과 공포증이 심한 분들에게 적용하며, 필요에 따라 정맥주사로 진정제를 투여하는 경우가 많습니다.</p>

<h3>원리 또는 특징</h3>
<p>진정제는 중추신경계의 활동을 억제해 긴장과 공포를 완화합니다. 호흡·심박수·산소포화도를 계속 관찰하며 투여량을 조절하므로 환자는 대체로 편안한 상태에서 의사와 의사소통이 가능합니다. 전신마취와 달리 완전한 무의식 상태로 가지 않습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>극심한 치과 공포증으로 일반진료가 어려운 경우</li>
  <li>발치·임플란트 등 장시간의 외과적 시술</li>
  <li>과거 진정 반응이 좋았거나 협조가 어려운 환자</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술 전 금식과 동반자 동행이 권장되며, 회복 후 일시적 졸림·메스꺼움이 생길 수 있습니다. 드물게 과도한 진정으로 호흡저하가 올 수 있어 경험 많은 팀과 모니터링이 필요합니다. 자세한 상담은 이음치과에서 안전하게 안내드립니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='conscious-sedation';
UPDATE dict_terms SET full_desc='<p><strong>근관장 측정기</strong>는 근관치료 중 금속 파일이 치아 뿌리 끝(근첨)에 어느 정도 도달했는지를 전기적 신호로 알려 주는 장비입니다. 방사선 촬영에만 의존하던 방식보다 실시간으로 길이를 확인할 수 있어 치료 정확도를 높이고 필요 방사선 횟수를 줄여 줍니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 내부의 파일과 환자 입안에 연결된 전극 사이 전기저항(또는 전도성) 변화를 측정해 파일 끝이 근첨에 가까워지면 장치가 이를 표시합니다. 디지털 화면과 소리 신호로 거리 정보를 주며 최근 기종은 오차 보정 기능이 있어 안정성이 향상되었습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>근관치료 중 정확한 길이 측정이 필요할 때</li>
  <li>뿌리 모양이 복잡하거나 강한 굴곡이 있을 때</li>
  <li>방사선 촬영을 제한해야 하는 상황(임신 등)에서 보조적으로</li>
  <li>치근 재치료 시 기존 자료와 비교하여 길이 확인할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>정확도가 높지만 단독으로만 의존하지 않고 방사선 영상과 함께 사용해야 안전합니다. 출혈이나 농성 분비물, 개방근첨 등으로 오차가 생길 수 있고, 의료기기(심박조율기 등)를 사용 중이면 시술 전 알려 주세요. 이음치과에서도 환자 상태에 맞춰 적절히 활용합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='apex-locator';
UPDATE dict_terms SET full_desc='<h3>고배율 루페란</h3>
<p>고배율 루페는 치과의사가 착용하는 광학 확대안경으로, 눈으로 보기 어려운 치아의 미세 구조를 2.5배에서 6배까지 확대해 보여줍니다. 확대된 시야는 수복물의 맞물림, 근관치료의 세밀한 작업, 미세 균열 확인 등에서 시술 정확도를 높이고 술자의 자세를 안정시켜 피로를 줄여줍니다.</p>

<h3>원리 또는 특징</h3>
<p>두 눈으로 보는 쌍안(바이노큘러) 광학계를 사용해 입체감과 깊이감을 유지하며, 배율이 높을수록 시야는 좁아지지만 세부 관찰력이 좋아집니다. 작업거리를 일정하게 유지하도록 설계되고, 필요하면 LED 광원이 결합되어 어두운 구강 내부를 밝힙니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>정밀한 수복(충전물 경계 확인)이나 보철물 조정</li>
  <li>근관치료(치수강 내 미세관 확인 및 기구 조작)</li>
  <li>미세 외과적 처치나 치아 균열·외상 진단</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>루페는 개인별 작업거리와 시력에 맞춰 조정해야 효과적이며 초기 적응기간이 필요합니다. 배율 선택과 품질에 따라 비용과 사용감이 달라질 수 있으니 담당 치과의와 상의하세요. 이음치과에서도 필요한 시술에 맞춰 적용하고 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-loupes';
UPDATE dict_terms SET full_desc='<p>치과용 수술 현미경은 작은 치아 구조를 크게 확대해 보여주는 기구로, 육안으로 확인하기 어려운 미세한 근관, 균열, 파절선을 정밀하게 관찰해 치료 정확도를 높입니다. 강한 조명과 입체 영상으로 깊이와 미세 구조를 구분할 수 있어 복잡한 근관치료나 치근단 수술 시에 특히 유용합니다. 이음치과에서도 활용합니다.</p>

<h3>원리 또는 특징</h3>
<p>광학 렌즈와 조명이 결합되어 대상 부위를 최대 약 25배까지 확대합니다. 입체시야로 깊이 인식이 가능하고, 카메라 연결로 치료 영상을 기록하거나 모니터링할 수 있어 정밀 제거·봉합·수복을 돕습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>복잡하거나 재치료가 필요한 근관치료</li>
  <li>치근단 수술(루트앤드수술) 시 병변 탐지</li>
  <li>치아의 미세 균열·파절선 확인</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>현미경 사용은 치료 성공률을 높이지만 검사·치료 시간이 다소 길어질 수 있고, 비용이 추가되는 경우가 있습니다. 숙련된 술자의 경험이 중요하며 필요 시 치료 계획에 반영됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-microscope';
UPDATE dict_terms SET full_desc='<p>오토클레이브는 121~134°C의 고온 포화증기를 고압으로 가해 치과 기구의 표면과 포장 내부까지 침투시켜 모든 미생물과 포자를 사멸시키는 멸균 장비입니다. 환자마다 재사용 기구를 안전한 상태로 만드는 감염관리의 기본 장치로 사용됩니다.</p>

<h3>원리 또는 특징</h3>
<p>고온·고압의 포화증기가 단백질을 변성시켜 미생물과 내열성 포자까지 제거합니다. 가열·포화·배기·건조의 사이클을 거치며, 포장한 상태로 멸균해 보관이 가능합니다. 성능 확인을 위해 생물학적 지시기와 화학적 지시기를 함께 사용합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>스케일링·발치 등 환자마다 사용하는 금속 기구의 멸균</li>
  <li>수술용 기구나 임플란트 삽입 전 멸균 확인</li>
  <li>열에 약한 플라스틱·전자장비는 대체 소독법 적용</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>멸균 봉투의 지시테이프나 멸균일자가 표기되어 있으면 처리 상태를 확인할 수 있습니다. 모든 기구가 오토클레이브에 적합한 것은 아니므로 분류와 포장·주기적 검증이 중요합니다. 이음치과와 같은 기관에서는 정기적 성능검사와 기록으로 안전하게 운영합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='autoclave';
UPDATE dict_terms SET full_desc='<p>에어샤워는 진료실이나 수술실에 들어가기 전에 고속의 깨끗한 공기를 쏘아 옷과 노출된 피부에 붙은 먼지나 미세입자를 떨어뜨리는 장비입니다. 공기 흐름과 여과를 이용해 외부 오염원을 줄여 멸균 환경을 보조하며, 이음치과에서는 수술실 감염 관리를 위해 운영합니다.</p>

<h3>원리 또는 특징</h3>
<p>노즐에서 나오는 고압·고속 공기가 표면에 붙은 입자를 떼어내고, 배기 쪽의 필터(대개 HEPA)를 통해 회수합니다. 장비는 짧은 시간(수초~수십초) 내 작동하며, 독립 부스형이나 출입구형으로 설치됩니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>수술실·임플란트 시술 등 무균 환경이 중요한 경우</li>
  <li>면역저하 환자 진료 전 감염 위험을 낮추려는 경우</li>
  <li>병원 출입 시 외부 오염물 유입을 최소화할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>에어샤워는 오염을 줄이는 보조 수단으로, 손위생·개인보호구·도구 멸균을 대체하지 않습니다. 기름기나 피부에 고정된 미생물은 제거되지 않을 수 있고, 장비는 정기 필터교체와 청소가 필요합니다. 이용 시 얇은 소지품이나 액세서리는 미리 제거하면 효과적입니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='air-shower';
UPDATE dict_terms SET full_desc='<p>디지털 파노라마는 필름 대신 전자센서를 이용해 한 번에 상·하악과 주변 구조를 넓게 촬영하는 영상 검사입니다. 전체 치아와 턱뼈, 관절과 부비동 일부를 한 장의 고해상도 영상으로 얻어 진단 시간을 줄이고 치료 계획을 세우기 쉽게 해줍니다.</p>

<h3>원리 또는 특징</h3>
<p>촬영 장비가 환자 주변을 회전하면서 디지털 센서로 연속 이미지를 얻어 하나의 파노라마 영상으로 합성합니다. 필름에 비해 즉시 확인 가능한 고화질 영상을 제공하고, 영상 보정·확대가 용이합니다. 방사선량은 장비와 설정에 따라 기존보다 약 50~80% 줄어 환자 부담이 적습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>임플란트 식립 전 골격·치아 위치 파악</li>
  <li>사랑니(매복치) 및 발치 계획</li>
  <li>교정 치료 초기 진단 및 추적 관찰</li>
  <li>외상이나 턱관절 이상 평가 시 1차 스크리닝</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>디지털 파노라마는 유용한 전반적 검사지만 작은 충치나 치근의 세밀한 병변은 놓일 수 있어 추가 근접 방사선이나 CBCT가 필요할 수 있습니다. 임신 초기에는 불필요한 촬영을 피하는 것이 원칙이며, 촬영 전에 담당 의사와 상담하세요. 이음치과에서도 환자 기록 관리와 영상 공유가 편리하게 이루어집니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='digital-panoramic';
UPDATE dict_terms SET full_desc='<p>구강 카메라는 손에 쥘 만큼 작은 카메라를 입 안에 넣어 치아와 잇몸을 확대 촬영하는 장비입니다. 진료 중 모니터로 영상을 보며 문제 부위를 환자에게 직접 보여주고, 사진·동영상으로 기록해 치료 과정과 결과를 비교하는 데 유용합니다.</p>

<h3>원리 또는 특징</h3>
<p>헤드에 내장된 렌즈와 LED 조명이 좁은 구강 내에서 고해상도 영상을 만들어 실시간으로 전송합니다. 확대율이 높아 미세한 균열이나 초기 우식, 보철물의 경계 등을 확인할 수 있으며 검사 자체는 비침습적이고 불편함이 적습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>초기 충치나 미세 균열 의심 시</li>
  <li>충전물·크라운 등 보철물의 가장자리 상태 점검</li>
  <li>치주 상태(잇몸 염증, 치석 등)를 환자에게 설명할 때</li>
  <li>치료 전후 비교 및 진료 기록 보관</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>촬영은 짧고 통증이 거의 없지만, 잇몸 아래 깊은 병변은 관찰이 제한될 수 있습니다. 촬영 영상은 진료기록으로 보관되며 비용이나 보험 적용 여부는 의료기관별로 다를 수 있으니 담당 의료진과 상의하세요. 이음치과와 같은 곳에서 환자 교육용으로 자주 사용됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='intraoral-camera';
UPDATE dict_terms SET full_desc='<p>석션은 진료 중 입안에 고이는 물, 타액, 혈액과 치료로 생기는 분진·에어로졸을 빨아들여 치과의사가 환부를 잘 보고 시술을 편안하게 받을 수 있게 돕는 장치입니다. 흡입으로 구강을 건조하게 유지해 디지털 인상 채득이나 수복물 접착 같은 정밀한 과정에서 정확도를 높여 줍니다.</p>

<h3>원리 또는 특징</h3>
<p>작은 관 끝의 팁으로 음압을 만들어 액체와 미세입자를 빨아들입니다. 일반적으로 흡입력 큰 고용량 석션(HVE)과 저유량 침흡입기(살리바 이젝터)로 나뉘며, 팁은 멸균 처리하거나 <strong>일회용</strong>을 사용해 감염을 예방합니다. 소음이 발생할 수 있으며 조절이 가능합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>레진 수복이나 인레이 시 건조하고 깨끗한 작업 환경이 필요할 때</li>
  <li>스케일링·초음파 치료로 에어로졸이 많이 발생할 때</li>
  <li>발치·임플란트 등 외과적 술기에서 출혈과 잔여물을 제거할 때</li>
  <li>디지털 스캔 등 정밀 인상 채득 시 시야 확보가 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>석션 소리가 크거나 약간의 불편감이 있을 수 있으나 정상입니다. 구역감이 있다면 치과에 알려 조절할 수 있고, 석션만으로 모든 감염원을 차단하지 못하므로 고무댐·공기정화 등 다른 보호장치와 함께 사용됩니다. 이음치과에서는 팁 멸균과 일회용 사용으로 안전 관리를 시행합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-suction';
UPDATE dict_terms SET full_desc='<p><strong>초음파 세척기</strong>는 고주파의 음파를 액체에 전달해 미세한 기포를 만들고 터뜨리는 힘으로 치과 기구 표면과 틈새에 낀 혈액·조직·먼지 등을 떼어내는 장비입니다. 멸균(멸균기) 전에 기구를 깨끗하게 만들어 소독·멸균 효과를 높이는 전처리 과정으로 널리 쓰입니다.</p>

<h3>원리 또는 특징</h3>
<p>초음파가 물속에서 미세기포를 만들고 순간 붕괴되며 발생하는 국소적인 소용돌이(공동현상)로 오염물을 기계적으로 분리합니다. 브러시로 닦기 어려운 미세 틈과 연결부에 유효하며, 세제와 함께 사용하면 더 잘 제거됩니다. 단독으로는 멸균 기능이 없습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>시술 직후 혈액·조직 잔유물이 있는 손기구 전처리</li>
  <li>보철물·수복물의 접착면이나 미세 잔여물 제거</li>
  <li>내부 관이 복잡한 기구(예: 소형 핸드피스 분해부) 세척</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초음파 세척은 효과적인 전처리지만 멸균을 대신하지 않습니다. 세척 후 기구를 건조·검사한 뒤 반드시 멸균해야 안전합니다. 제조사 권장 세제·농도와 주기적 유지관리가 중요하며, 이음치과에서도 표준 지침에 따라 사용하고 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='ultrasonic-cleaner';
UPDATE dict_terms SET full_desc='<p><strong>PMMA(폴리메틸메타크릴레이트)</strong>는 임시 보철물에 주로 쓰이는 아크릴 계열 수지입니다. 가공과 수리가 쉬워 임시 크라운, 의치, 교정 장치 등에서 형태와 심미를 빠르게 회복시키는 재료로 널리 사용됩니다. CAD/CAM 블록으로 제작하면 정밀도와 일관된 품질을 얻을 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>PMMA는 단량체가 중합하여 단단한 고분자 구조를 만들며 표면 광택과 색 조절이 용이합니다. 금속이나 도재보다 강도는 낮지만 가벼워 착용감이 좋고 현장에서 빠르게 수리·조정할 수 있습니다. 블록 가공 시 잔류 단량체가 줄어 안전성이 개선됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>임시 크라운·브릿지로 치아 형태와 기능을 보호할 때</li>
  <li>최종 보철 전 임시 의치나 형태 확인이 필요할 때</li>
  <li>교정용 유지장치·스플린트처럼 조정이 필요한 장치를 만들 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>PMMA는 영구 보철물 대체용이 아니어서 시간이 지나며 변색·마모·파절이 생길 수 있습니다. 아크릴에 민감한 분은 알레르기 반응이 나타날 수 있으니 병력 상담이 필요합니다. CAD/CAM 제작물은 정밀도와 안전성이 높아 선택지로 고려되며, 자세한 상담은 이음치과에서 도와드립니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='pmma';
UPDATE dict_terms SET full_desc='<h3>차폐막이란 무엇인가요?</h3>
<p>차폐막은 골이식과 GBR(유도골재생술)을 할 때 뼈가 자라야 할 공간을 확보하고 잇몸(연조직)이 그 공간으로 들어오는 것을 막아 주는 생체친화적 재료입니다. 막이 있으면 뼈를 만드는 세포가 자리를 잡아 안정적으로 골조직이 재생되도록 돕습니다.</p>

<h3>원리 또는 특징</h3>
<p>원리는 ‘선택적 세포 재생’입니다. 빠르게 자라는 연조직을 차단해 느리게 증식하는 골세포가 우선 자리잡게 하고, 흡수성(콜라겐 등)과 비흡수성(PTFE·티타늄 보강막 등) 제품이 있어 상황에 따라 선택합니다. 고정용 핀이나 봉합으로 안정화합니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>임플란트 식립 전 치조골 모양을 개선해야 할 때(뼈이식과 병행)</li>
  <li>발치 후 소켓 보존으로 향후 임플란트 계획 시</li>
  <li>골결손(뼈함몰)이나 상악동 거상술 등 뼈를 늘려야 할 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>비흡수성 막은 제거를 위해 추가 수술이 필요할 수 있고, 막 노출 시 감염·치유지연 위험이 있습니다. 적절한 재료 선택과 구강위생, 정기 관찰이 중요하며, 치료 계획은 환자 상태에 맞춰 이음치과 등 전문의와 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='barrier-membrane';
UPDATE dict_terms SET full_desc='<h3>이종골이란 무엇인가요?</h3>
<p>이종골은 주로 소에서 채취한 뼈를 고온·화학처리해 유기물을 제거하고 무기질 골격만 남긴 골이식재입니다. 환자 자신의 뼈를 떼어내는 수고와 통증을 줄여주며 임플란트 주변 뼈를 보충하거나 빈 공간을 메우는 데 사용됩니다. 이음치과에서도 골결손 회복을 위해 자주 쓰이는 재료입니다.</p>

<h3>원리 또는 특징</h3>
<p>가공된 골은 골형성 유도보다는 뼈가 자라 들어갈 수 있는 ''골전도성(osteoconductive)'' 지지체로 작용합니다. 비교적 서서히 흡수되며, 그 자리를 따라 환자 자신의 뼈가 채워져 안정된 구조를 만듭니다. 처리 과정으로 항원성은 낮아지지만 완전한 골전환에는 시간이 필요합니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>임플란트 식립 전·후의 골 부족 부위 보강(동시 또는 지연 보철)</li>
  <li>상악동 거상술(부비동 수술) 시 골이식</li>
  <li>발치 후 빈 소켓(치조와) 보존</li>
  <li>치주 수술에서 뼈 결손 회복이 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>장점은 추가 수술 없이 사용 가능하고 수급이 용이하다는 것입니다. 단점은 자가골보다 골전환 속도가 느리고 일부 잔존물이 영상에서 남을 수 있다는 점입니다. 감염·면역 반응 가능성은 매우 낮지만 완전히 배제할 수 없어 시술 전 장단점과 대체재(자가골·동종골·합성골)를 의사와 상의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='xenograft';
UPDATE dict_terms SET full_desc='<p>합성골은 사람 뼈 대신 인공적으로 만든 골이식재로, β‑TCP(β인산삼칼슘)나 하이드록시아파타이트 같은 무기성분으로 제조됩니다. 임플란트 식립이나 뼈 결손 부위에 채워 골의 틀을 제공해 주변 자연골이 자라 들어가도록 돕는 보조재 역할을 합니다.</p>

<h3>원리 또는 특징</h3>
<p>주로 골전도성(osteoconductive) 재료로 작용해 뼈가 붙을 수 있는 지지체를 만듭니다. 멸균된 인공재료라 감염 위험이 비교적 낮고 공급이 안정적입니다. 소재에 따라 흡수 속도와 잔존 기간이 달라 장기간 잔류하는 제품도 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>임플란트 식립 전 치조골 부족 보강</li>
  <li>발치 후 소켓 보존</li>
  <li>상악동 거상술(상악동막 올림) 시 골충전</li>
  <li>치조골 결손이나 골증가가 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>합성골은 자가골처럼 빠르게 완전히 대체되지는 않을 수 있어 경우에 따라 자가골이나 기타 재료와 병용합니다. 드물게 이물반응이나 치유 지연이 발생할 수 있으므로 환자 상태에 맞는 재료 선택과 추적 관찰이 중요합니다. 자세한 평가는 이음치과에서 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='alloplast';
UPDATE dict_terms SET full_desc='<h3>핵심 설명</h3>
<p><strong>실러</strong>는 근관치료에서 거타퍼차와 함께 쓰여 치아 뿌리 속을 완전히 막아주는 충전 보조재입니다. 근관벽과 거타퍼차 사이에 남는 아주 작은 틈까지 채워 세균 재침투를 막고, 충전재가 안정적으로 자리하도록 도와줍니다.</p>

<h3>원리 또는 특징</h3>
<p>실러는 흐름성이 좋아 미세한 공간으로 침투해 밀봉을 완성합니다. 재료별로 특징이 다른데, 아연옥시드-유제놀계는 수축이 적고, 레진계는 접착성이 좋으며, 바이오세라믹계는 생체적합성과 봉쇄력이 우수합니다. 방사선 불투명성과 세팅시간, 항균성도 제품마다 다릅니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>근관세척·성형 후 최종 충전(거타퍼차와 병용)</li>
  <li>복잡한 측지관이나 미세균열을 보완해야 할 때</li>
  <li>근관재치료 시 기존 틈새를 재밀봉할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>실러는 적절한 양과 종류 선택이 중요합니다. 과량이 뿌리 끝으로 흘러나가면 염증을 유발할 수 있고, 유제놀 성분에 민감한 경우 알레르기나 변색이 생길 수 있습니다. 재료별 장단점이 있으니 치과의사가 환자 상태에 맞춰 선택하며, 이음치과에서도 환자 특성에 맞는 실러를 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='sealer';
UPDATE dict_terms SET full_desc='<h3>교정용 미니 스크류란</h3>
<p>교정용 미니 스크류는 작은 티타늄 나사로 잇몸뼈(치조골)에 삽입해 교정 장치가 기대기 어려운 부위에 안정된 고정점을 만들어 주는 장치입니다. 치아를 움직이는 동안 뼈에 직접 고정되어 정확한 방향으로 힘을 전달하고, 치료가 끝나면 비교적 간단히 제거할 수 있습니다. 이음치과에서도 사용합니다.</p>

<h3>원리 또는 특징</h3>
<p>작은 나사를 잇몸뼈에 삽입하면 치아 대신 뼈가 ''고정원'' 역할을 해 상대 치아만 이동하게 합니다. 대부분 티타늄 재질로 생체적합성이 좋고 국소마취 하에 시술하며 즉시 힘을 걸 수 있습니다. 크기와 위치에 따라 성공률과 유지기간이 달라질 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>개방교합(어금니만 닿는 문제) 등 복잡한 교합 교정이 필요할 때</li>
  <li>어금니 이동(원심 이동)이나 공간 폐쇄를 정확히 조절해야 할 때</li>
  <li>중간선 교정이나 국소적인 치아 보정으로 일반 고정원으로 부족할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>시술은 비교적 짧고 국소마취로 진행되며 초기 불편감과 염증 위험이 있으므로 구강 위생을 철저히 해야 합니다. 드물게 느슨해지거나 신경·치근과 근접할 수 있어 경험 있는 의사가 위치를 계획해야 합니다. 제거는 간단하며 작은 흉터가 남아도 대체로 빠르게 회복됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='ortho-miniscrew';
UPDATE dict_terms SET full_desc='<h3>프라이머란 무엇인가요?</h3>
<p>프라이머는 에칭으로 거칠어진 치아 표면에 얇게 바르는 전처리액으로, 본딩제(접착제)가 치아 조직 속으로 잘 스며들게 도와 레진 수복의 접착력을 높입니다. 액체 형태로 빠르게 증발하는 용매와 친수성 단량체를 포함해 얇은 층을 만들고, 적절히 건조한 뒤 본딩제를 적용합니다. 이음치과에서 흔히 사용하는 과정입니다.</p>

<h3>원리 또는 특징</h3>
<p>프라이머는 떼어낸 법랑질·상아질 표면의 미세공에 스며들어 콜라겐 섬유와 상호작용하고, 수분을 어느 정도 제어해 본딩제가 깊이 침투하도록 돕습니다. 보통 용매(알코올·아세톤 등)와 친수성 단량체(예: HEMA, MDP 계열 등)가 함께 있어 얇게 펴 발리고 공기 건조로 균일한 층을 만듭니다.</p>

<h3>언제 필요한가 / 관련 상황</h3>
<ul>
  <li>레진(합성수지) 충전물이나 인레이·온레이 접착 시</li>
  <li>치수가 드러나지 않은 상아질이 노출된 경우의 접착 강화</li>
  <li>치아 표면 실란트 또는 얇은 라미네이트 부착 전처리</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>프라이머는 본딩제의 보조물질로, 단독으로는 충분한 접착을 기대하기 어렵습니다. 제품 간 상호호환성이 있어 제조사 지침을 따르는 것이 중요하며, 과다 도포나 불충분한 건조는 접착력 저하나 감작성 위험을 높일 수 있습니다. 궁금하면 담당 치과의사에게 문의하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='primer';
UPDATE dict_terms SET full_desc='<p>구강 위생은 칫솔질·치실·가글 등으로 입안의 플라크(세균막)와 음식 찌꺼기를 제거해 치아와 잇몸, 혀를 건강하게 유지하는 일상 관리입니다. 꾸준한 관리로 충치·치주질환·구취 위험을 낮추고 전신 건강에 도움이 될 수 있습니다. 이음치과에서 권하는 기본 습관을 바탕으로 쉽게 실천할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>주요 원리는 물리적 제거와 화학적 억제입니다. 칫솔과 치실로 플라크를 제거하고 불소치약이나 항균 가글로 세균 활동을 억제합니다. 치아 배열·보철물 여부에 따라 도구와 방법을 조정해야 효과적입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>아침·취침 전 및 식후 규칙적인 관리가 필요한 경우</li>
  <li>치아 사이에 음식물이 자주 끼는 사람</li>
  <li>잇몸 출혈·붓기나 지속적 구취가 있는 경우</li>
  <li>임신·당뇨 등 전신질환으로 구강관리가 중요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>칫솔질은 부드러운 칫솔로 2분 이상, 치실은 하루 1회 이상 권장합니다. 과도한 힘이나 거친 방법은 잇몸 손상과 치경부 마모를 초래할 수 있으니 치과 진단을 받아 개인에 맞는 도구와 방법을 선택하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='oral-hygiene';
UPDATE dict_terms SET full_desc='<h3>치실이란</h3>
<p>치실은 치아 사이의 좁은 틈을 통과해 칫솔이 닿지 않는 접촉면의 플라크와 음식물 찌꺼기를 제거하는 얇은 실입니다. 매일 적절히 사용하면 충치와 잇몸염 위험을 낮추는 데 도움이 되며, 왁스·비왁스·플로스테이프 등 상황에 맞는 여러 형태가 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>치실은 치아 사이의 치태를 물리적으로 떼어내는 도구로, 얇아 치아 접촉점을 통과하고 잇몸선 바로 아래까지 닿여 세균덩어리를 제거합니다. C자 모양으로 감싸듯 사용하면 잇몸을 손상시키지 않으면서 효과적이며, 교정기나 임플란트 주변은 전용 제품이 권장됩니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>치아 사이에 음식물이 자주 끼는 경우</li>
  <li>치태나 플라크 축적이 우려될 때</li>
  <li>교정 장치·임플란트 등 관리 보조가 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>처음엔 잇몸이 약간 출혈할 수 있으나 일주일 이상 지속되면 진료가 필요합니다. 힘으로 끌어당기지 말고 잇몸을 따라 부드럽게 사용하세요. 개인 치아 상태에 맞는 치실 종류와 정확한 사용법은 이음치과에서 상담받아 보세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-floss';
UPDATE dict_terms SET full_desc='<h3>치간 칫솔이란</h3>
<p>치간칫솔은치아사이좁은틈에낀플라그와음식물찌꺼기를효율적으로제거하는작은솔입니다.실처럼얇은철심에브러시모가둘러진모양으로,치실로닦기힘든넓은치간이나보철물주변에서더수월하게사용할수있습니다.일상적인양치에보조적으로쓰면충치와치주질환예방에도도움이됩니다.</p>

<h3>원리 또는 특징</h3>
<p>가늘고짧은모가치아사이에들어가서기계적마찰로플라그를제거합니다.여러가지두께(미크론단위)로나와적절한사이즈를선택해야하며,와이어심이있어형태유지가됩니다.재사용가능한제품과일회용제품이있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>치아사이가넓어치실로충분히닦이지않을때</li>
  <li>임플란트·브릿지·보철물주변관리</li>
  <li>교정장치착용중플라그제거가필요할때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>사이즈가맞지않으면치은손상을일으킬수있으니무리하게밀어넣지말고치과에서적정사이즈를상담받으세요.사용후물로씻어건조보관하고,치주질환이있다면전문의권고에따라사용방법을조정하는것이안전합니다.필요시이음치과에서도도움받을수있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='interdental-brush';
UPDATE dict_terms SET full_desc='<h3>전동 칫솔이란</h3>
<p>전동칫솔은 내장된 모터가 칫솔모를 빠르게 진동하거나 회전시켜 치아 표면과 잇몸 선에 붙은 플라크를 물리적으로 분리하는 구강관리기구입니다. 일정한 속도와 타이머, 압력센서 같은 보조기능으로 올바른 칫솔질 습관을 돕고, 사용법을 지키면 수동칫솔보다 세정 효과가 높아질 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>작동 원리는 칫솔모의 반복적인 진동·회전으로 플라크를 흔들어 떨어뜨리고 치면에 닿아 제거하는 것입니다. 소닉형은 고속 진동으로 액체 흐름을 만들어 틈새 세정을 도와주고, 회전·진동형은 직접적인 마찰로 표면을 닦습니다. 타이머·압력경보 등 안전장치가 있는 제품이 많습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>손목·손가락 힘이 약해 수동칫솔 사용이 어려운 경우</li>
  <li>교정장치·보철물이 있어 세정이 까다로운 경우</li>
  <li>치은염이나 플라크 관리가 필요한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>칫솔모는 2~3개월마다 교체하고, 너무 강한 압력은 잇몸 퇴축을 유발할 수 있으니 부드럽게 사용하세요. 전동칫솔은 치실을 대신하지 못하므로 치간청결도 병행해야 합니다. 제품별 헤드형과 진동 특성이 다르니 치과에서(이음치과 포함) 상담 후 선택하면 도움이 됩니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='electric-toothbrush';
UPDATE dict_terms SET full_desc='<p>교차 감염은 병원·치과 환경에서 한 사람에게서 다른 사람으로 병원체가 옮겨 가는 현상을 뜻합니다. 치과에서는 혈액·타액·오염된 기구나 표면, 시술 중 생기는 에어로졸이 매개가 되어 환자 간 또는 의료진과 환자 사이에 감염이 전달될 수 있습니다. 예방은 절차와 장비 관리가 핵심입니다.</p>

<h3>원리 또는 특징</h3>
<p>교차 감염은 직접접촉(타액·혈액), 간접접촉(오염된 기구·손), 비말·에어로졸 등의 경로로 일어납니다. 치과에서는 고속 핸드피스나 초음파 스케일러 사용 시 미세한 입자가 공기 중에 퍼져 감염 위험을 높입니다. 감염원은 증상이 없는 보균자일 수도 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>출혈이 있는 시술(발치·임플란트 등) 중 장비 접촉</li>
  <li>초음파·고속기구 사용으로 에어로졸이 발생할 때</li>
  <li>멸균·소독이 불충분한 기구나 표면이 공유될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>교차 감염은 멸균(오토클레이브), 일회용품 사용, 손위생, 장갑·마스크·보호안면 착용, 표면 소독과 환자 선별로 크게 줄일 수 있습니다. 이음치과를 포함한 대부분의 치과는 표준 예방지침을 따라 관리하며, 궁금하면 진료팀에게 멸균·소독 과정에 대해 문의하시길 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cross-infection';
UPDATE dict_terms SET full_desc='<h3>방사선 방호란</h3>
<p>치과에서 X선 촬영 시 환자와 의료진이 받는 방사선을 가능한 한 줄여 안전하게 검사하는 모든 절차를 말합니다. 불필요한 촬영을 피하고 보호장비와 최신 장비를 사용해 진단에 필요한 최소한의 선량만 받도록 관리하는 것이 핵심입니다.</p>

<h3>원리 또는 특징</h3>
<p>기본 원칙은 ALARA(As Low As Reasonably Achievable)로, 합리적으로 달성 가능한 수준까지 피폭을 낮추는 것입니다. 납 앞치마·갑상선 보호대 착용, 디지털 센서·직사각 콜리메이터 사용, 적절한 위치잡기와 노출시간 단축, 장비 정기 점검 등이 주요 방법입니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>충치·치근 감염 진단 등 정확한 진단이 필요할 때</li>
  <li>임플란트·발치 전 뼈 상태 확인 시</li>
  <li>정기검진 시 불필요한 중복 촬영을 줄여야 할 때</li>
  <li>임신 가능성이나 소아 환자 등 방사선 민감군의 관리가 필요할 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>치과 X선은 일반적으로 선량이 낮아 위험이 크지 않지만, 임신 사실은 미리 알리고 불필요한 촬영은 피하는 것이 좋습니다. 디지털 방사선과 보호장비 사용으로 노출을 크게 줄일 수 있으니 궁금한 점은 방문한 치과(예: 이음치과)에 문의해 안전수칙을 확인하세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='radiation-protection';
UPDATE dict_terms SET full_desc='<h3>치아 우식증이란</h3>
<p>치아 우식증은 일상적 표현의 충치로, 입안에 있는 세균이 음식물 속 당을 분해하며 만든 산이 치아의 단단한 층을 서서히 녹여 발생하는 감염성 질환입니다. 초기에는 흰색 반점과 민감도로 시작하고, 악화되면 구멍·통증·치수염으로 진행할 수 있어 진단과 치료가 중요합니다.</p>

<h3>원리 또는 특징</h3>
<p>치면에 붙은 플라크(세균막)가 당을 이용해 산을 만들면 에나멜의 무기질이 탈회되어 약해집니다. 탈회가 반복되면 회복 불가능한 공동(cavity)이 형성되며, 초기 단계는 불소·구강위생 개선으로 어느 정도 회복될 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>단 음식·간식 빈번 섭취로 산 노출이 잦을 때</li>
  <li>칫솔질 불량이나 플라크 관리가 안 될 때</li>
  <li>타액 분비 감소(구강건조증) 또는 치아 홈·균열이 깊을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>예방이 가장 중요하며 불소 사용, 규칙적 칫솔질, 식습관 개선, 정기검진으로 조기 발견 시 보존적 치료가 가능합니다. 진행되면 충전·근관치료·발치 등 침습적 치료가 필요할 수 있으니 이상이 느껴지면 이음치과 등 전문의에게 상담받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='dental-caries';
UPDATE dict_terms SET full_desc='<p>구취는 입에서 발생하는 불쾌한 냄새로, 대부분 구강내 세균이 단백질을 분해해 생긴 휘발성 유황화합물이 주된 원인입니다. 혀 표면의 설태나 치주질환, 충치, 구강건조 등으로 악화되며 적절한 구강관리와 치과치료로 호전되는 경우가 많습니다. 지속되면 이음치과에서 평가가 필요합니다.</p>

<h3>원리 또는 특징</h3>
<p>구강세균이 단백질을 분해하면서 황화수소·메틸메르캅탄 등 악취성 가스를 생성합니다. 혀 후면과 치주낭은 세균이 쌓이기 쉬운 곳이며, 타액 감소는 냄새를 더 심하게 만듭니다. 드물게 전신 질환이나 약물이 관련될 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
<li>혀 위에 끼는 설태</li>
<li>붓고 피가 나는 잇몸(치주질환)</li>
<li>입이 자주 마르는 경우</li>
<li>충치나 보철물 틈새에 음식물 잔류</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>양치질·혀 클리닝·치실 사용과 물 자주 마시기가 기본입니다. 구강청결제는 일시적 완화에 도움되지만 원인 치료가 우선이며, 호전되지 않으면 치과나 내과 검사가 필요합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='halitosis';
UPDATE dict_terms SET full_desc='<h3>설태란?</h3>
<p>설태는 혀 표면의 유두 사이에 세균, 음식 찌꺼기, 탈락한 세포 등이 쌓여 만든 막을 말합니다. 겉으로는 하얗거나 노랗게 보이지만 색과 양은 개인차가 있고, 구취의 흔한 원인이기도 합니다. 보통 위생 관리로 호전되지만 경우에 따라 추가 검사가 필요할 수 있습니다.</p>

<h3>원리 또는 특징</h3>
<p>혀 표면의 미세한 굴곡(유두)에 물질이 끼면서 미생물이 번식하기 쉽습니다. 침 분비량이 적거나 구강 청결이 부족하면 더 두껍게 쌓이며, 색깔은 음식·약물·세균 구성에 따라 달라집니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>입 냄새(구취)가 심할 때</li>
  <li>구강 위생이 좋지 않거나 식사 후 청결 관리가 어려울 때</li>
  <li>구강 건조증이나 수면 중 입을 벌리고 자는 경우</li>
  <li>흡연, 특정 약물 복용 후 설태가 증가한 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>매일 혀 클리너나 부드러운 칫솔로 뒤에서 앞으로 가볍게 닦아 제거하는 것이 도움이 됩니다. 과도한 세척은 혀 조직을 손상시킬 수 있으니 부드럽게 관리하세요. 색이 급격히 변하거나 통증·출혈이 동반되면 이음치과 등에서 검진받아 원인을 확인하는 것이 안전합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='tongue-coating';
UPDATE dict_terms SET full_desc='<h3>구순 포진이란</h3>
<p>구순 포진은 단순포진바이러스(주로 HSV-1)가 입술 가장자리나 입 주변 피부에 다시 활성화되어 작은 물집이 군집으로 생기는 질환입니다. 처음에는 따끔거림이나 가려움이 느껴지고, 수일 내에 물집이 터져 가피가 생기며 보통 1~2주 내에 회복됩니다.</p>

<h3>원리 또는 특징</h3>
<p>바이러스는 일단 신경절에 잠복했다가 피로나 스트레스, 자외선, 발열 등 유발인자에 의해 재활성화됩니다. 전염성이 있어 접촉으로 옮기며, 눈 등 다른 부위로 번질 수 있으므로 주의가 필요합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>처음 발생하거나 물집이 넓고 통증이 심할 때</li>
  <li>재발이 잦아 일상에 지장을 줄 때</li>
  <li>면역저하자, 눈주변에 생기거나 열이 동반될 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기 증상에 항바이러스제를 빨리 사용하면 경과를 줄일 수 있고, 물집이 마를 때까지 키스나 음식물 공유를 피하고 손 위생을 지키는 것이 중요합니다. 증상이 심하거나 오래가면 이음치과 등 전문의 진료를 받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='cold-sore';
UPDATE dict_terms SET full_desc='<h3>악관절이란</h3>
<p><strong>악관절(측두하악관절, TMJ)</strong>은 아래턱뼈와 머리뼈가 만나는 복합 관절로, 귀 앞쪽에 있으며 씹기·말하기·입 벌림과 닫힘 같은 모든 턱 운동을 조절합니다. 뼈 사이에 연골성 관절원반이 있어 충격을 흡수하고 양측이 함께 움직이도록 돕습니다.</p>

<h3>원리 또는 특징</h3>
<p>이 관절은 회전과 전위가 결합된 복합운동을 하며, 관절원반·인대·저작근의 협동으로 안정성을 유지합니다. 스트레스나 교합 이상, 외상으로 근육 긴장이나 원반의 위치 이상이 생기면 통증·소리·운동제한이 나타날 수 있습니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>턱에서 소리(딱딱, 클릭)나 통증이 있을 때</li>
  <li>입이 잘 안 벌어지거나 한쪽으로만 치우칠 때</li>
  <li>치아갈기나 교합 변화로 저작근에 과부하가 생긴 경우</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>초기에는 물리치료, 근이완, 교합조정 등 보존적 치료로 호전되는 경우가 많습니다. 진단은 임상검사와 필요시 방사선·MRI로 하며, 전문의와 상담해 단계적 치료 계획을 세우는 것이 안전합니다. 증상이 있으면 이음치과 등 전문 기관에서 평가받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='jaw-joint';
UPDATE dict_terms SET full_desc='<h3>저작이란</h3>
<p>저작은 치아와 턱근육, 혀와 침이 함께 작용해 음식을 잘게 부수고 섞는 과정입니다. 단순한 씹기 행위를 넘어 음식의 입자 크기를 줄이고 소화효소와 혼합해 위·장으로 넘어가기 쉬운 상태로 만드는 중요한 구강 기능입니다. 올바른 저작은 소화와 잇몸·치아 건강에 영향을 줍니다.</p>

<h3>원리 또는 특징</h3>
<p>저작은 교합(어금니 맞물림)과 저작근(측두근, 교근, 내외익돌근)의 협동으로 이루어집니다. 혀와 침은 음식 위치 조절과 연화에 기여하고, 반복적인 기계적 분쇄는 음식 표면적을 넓혀 소화 효소의 작용을 돕습니다. 치아 결손이나 보철 상태가 저작 효율에 큰 영향을 줍니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>빠르게 피로해지는 턱이나 저작 시 통증이 있는 경우</li>
  <li>치아 일부가 빠졌거나 보철물이 잘 맞지 않는 경우</li>
  <li>소화불량이나 삼키기 어려움이 반복되는 경우</li>
  <li>노화로 인한 입 근육 약화</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>양쪽을 고루 사용해 천천히 씹는 습관이 중요하며, 저작에 문제가 있으면 치아 보철교정이나 턱관절 평가가 필요할 수 있습니다. 증상이 지속되면 이음치과에서 원인을 진단받아 적절한 치료나 재활을 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='mastication';
UPDATE dict_terms SET full_desc='<p>연하는 음식물이나 침을 입에서 식도로 보내는 일련의 과정입니다. 씹은 음식이 혀의 움직임과 목 뒤쪽 구조의 협동으로 인두를 지나 식도로 안전하게 내려가도록 조절하는 행위로, 의식적으로 할 수도 있고 많은 부분은 자동으로 조절됩니다.</p>

<h3>원리 또는 특징</h3>
<p>연하는 구강기·인두기·식도기의 세 단계로 이루어집니다. 혀와 연구개(목젖), 인두 근육이 순차적으로 수축하고 숨길(성문)이 일시적으로 닫혀 기도로 음식물이 들어가지 않게 합니다. 뇌와 여러 뇌신경이 이 과정을 세밀히 조절합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>삼키기 어려움(연하곤란), 자주 기침하거나 목에 걸림 느낌이 있을 때</li>
  <li>뇌졸중·신경계 질환 등 신경학적 문제 후</li>
  <li>수술·방사선치료 후 구강·인두 기능 변화가 있을 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>연하장애는 흡인성 폐렴이나 영양불량으로 이어질 수 있어 조기 평가가 중요합니다. 영상검사나 내시경 평가로 원인을 찾고, 식이 변경·자세 교정·연하재활 치료로 증상 완화가 가능합니다. 자세한 검진은 이음치과 등 전문기관에서 받아보시길 권합니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='swallowing';
UPDATE dict_terms SET full_desc='<p>개구는 아래턱을 내려 입을 여는 동작으로, 윗앞니 끝과 아랫앞니 끝 사이의 거리를 ''개구량''이라 합니다. 정상 성인은 대략 40~55mm가 보통이며, 이 범위를 벗어나면 식사나 말하기, 치과 치료에 불편이 생깁니다.</p>

<h3>원리 또는 특징</h3>
<p>개구는 측두하악관절(TMJ)과 교근·측두근 같은 저작근의 협동으로 일어납니다. 관절의 구조 이상, 근육 긴장, 염증 등에 따라 개구량이 줄어들 수 있으며 간단한 자가측정으로 초기 판단이 가능합니다.</p>

<h3>관련 상황</h3>
<ul>
  <li>턱관절 장애(TMJ 통증·소리)</li>
  <li>저작근의 과긴장·근육성 통증</li>
  <li>발치나 구강감염 후의 개구 제한</li>
  <li>외상·관절염 등 구조적 문제</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>따뜻한 찜질, 부드러운 스트레칭과 씹기 운동으로 호전되는 경우가 많습니다. 통증이 심하거나 1~2주 이상 지속되면 전문적인 진단과 물리치료, 교합장치 등 치료가 필요하니 이음치과와 같은 전문 기관을 찾아 상담받으세요. 무리한 강제 개구는 악화시킬 수 있습니다.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='mouth-opening';
UPDATE dict_terms SET full_desc='<p>치아 뿌리 끝이나 잇몸 깊은 곳에 세균이 침투해 고름(농)가 모인 상태를 말합니다. 흔히 충치나 잇몸염이 진행되며 발생하고 심한 통증과 국소 부종, 발열을 동반할 수 있어 빠른 처치가 필요합니다. 이음치과에서도 응급으로 다루는 경우가 많습니다.</p>

<h3>원리 또는 특징</h3>
<p>치아 속 신경이나 잇몸 조직에 있던 세균이 염증을 일으켜 고름을 형성합니다. 농양은 국소적으로 압력이 높아져 욱신거리거나 씹을 때 통증이 심해지며, 치료하지 않으면 주변 조직이나 전신으로 퍼질 수 있습니다.</p>

<h3>언제 필요한가 / 적응증</h3>
<ul>
  <li>지속적이거나 심한 치통이 있을 때</li>
  <li>턱·얼굴의 붓기와 발열이 동반될 때</li>
  <li>입 안에서 고름이 보이거나 냄새가 날 때</li>
</ul>

<h3>알아두면 좋은 점</h3>
<p>진단 후 배농(고름 제거), 항생제, 근본 치료(근관치료 또는 발치)가 병행됩니다. 임의로 짜거나 지연하면 감염이 악화될 수 있으니 가급적 빨리 치과 진료를 받으세요.</p>', updated_at=CURRENT_TIMESTAMP WHERE slug='abscess';
